// ═══════════════════════════════════════════════════════════════
//  다이어터 연금술사 — 아바타 렌더러 (SVG 페이퍼돌)
//  5개 바디 파츠(머리·몸통·팔·허벅지·종아리)
//  + 헤어(스타일/컬러) · 표정 · 옷 · 악세사리 · 문신 레이어
// ═══════════════════════════════════════════════════════════════
(function () {
  const D = window.GameData;

  // ─── 기본 팔레트 ───
  const SKIN     = '#ffdcc4';
  const SKIN_SH  = '#f2c6a6';
  const HAIR_DEF = '#7b5640';

  function shade(hex, amt = 26) {
    if (!hex || hex[0] !== '#') return hex;
    const h = hex.replace('#', '');
    const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16);
    let r = (n >> 16) - amt, g = ((n >> 8) & 255) - amt, b = (n & 255) - amt;
    return `rgb(${Math.max(0, r)},${Math.max(0, g)},${Math.max(0, b)})`;
  }

  function getItem(slot, id) {
    const list = (D.WARDROBE && D.WARDROBE[slot]) || [];
    return list.find(x => x.id === id) || list[0] || { kind: 'none' };
  }
  const isNone = it => !it || it.kind === 'none';

  function starPath(cx, cy, r) {
    let d = '';
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + i * Math.PI / 5;
      const rad = i % 2 === 0 ? r : r * 0.45;
      d += (i === 0 ? 'M' : 'L') + (cx + Math.cos(ang) * rad).toFixed(1) + ',' + (cy + Math.sin(ang) * rad).toFixed(1);
    }
    return d + 'Z';
  }

  // ═══════════════════════════════════════════════════════════════
  //  바디 파츠 (피부)
  // ═══════════════════════════════════════════════════════════════
  // ═══════════════════════════════════════════════════════════════
  //  바디 기준 좌표 — 옷은 반드시 이 값을 기준으로 그린다.
  //  (몸을 고치면 옷도 같이 따라가도록. 체형 변화는 몸/옷을 같은 그룹으로
  //   함께 늘리므로, 여기만 맞으면 살이 찌든 빠지든 옷이 몸을 덮는다)
  // ═══════════════════════════════════════════════════════════════
  const BODY = {
    neckY: 96, neckBottom: 116,
    shoulderY: 113,                 // 어깨 윗선
    torsoTopY: 108,                 // 몸통의 맨 윗점 (목 바로 아래, x=100)
    torsoL: 64, torsoR: 136,        // 몸통 최대 폭 (어깨)
    // 어깨 곡선의 제어점 (오른쪽 반. 왼쪽은 x 를 100 기준으로 뒤집는다).
    //
    // ⚠️ **여기 한 곳에서만 정한다.** 그리는 곳(torsoArms)과 재는 곳(torsoTopAtX)이
    // 같은 값을 읽어야 한다 — 두 군데에 적어 두면 어긋나는 순간 넥라인 검사가 헛돈다.
    //
    // ⚠️ **꼭대기가 평평한 것은 어쩔 수 없다.** 목 옆에서부터 기울여 봤더니
    // (첫 제어점을 `[110,109]` 로 당김) **넥라인을 판 옷의 모서리가 몸통 위로 떠서**
    // 그 틈으로 살이 비쳤다 — 퍼프·슬립 드레스에서 좌우 1px 씩.
    // 넥라인은 x 118 언저리까지 파는데, 그 안쪽 어깨선이 108 보다 내려가면
    // 「옷도 몸도 없는 자리」가 생긴다 (checkavatar 의 넥라인 검사가 보는 것과 같은 자리).
    //
    // 그래서 **어깨를 기울이려면 넥라인 표(NECK_CUT)도 같이 좁혀야 한다.** 지금은 안 한다 —
    // 「목이 없어 보이는」 문제는 목 길이(NECK_LIFT)로 풀린다.
    //
    // ⚠️ **어깨는 팔 윗머리보다 높은 채로 팔까지 가야 한다.** 예전 값
    // `[[116,108],[136,117],[136,133]]` 은 x=126 에서 이미 y=114 까지 내려와 있었는데,
    // 팔의 둥근 윗머리는 y=110.25 로 그보다 **위**였다. 그래서 실루엣이
    // 「어깨 → 아래로 파임 → 팔이 다시 솟음」 이 되어 **3.75px 짜리 홈**이 생겼다.
    // 어깨 봉우리와 팔 봉우리가 따로 놀아 「관절이 분리된 인형」처럼 보이던 자리다.
    //
    // 지금 값은 목에서 팔까지 **사선으로 눕는다.** 예전 값 `[[122,108],[136,111],[136,120]]`
    // 은 x=136 까지 y 108~111 로 거의 «평평하게» 가다가 거기서 수직으로 떨어져,
    // 어깨가 **직각으로 꺾이는 선반**이었다 — 목 밑부터 허리까지가 관절 없는 한 덩어리로
    // 보이던 것(라운드 숄더)이 여기서 왔다.
    //
    // ⚠️ **어깨선만으로는 여기까지가 한계였다.** 더 눕히면 팔의 둥근 마개 꼭대기
    // (`armY`)보다 낮아져 홈이 생긴다 — 그래서 **팔을 4px 내리고**(114 → 118)
    // 그만큼 더 눕혔다. 위쪽 실루엣이 x112 의 y106 에서 x139 의 y120.8 까지
    // 한 번도 되솟지 않고 내려간다 (예전에는 y106 → y117 이었다).
    //
    // ⚠️ **팔을 넓혀서 어깨를 만들려는 쪽이 아니다.** 삼각근을 15→19 로 넓혀 봤더니
    // 옷이 그것을 덮으려면 어깨도 같이 넓혀야 하는데, 어깨를 팔의 제 폭까지 넓히면
    // **팔의 둥근 마개 위로 부리처럼** 솟았다 (`ARM_W` 의 주의를 볼 것).
    // 어깨선을 눕히는 쪽은 폭이 안 변해서 옷 커버리지가 한 톨도 안 흔들린다.
    //
    // 팔이 이어받는 지점에서 어깨가 팔 봉우리와 비슷한 높이라 **홈이 안 생긴다.**
    // (checkavatar 의 「어깨 홈」 검사가 이 값을 지킨다 — 1px 을 넘기면 실패한다)
    // ⚠️ 마지막 점(136,120)은 **어깨 끝**이다. 몸통 path 의 왼쪽 되돌아오는 자리도
    // 이 값을 읽는다 — 예전에는 133 이 손으로 박혀 있어 좌우가 어긋날 뻔했다
    shoulderC: [[122, 108], [136, 112], [136, 122]],
    // 허리 높이. 예전에는 196 이라 잘록한 지점이 골반 바로 위까지 내려와,
    // 상체가 길고 허리가 없어 보였다. 그 뒤 184 로 올렸고, 지금은 **황금비**로 다시 잡았다.
    // **옷의 허리선도 전부 이 값을 본다** — 여기만 고치면 상의·치마·드레스가 같이 따라온다.
    //
    // 황금비: 정수리(24)~바닥(342) 을 상체 1 : 하체 1.618 로 나누면
    // 24 + 318/2.618 ≈ **145** 가 허리다. 그런데 145 는 갈비뼈 한가운데라,
    // 거기서 잘록해지면 몸통이 위아래로 반 접힌 것처럼 보여 쓸 수 없었다.
    // (턱 105 부터 재면 105 + 237/2.618 ≈ 195 로 지금보다 **내려간다** — 머리를 빼면
    //  기준이 뒤집히므로, 이 그림에서 「상체」는 정수리부터다)
    // 그래서 **절충으로 20px 만 올렸다**(184 → 164). 그림이 견디는 한계선이다.
    //
    // ⚠️ **허리를 옮기면 그 아래가 전부 따라 올라간다.** 허리만 올리면 엉덩이가
    // 제자리에 남아 「허리와 골반 사이가 늘어난」 몸이 된다. 바닥(342)은 고정이므로
    // 허리 아래 구간이 158 → 178 로 늘어난 배율 k = 178/158 ≈ 1.1266 을
    // **엉덩이·허벅지·종아리·발·무릎 기준선에 전부 같이 먹인다** (y' = 342 - (342-y)·k).
    // 결과적으로 다리가 그만큼 길어진다 — 황금비로 옮기는 목적 자체가 이것이다.
    waistY: 164, hipY: 198,
    // 허리 반폭 (waistY 에서 중심선 100 으로부터의 거리). '허리' 배율이 이 값을 늘이고 줄인다.
    // **옷의 허리도 이 값을 따라간다** — 예전에는 드레스 허리가 78~122 로 박혀 있어
    // 몸통 허리(70~130)보다 좁았고, 그래서 허리 살이 드레스 밖으로 나왔다.
    waistHalf: 30,
    // 엉덩이 — 허리보다 넓어야 여성 실루엣이 산다. '엉덩이' 배율이 이 값을 늘이고 줄인다.
    // 예전에는 몸통이 hipY 에서 한 점(100,214)으로 모여, 허벅지(78~122)와 만나는 곳이
    // 뚝 끊겨 보였다. 둥근 엉덩이가 그 사이를 잇는다.
    //
    // ⚠️ **허벅지 윗머리(`thighTop` 의 기본값 38)와 같은 값이어야 한다.**
    // 이 값이 그보다 낮으면 `hipBaseHalf` 의 허벅지 하한이 늘 이겨 **슬라이더가
    // 통째로 죽는다** — 34 였을 때 20%~150% 가 전부 38.0~38.6px 로 나와,
    // 엉덩이를 아무리 줄여도 좌우 폭이 하나도 안 변했다.
    hipHalf: 38,
    hipBottom: 214,                 // 엉덩이 아래 끝 (허벅지와 겹쳐 이어진다)
    thighHalf: 22,                  // 허벅지 바깥 (78 / 122)
    // 팔: (x, y=120) 에서 시작하는 폭 armW 의 막대를 어깨 기준으로 회전.
    // **팔을 옮기면 소매도 같이 따라온다** — armShape() 이 이 값만 본다.
    // 몸통 쪽으로 조금 붙이고(52→55) 벌어짐을 줄였다(7°→4°). 예전에는 날씬할 때
    // 몸통은 허리로 좁아지는데 팔은 바깥으로 벌어져, 팔이 몸에서 떨어져 보였다.
    // 팔은 **몸통에 2px 물려 둔다.** 몸통 옆선은 어깨(133)에서 허리(184)로 좁아지는데
    // 팔은 armRot 만큼 바깥으로 기울어 내려간다 — 둘이 반대로 가서 y 170 언저리에서
    // **1px 짜리 틈**이 생겼다. 같은 살색이라 색은 안 튀는데 배경이 실처럼 비쳐
    // 「팔이 몸에서 떨어져 있다」로 읽혔다. 회전축(armPivot)도 같이 옮겨야 기울기가 그대로다.
    // **팔 위 끝은 어깨선(108)보다 조금 아래(114)에서 시작한다.**
    // 예전에는 120 → 112 였다. 120 은 몸통의 어깨가 먼저 옆으로 뻗고 그 아래에서 팔이
    // 따로 시작해 계단이 졌고(「승모근이 불쑥」), 112 는 어깨선이 **평평한 채로** 팔에
    // 닿아 어깨와 팔이 거의 직각으로 보였다.
    // 지금은 어깨선을 **사선으로 눕히고**(shoulderC) 팔을 그 끝에 맞춰 내렸다 —
    // 승모근이 목에서 비스듬히 흘러내려 팔의 둥근 마개로 이어진다.
    // ⚠️ **어깨선(108)까지 올리면 안 된다** — 마개 꼭대기가 몸통보다 높아져 **혹이 솟는다.**
    //
    // 지금은 **118** 이다 (114 에서 4px 더 내렸다). 어깨선을 더 눕히려 했더니
    // **팔의 둥근 마개 꼭대기가 벽이었다** — 마개는 `armY` 에 붙박여 있어서, 어깨선이
    // 그보다 낮아지는 순간 「어깨 → 파임 → 팔이 다시 솟음」 홈이 생긴다.
    // 그래서 **팔을 먼저 내리고 그만큼 어깨선을 더 눕혔다.**
    //
    // ⚠️ **7px 까지 내리면 무너진다** — 121 로 해 봤더니 치마가 팔을 덮고(37건)
    // 상의·드레스 커버리지가 통째로 깨졌다. 4px 이 이 그림이 견디는 폭이다.
    // 손목 자리는 그대로 둔다 (armY + armH = 214 로 같다)
    armX_L: 59, armX_R: 126, armY: 114, armH: 100, armW: 15,
    armRot: 4, armPivotL: 66, armPivotR: 134, armPivotY: 130,
    // 팔꿈치 — 팔은 윗팔/아랫팔 두 마디다. 아랫팔이 몸 쪽으로 살짝 굽는다.
    //   elbowT   팔 길이에서 팔꿈치가 있는 비율 (해부학적으로 윗팔이 조금 길다)
    //   elbowRot 아랫팔이 안쪽으로 굽는 각도. **9° 를 크게 넘기지 말 것** —
    //            더 굽히면 손이 치마 뒤로 완전히 숨고, 아랫팔이 커버리지 검사의
    //            몸통 창(x 72~128)에 들어가 위반으로 잡힌다. 지금은 팔 자체가
    //            4°(armRot) 바깥으로 기울어 있어 굽힘과 상쇄돼 2~4px 여유가 있다
    // 팔 위 끝을 8px 올리면서 비율도 다시 잡았다 — 팔꿈치의 **절대 높이는 그대로**다
    // (112 + 102×0.594 ≈ 120 + 94×0.56)
    // ⚠️ **팔꿈치의 «절대 높이»를 그대로 둔다.** 팔 위 끝을 내리면서 길이가 줄었는데
    // 비율을 그대로 두면 팔꿈치가 1.6px 밀려 **이음매에 0.75px 턱**이 났다 (팔 200%).
    // 118 + 96×0.577 = 173.4 로 예전(114 + 100×0.594)과 같은 자리다
    elbowT: 0.594, elbowRot: 9,
    ankleY: 331,
    // 발(그리고 그것을 덮는 구두)의 중심 높이. 허리를 올리면서 다리가 길어져 1px 내려왔다.
    // **한 곳에만 적는다** — 예전에는 legs() 와 renderShoes() 에 335 가 따로 박혀 있어,
    // 한쪽만 옮기면 구두가 발을 1px 비껴 덮어 살색 실선이 남는다
    footY: 334,
  };
  // 옷이 몸을 확실히 덮도록 주는 여유 (한쪽당 px)
  const CLOTH_PAD = 3;
  // 옷의 **어깨 윗선**. 몸통 맨 위(108)보다 위여야 한다 —
  // 예전에는 옷이 110 에서 시작해 몸통보다 2px 아래였고, 그 사이로 살색 띠가
  // 목 밑을 가로질렀다. 눈에는 '1px 어긋난 선' 으로만 보여서 오래 남아 있었다.
  // (커버리지 검사도 y 112 부터 보고 있어서 이 띠를 통째로 지나쳤다)
  const CLOTH_TOP_Y = BODY.torsoTopY - 1;
  // 맨팔에만 주는 옅은 테두리. 팔과 몸통이 같은 살색이라, 통통해져 몸통이 넓어지면
  // 팔이 몸통에 묻혀 실루엣이 사라졌다. 얇은 선 하나로 겹쳐도 팔이 읽힌다.
  // (소매를 입으면 옷 색이 대비를 만들어 주므로 옷에는 넣지 않는다)
  // 맨팔에는 **테두리를 두르지 않는다.**
  //
  // 예전에는 살색 그림자선(SKIN_SH)을 팔 둘레에 둘렀는데, 그 선이 어깨에서도 이어져
  // **팔이 몸에서 떨어져 붙인 것처럼** 보였다. 어깨 실루엣에는 테두리가 없으므로
  // 없는 쪽으로 맞춘 것이다 — 같은 살색끼리는 선 없이 그냥 이어지는 편이 몸으로 읽힌다.
  // (선을 지우면 팔꿈치 이음매를 덮던 덧칠도 필요 없어진다 — armShape 참고)
  const ARM_EDGE = '';

  // ─── 등신 비율 기준값 ───
  // 머리(머리카락 끝 ~ 턱) 높이와 몸(어깨 ~ 발) 길이. 이 둘의 비가 등신을 만든다.
  // ─── 그림 상자 ─────────────────────────────────────────────
  //
  // ⚠️ **가로를 200 → 244 로 넓혔다.** 통통 최대는 몸이 가로로 1.36배가 되는데
  // (`bodyScaleX`), 200 짜리 상자에서는 허벅지 하나가 폭의 90% 를 먹어 **엉덩이가
  // 허벅지보다 넓어질 자리가 8px 밖에 없었다** — 「빌렌도르프의 비너스」 같은
  // 난형 실루엣이 수학적으로 안 나오는 상태였다. 굵기를 조금만 키워도 상자에
  // 잘려서, 그동안 늘 반대로 «허벅지를 깎아» 맞추고 있었다.
  //
  // ⚠️ **중심선 100 은 그대로 둔다.** 왼쪽으로 14 를 열어 두면 −14 ~ 214 라
  // 100 이 정확히 한가운데다 — 모든 좌표·세이브·옷이 그대로 산다.
  //
  // ⚠️ **위로도 18 을 열었다** (`y: -18` · 높이 348 → 366). 머리는 목에서 위로
  // 자라는데 상자 위가 y=0 이라, 얼굴 배율의 상한이 **114%** 로 묶여 있었다.
  // ⚠️ **머리 모양까지 재야 한다.** 올림머리(`hair_bun_*`)는 쪽이 더 높다 —
  // 지금 제일 높이 올라가는 것은 **올림머리 × 얼굴 115% × 날씬**의 −12 다
  // (그 올림머리는 예전 상한 114% 에서도 이미 8.3px 잘리고 있었다.
  //  「그림 상자」 검사가 민머리 하나로만 재고 있어서 아무도 못 봤다).
  // ⚠️ **115% 를 넘으면 오히려 내려온다** — 몸이 줄면서 목이 내려오기 때문이다
  // (`bodyShrink`). 그래서 150% 를 열면서도 상자는 18 만 열면 된다.
  // 한때 54 까지 열었는데(몸 축소 전) 그만큼 화면이 좁아져서 되돌렸다.
  // ⚠️ **세로는 «인물 크기»에 바로 걸린다.** 가로와 달리 `.avatar-svg` 가 높이로
  // 크기를 잡기 때문이다 — 그래서 `style.css` 의 `height` 도 312 → **328** 로 같이
  // 올렸다 (312/348 = 328/366 = 0.8962). 한쪽만 고치면 인물이 통째로 작아진다.
  // 마이 룸의 인트로 공주(`game.js` 의 `princessFigure`)도 같은 상자를 써야 한다 —
  // 거기만 348 로 남으면 공주가 아바타보다 10% 커진다.
  //
  // ⚠️ **검사기는 아직 «200 폭 × 348 높이» 좌표로 잰다.** `checkavatar` 가 캔버스에
  // 그릴 때 이 값만큼 밀어 그려서 캔버스의 0..200 · 0..348 이 예전과 같은 자리를
  // 가리킨다 (`__drawAvatar`). 그래서 스무 개 넘는 검사의 좌표를 하나도 안 고쳤다.
  const VB = { x: -22, y: -18, w: 244, h: 366 };
  const HEAD_H   = 84;    // 현재 아트의 머리 높이 (y 21 ~ 105)
  const BODY_SPAN = 229;  // 어깨(113) ~ 바닥(342)
  const FLOOR_Y  = 342;   // 발이 닿는 높이 (여기를 축으로 몸을 늘린다)
  const NECK_Y   = 112;   // 머리를 얹는 목 위치
  // ─── 목 길이 ───
  //
  // **날씬할수록 목을 길게 뺀다.** 안 그러면 날씬한 몸에서 목이 사라진다.
  //
  // 왜 사라지나: 머리는 NECK_Y(112)를 축으로 줄어드는데 **턱(105)이 축보다 위**에 있어서,
  // 머리가 작아질수록 턱이 112 쪽으로 끌려 내려온다. 몸통 윗선은 바닥(342)을 축으로
  // 늘어나 거의 안 움직인다. 그래서 턱과 어깨 사이가 **통통 5.8px · 날씬 2.8px** 로
  // 반 토막이 났고, 목이 없어 어깨가 솟아 보였다.
  //
  // ⚠️ **축을 턱으로 옮기는 것으로는 안 고쳐진다.** 그렇게 하면 날씬 쪽은 2.8→3.0 으로
  // 그대로인데(머리 배율이 0.979 라 축을 옮겨도 0.15px 차이다) 통통 쪽만 5.8→3.6 으로
  // 짧아진다 — 멀쩡하던 쪽을 나쁜 쪽에 맞추는 셈이다. 실제로 해 보고 눈으로 확인했다.
  //
  // 그래서 **길이를 직접 주는 손잡이 하나**를 둔다. 머리를 그만큼 위로 올린다.
  // 통통은 0 (지금 모습 그대로 · 3등신은 목이 짧아야 귀엽다), 날씬은 NECK_LIFT.
  // 결과: 날씬 8.8px · 중간 7.3px · 통통 5.8px — 날씬할수록 목이 길다 (4등신)
  // ⚠️ **통통 쪽에도 조금은 줘야 한다.** 예전에는 `(1 - w)` 라 통통에서 정확히 0 이었는데,
  // 「3등신은 목이 짧아야 귀엽다」는 그때의 판단이었다. 머리를 줄여 3.3등신으로 옮기자
  // **목이 4.3px 밖에 안 남아**(`checkavatar` 의 「목」은 5px 이 바닥이다) 턱이 어깨에
  // 얹혔다. `1 - NECK_FAT * w` 로 바닥을 깔아 둔다 — 통통에서도 2px 은 올린다.
  const NECK_LIFT = 10, NECK_FAT = 0.8;
  // 몸통 배율로 가늘게 했을 때 더 빼 주는 몫 (100% 이상은 0 — 기본 체형은 그대로다)
  const NECK_LIFT_TORSO = 8;
  // 머리 크기 배율 — 통통 3등신 / 날씬 4등신 (귀여운 체형)
  // 등신 = 전체높이 / (HEAD_H × k) 이고 전체높이도 k 를 따라 조금 움직이므로
  // 두 측정점에서 관계식(전체높이 ≈ 322 + 7k)을 세워 역산한 값이다.
  // **이 값을 바꾸면 등신이 바뀐다 — 실측으로 확인할 것.**
  // ⚠️ **통통 쪽을 한 번 낮췄다** (1.314 → 1.15 · 2.91등신 → 3.3등신).
  // 「몸이 뚱뚱하고 얼굴이 커졌을 때 비율이 이상하다」는 신고였고, 재어 보니 실제로
  // **머리가 키의 34%** 였다. 게다가 머리가 커질수록 `bodyKy` 가 몸을 «세로로 눌러»
  // (0.885) 다리까지 짧아져서 — 위는 부풀고 아래는 눌린 모양이 됐다.
  // 머리를 줄이면 그 몫이 그대로 몸 길이로 간다 (bodyKy 0.885 → 0.945).
  const HEAD_K_FAT  = 1.15;
  const HEAD_K_SLIM = 0.979;
  const lerpN = (a, b, t) => a + (b - a) * t;

  // ─── 파츠별 미세 조정 (임시 · 테스트용) ───────────────────────
  // build(outfit, body, tune) 의 tune 으로 파츠 굵기/크기를 따로 조절한다. 1 = 기본.
  // 팔·허벅지·종아리는 좌우가 각자 제자리에서 굵어지도록 **자기 중심**을 축으로 늘린다.
  // (x=100 을 축으로 하면 굵어지는 대신 바깥으로 벌어져 어깨에서 떨어져 보인다)
  const TUNE_KEYS = ['torso', 'waist', 'hip', 'arm', 'thigh', 'calf', 'face'];
  function tuneOf(tune, k) {
    const v = tune && Number(tune[k]);
    return Number.isFinite(v) && v > 0 ? v : 1;
  }
  // ─── 배율이 살에 얹히는 정도는 부위마다 다르다 ────────────────
  //
  // 슬라이더는 부위마다 0.5~2 로 같은데, **같은 200% 라도 자연스러운 두께는 다르다.**
  // 눈으로 맞춘 값이다 — 200% 에서 엉덩이는 예전의 0.8배.
  //
  // ⚠️ **100% 는 어느 부위도 안 건드린다.** 기본 체형이 한 톨도 안 움직여야 한다.
  // 그래서 100% 를 **넘는 만큼(k−1)에만** 곱한다: k' = 1 + (k−1)·gain.
  //   허벅지 200% : 1 + 0.95 = 1.95 → 살 36 → 70.2
  //   엉덩이 200% : 1 + 0.27 = 1.27 → 34 → 43.2  (예전 68 의 0.64배 — 두 번 깎았다)
  //   종아리 200% : 1 + 0.95 = 1.95 → 살 18 → 35.1
  //
  // ⚠️ **허벅지와 종아리는 같은 몫을 탄다.** 예전에는 허벅지만 0.444 였는데,
  // 슬라이더를 둘 다 끝까지 올리면 허벅지는 143.8% 인데 종아리가 159.3% 라
  // **다리 위쪽이 아래쪽보다 가늘어 보였다** — 개발용 패널의 숫자에도 그렇게 찍혔다.
  // 두 슬라이더의 상한이 똑같이 200% 이므로 얹히는 몫도 같아야 눈이 납득한다.
  //
  // ⚠️ **100% 아래는 그대로 둔다.** 얇은 쪽은 이미 맞춰 놓은 그림이라 건드릴 이유가 없다.
  // ⚠️ **`tuneOf` 를 그냥 바꾸면 안 된다.** 슬라이더 값 자체를 쓰는 곳(옷이 어느 파츠를
  // 따라갈지 고르는 `tuneMax` · 세이브·화면의 % 표시)은 사람이 고른 값 그대로여야 한다.
  // **살의 양을 셈하는 자리에서만** `fatOf` 를 쓴다.
  // ⚠️ **끝까지 올렸을 때를 한 번 더 키웠다** (0.444 → 0.87 · 살의 양이 1.28배).
  // 「최대인데도 더 뚱뚱해져도 되겠다」는 판단이었다 — 100% 는 여전히 안 움직인다.
  //
  // ⚠️ **여기가 그림 상자의 한계다.** 원래는 1.3배로 키우려 했는데,
  // `viewBox` 가 200 인데 **통통 최대는 이미 191.5 까지 차 있었다** — 몸무게가
  // 가로로 1.36배 늘리기 때문이다(`bodyScaleX`).
  // 한동안 0.95 로 두었는데, `thighOuterAt` 이 **그리는 곡선을 그대로 풀도록**
  // 고쳐지면서 허벅지가 실제로는 더 굵다는 것이 드러났고 — 엉덩이는 그것을
  // 덮어야 하므로 반폭이 2.2px 늘어 상자 밖으로 나갔다(39~65줄이 잘렸다).
  // **0.87 이 지금 안 잘리는 가장 큰 값이다** (오른쪽 끝 198.8/200 · 여백 1.3px).
  // 더 키우려면 `viewBox` 를 「-12 0 224 342」 처럼 **양옆으로 넓혀야** 한다
  // (중심선 100 을 안 옮기는 것이 요령이다 — 옮기면 모든 좌표가 어긋난다).
  //
  // ⚠️ **엉덩이의 몫(0.27 → 0.5)은 슬라이더를 살리려고 올렸다.** 엉덩이 반폭에는
  // 「허벅지 윗머리를 덮어야 한다」는 바닥이 있는데, 위의 `thighOuterAt` 수정으로
  // 그 바닥이 올라가 **100% 와 125% 가 둘 다 40.3px** 이 됐다 — 슬라이더를
  // 한 칸 밀어도 몸이 하나도 안 변한다. 몫을 키워 바닥 위로 다시 띄웠다.
  // ⚠️ **팔에도 몫을 붙였다** (`arm: 1.32`). 슬라이더 상한이 150% 뿐이라 그냥 곱하면
  // 끝까지 올려도 «가는 막대»를 못 벗어난다 — 통통한 몸 옆에서 팔만 실처럼 남았다.
  // 100% 를 넘는 만큼에만 얹는다. 100% 이하는 한 톨도 안 변한다.
  // ⚠️ **4.4 → 3.0 → 1.32 로 두 번 내려왔다.** 150% 에서의 두께가
  // 38.8px → 30.8 → **21.3px** 이다(기본 13.5px 의 1.58배).
  // 마지막 값은 「지금 122% 인 굵기가 150% 가 되도록」이라 — 옛 122% 의 배율
  // (1 + 0.22 × 3.0 = 1.66)이 새 150% 의 배율이 되게 풀면 1.32 다.
  //
  // ⚠️ **엉덩이의 몫은 0.62 → 0.42 로 다시 내렸다** (「엉덩이 최대일 때 가장 좌우로
  // 튀어나온 부분을 20% 정도 작아지게」). 재는 자리는 **총 반폭이 아니라 «허리 위로
  // 튀어나온 몫»** 이다 — 총 반폭을 20% 깎으면 150% 가 100% 보다 좁아져
  // (49.5 × 0.8 = 39.6 < 40.8) **슬라이더가 뒤집힌다.**
  // 기본 몸 · 엉덩이 150% 에서 허리 30.0 · 봉우리 49.5 → **45.8** (몫 19.5 → 15.8).
  const TUNE_GAIN = { thigh: 0.92, hip: 0.42, calf: 0.92, arm: 1.32, waist: 0.6 };
  function fatOf(tune, k) {
    const v = tuneOf(tune, k), g = TUNE_GAIN[k];
    return (g == null || v <= 1) ? v : 1 + (v - 1) * g;
  }
  // ─── 슬라이더가 «상한까지» 얼마나 갔는가 (0 = 100% · 1 = 그 부위의 끝) ──
  //
  // ⚠️ **`tuneOf(...) - 1` 을 그대로 0~1 로 쓰면 안 된다.** 그 식은 상한이 200% 이던
  // 시절에 맞춰 쓴 것이라, 상한을 150 으로 내리자 **끝까지 밀어도 0.5 밖에 안 됐다** —
  // 허벅지의 볼록함(`THIGH_BULGE`)과 엉덩이가 허벅지를 덮는 몫(`HIP_OVER`)이
  // 소리 없이 절반으로 줄었다. 화면에서는 「허벅지가 직선 사선으로 떨어진다」·
  // 「엉덩이가 마름모」로 보였고, 수치로 재 보니 y226~270 이 곡률 0(직선)이었다.
  // **상한을 바꾸면 여기 표도 같이 바꾼다** — `checkavatar` 가 game.js 의
  // `TUNE_PARTS` 와 대조해서, 어긋나면 잡아 준다.
  const TUNE_MAX = { torso: 1.5, waist: 1.5, hip: 1.5, arm: 1.5, thigh: 1.5, calf: 1.5, face: 1.5 };
  function overOf(tune, k) {
    const m = TUNE_MAX[k] || 2;
    return Math.max(0, Math.min(1, (tuneOf(tune, k) - 1) / (m - 1)));
  }
  // 몸무게(w: 0 날씬 ~ 1 통통)가 만드는 **가로 배율**.
  // `build()` 의 몸 변환이 이 값을 쓴다 — 식을 두 군데 두면 개발용 패널이
  // 그리는 것과 다른 숫자를 말하게 된다
  const BODY_FAT_X = 0.36;
  const bodyScaleX = w => 1 + BODY_FAT_X * Math.max(0, Math.min(1, Number(w) || 0));

  // ─── 머리가 커지면 몸을 조금씩 줄인다 ────────────────────────
  //
  // 얼굴 상한을 150 까지 열고 나니 **화면이 좁아졌다.** 머리만 커지는데 몸은 그대로라
  // 인물이 통째로 자리를 더 먹는다 — 마이 룸에서 방이 거의 안 보였다.
  //
  // 그래서 **115% 를 넘는 만큼 몸을 줄인다.** 115% 까지는 한 톨도 안 변하고
  // (예전 상한 114 언저리까지가 지금까지의 그림이다), 150% 에서 **0.8배**다.
  // 몸이 줄면 목도 따라 내려오므로 **머리도 같이 내려간다** — 그 몫이 `headDrop` 이다.
  //
  // ⚠️ **가로·세로를 같은 값으로 줄인다.** 세로만 줄이면 다리만 짧아진 난쟁이가 되고,
  // 가로만 줄이면 홀쭉해진다. 「몸이 작아진다」는 둘이 같이 줄어드는 것이다.
  // ⚠️ 축은 **바닥**(`FLOOR_Y`)이다 — 발이 바닥에서 떨어지면 공중에 뜬다.
  const FACE_SHRINK = { from: 1.15, to: 1.5, min: 0.8 };
  function bodyShrink(kFace) {
    const t = (kFace - FACE_SHRINK.from) / (FACE_SHRINK.to - FACE_SHRINK.from);
    return 1 - (1 - FACE_SHRINK.min) * Math.max(0, Math.min(1, t));
  }

  // 이 부위가 **처음 몸**(슬라이더 100% · 통통 `bodyLevel` 1)에 견줘 몇 배인가.
  // 개발용 「바디 파츠 조절」이 물약·폭식으로 몸이 얼마나 달라졌는지 보여 주는 데 쓴다.
  //
  // ⚠️ 식을 밖에서 다시 쓰지 않는다 — 살의 양은 `fatOf`(부위마다 얹히는 정도가
  // 다르다), 몸무게는 `bodyScaleX` 다. 옮겨 적으면 패널이 그림과 다른 말을 한다
  function partRatio(k, tune, w) {
    return fatOf(tune, k) * bodyScaleX(w) / bodyScaleX(1);
  }

  // 가로(굵기)만 늘리는 변환 — ax 를 축으로
  function sx(k, ax) {
    return k === 1 ? '' : ` transform="translate(${ax},0) scale(${k.toFixed(3)},1) translate(${-ax},0)"`;
  }
  // 전체 크기를 늘리는 변환 — (ax,ay) 를 축으로
  function su(k, ax, ay) {
    return k === 1 ? '' : ` transform="translate(${ax},${ay}) scale(${k.toFixed(3)}) translate(${-ax},${-ay})"`;
  }
  // 옷도 자기가 덮는 파츠를 따라 커진다 — 살이 옷 밖으로 나오지 않게.
  // 여러 파츠를 덮는 옷(치마·바지·드레스)은 그중 **가장 큰 배율**을 따른다.
  // 하나만 따라가면 나머지 파츠에서 살이 삐져나온다.
  function tuneMax(tune, keys) {
    return keys.reduce((m, k) => Math.max(m, tuneOf(tune, k)), 1);
  }
  // 도형 묶음을 가로로 늘려 감싼다 (배율이 1이면 그대로 둔다)
  function wrapX(s, k, ax) {
    return (!s || k === 1) ? s : `<g${sx(k, ax)}>${s}</g>`;
  }
  // 도형 묶음을 전체 크기로 늘려 감싼다
  function wrapU(s, k, ax, ay) {
    return (!s || k === 1) ? s : `<g${su(k, ax, ay)}>${s}</g>`;
  }

  // 팔과 소매를 **같은 좌표에서** 그린다.
  // 예전에는 소매 좌표가 renderTop·renderDress 에 그대로 박혀 있어서,
  // 팔 위치나 각도를 고치면 소매만 제자리에 남아 어긋났다. BODY 하나만 고치면 되게 모았다.
  //
  // 팔은 **윗팔/아랫팔 두 마디**고 팔꿈치에서 안쪽으로 굽는다. 곧은 좌표(armY 에서 아래로)로
  // 그린 뒤 아랫팔 조각에만 팔꿈치 회전을 하나 더 건다. 소매·장갑도 이 함수를 지나므로
  // 옷이 팔꿈치를 따로 알 필요가 없다 — 긴 소매는 저절로 팔꿈치에서 같이 굽는다.
  //
  //   side  'L'|'R' · pad 팔보다 얼마나 넓게(소매) · h 길이 · extra 덧붙일 속성
  //   opts.extra 덧붙일 속성 · opts.yFrom 위쪽을 잘라 아래 구간만 그림 (장갑)
  // ─── 팔도 원통이 아니다 ────────────────────────────────────
  //
  // 예전에는 윗팔·아랫팔이 **둥근 네모(rect)를 가로로 늘린 것**이라, 굵게 하면
  // 팔꿈치도 손목도 같이 굵어져 원통 두 개가 됐다. 다리와 같은 규칙으로 고친다:
  // **살(어깨·팔뚝)은 배율을 타고 관절(팔꿈치·손목)은 덜 탄다.**
  // ⚠️ **삼각근을 넓혀서(15 → 19) 어깨를 만들려다 되돌렸다.** 그림은 좋아졌는데
  // 팔이 넓어진 만큼 **어깨도 넓혀야** 옷이 그것을 덮는데(`shoulderSquash`),
  // 어깨를 팔의 «제 폭»까지 넓히면 이번에는 팔의 **둥근 마개 위로 부리처럼** 솟는다
  // (팔 200% 에서 4.0px). 팔 위 끝은 아직 제 폭이 아니기 때문이다.
  // 라운드 숄더로 보이던 것은 결국 **어깨선이 직각이던 것**이라, 그쪽(`shoulderC`)만
  // 눕혀서 해결했다. 여기를 건드리려면 어깨가 팔을 «높이마다» 따라가야 한다.
  // ⚠️ **한 번 15% 가늘게 했다** (어깨 15 → 12.75 · 팔꿈치 12 → 10.2 · 손목 9.5 → 8.08).
  // 「팔이 다리보다 두껍다」를 고친 뒤에도 굵어 보인다는 판단이었다.
  // 실루엣으로는 팔 100% 가 17 → 15px 이 됐다 (그늘·관절이 배율을 덜 타서 12% 다).
  //
  // ⚠️ **여기를 깎으면 어깨가 팔 밖으로 나온다.** 팔이 목 옆을 가려 주고 있어서,
  // 몸통 50% · 팔 75% 에서 목 자락이 1.5px 튀어나왔다 (`checkavatar` 의 「어깨 부리」).
  // `shoulderSquash` 의 마개 몫을 2 → 3.4 로 키워서 어깨가 따라 들어오게 했다 —
  // **기본 체형은 그대로다**(거기서는 여전히 팔이 어깨보다 바깥이다).
  // 손도 같이 봐야 한다 — 손은 손목 폭을 따라가므로(`HAND_W`) 팔을 깎으면 같이 얇아진다.
  // ⚠️ 그러고도 한 번 **더 10%** 깎았다 (12.75 → 11.48 · 10.2 → 9.18 · 8.08 → 7.27).
  //   실루엣: 팔 50% 8.5 → 7.5 → 6.8px · 100% 17 → 15 → 13.5px
  // ⚠️ 손목만 7.27 → 8.7 로 조금 굵혔다. **손이 팔보다 넓어 «혹»처럼 보였다** —
  // 기본 체형에서 엉덩이(39.3) → 팔(38.3) → 손(39.0) 으로 한 번 들어갔다 다시
  // 나와서, 옆구리에 작은 돌기 둘이 생겼다 (「엉덩이 중간이 뾰족하다」로 신고받았는데
  // 조각별로 재어 보니 엉덩이가 아니라 손이었다). 손목을 굵히면 그 골이 메워진다.
  const ARM_W = { shoulder: 11.48, elbow: 9.18, wrist: 8.7 };
  // 몸 쪽으로 깔아 두는 그늘의 폭.
  // ⚠️ **배율을 같이 타야 한다.** 2.5px 붙박이였는데, 그러면 팔이 가늘어질수록
  // 그늘의 «몫»이 커진다 — 팔 50% 에서 7.5px 짜리 팔에 2.5 가 붙어 실루엣이 33% 나
  // 두꺼워졌고, 그래서 **모든 파츠를 최소로 하면 팔이 종아리보다 두꺼웠다.**
  const ARM_SHADE = 2.5;
  const armShadeW = k => +(ARM_SHADE * Math.min(1.2, Math.max(0.45, k))).toFixed(2);
  const ARM_OUTLINE = 0.9;               // 옷과 같은 색으로 겹칠 때 두르는 윤곽선의 반두께
  const ARM_SHADE_FROM = 10;             // 팔 위 끝에서 이만큼 내려와서 시작한다
  // ⚠️ **팔의 몫은 슬라이더 상한(150%)에서 멈춘다.** `TUNE_GAIN.arm` 이 4.4 라
  // 200% 를 넣으면 5.4배가 되는데, 팔 슬라이더는 150% 까지밖에 안 올라간다 —
  // 닿을 수 없는 값에서 팔꿈치 이음매가 7.5px 씩 벌어졌다.
  const ARM_K_MAX = 1 + (1.5 - 1) * 1.32;
  const armK = tune => Math.min(fatOf(tune, 'arm'), ARM_K_MAX);
  function armWidths(k) {
    const S = ARM_W.shoulder * k;
    // 관절도 살이 붙긴 하지만 **덜 붙는다.** 그리고 마디보다 굵어질 수는 없다
    // ⚠️ **관절이 마디를 너무 안 따라가면 이음매가 튄다.** 팔에 몫이 붙어
    // 어깨가 3.2배가 되는데 팔꿈치는 1.9배뿐이라, 윗팔이 팔꿈치로 급하게 좁아져
    // 굽힘 자리에서 옆선이 1.5px 튀었다 (팔꿈치 0.6+0.4k → 0.15+0.85k · 손목 0.7+0.3k → 0.45+0.55k)
    const E = Math.min(ARM_W.elbow * (0.15 + 0.85 * k), S * 0.9);
    const W = Math.min(ARM_W.wrist * (0.45 + 0.55 * k), E * 0.9);
    return { S: S, E: E, W: W };
  }
  // 팔 위 끝(armY)에서 dist 만큼 내려간 곳의 **반폭** (pad = 소매가 팔보다 넓은 만큼)
  function armHalf(dist, k, pad) {
    const B = BODY, up = B.armH * B.elbowT, wd = armWidths(k);
    const inUp = dist <= up;
    const a = inUp ? wd.S : wd.E, b = inUp ? wd.E : wd.W;
    const t = inUp ? dist / up : (dist - up) / (B.armH - up);
    const u = Math.max(0, Math.min(1, t));
    // 매끄럽게(에르미트) — 어깨·팔꿈치·손목에서 접선이 세로라 관절이 안 꺾인다
    return (a + (b - a) * u * u * (3 - 2 * u)) / 2 + pad;
  }
  // 마디 하나의 테이퍼 path. **안쪽 변은 곧은 세로선**이고 바깥 변만 곡선이다.
  //   xin 안쪽 변 · sgn 바깥 방향 · d0~d1 armY 에서 잰 거리 · cap 둥근 마개
  // ⚠️ **어깨 마개는 반원이 아니라 세로로 긴 타원이다.**
  // 반원이면 폭의 절반(7.5px)만에 가로에서 세로로 돌아서, 평평한 어깨선과 거의 곧은
  // 팔이 **작은 모서리 하나로** 만난다 — 어깨와 팔이 직각으로 보이던 것이 이것이다.
  // 세로로 늘이면 같은 폭을 **더 긴 거리에 걸쳐** 돌아 어깨가 둥글게 흘러내린다.
  // 꼭대기는 그대로 armY 라 어깨 위로 혹이 솟지도 않는다.
  // ⚠️ **통통할 때 「어깨가 네모나다」는 것도 결국 이 값이다.** 몸통·통통 배율을 타면
  // 팔이 몸통보다 바깥에 서서 **어깨선이 곧 팔의 마개**가 된다 — 1.8 이면 화면에서
  // 14.5px 만에 0 에서 제 폭까지 벌어져 「선반」으로 보였다. 2.4 면 21px 에 걸쳐 돈다.
  // 대신 마개가 길어질수록 어깨 높이의 팔이 가늘어져 **어깨 부리**가 다시 나므로
  // `shoulderSquash` 의 물리는 폭도 같이 봐야 한다.
  const ARM_CAP_H = 2.2;                             // 위 마개의 세로/가로 비
  function armSegPath(xin, sgn, d0, d1, k, pad, capTop, capBot) {
    const B = BODY, f = n => +n.toFixed(2);
    const h0 = armHalf(d0, k, pad), h1 = armHalf(d1, k, pad);
    const y0 = B.armY + d0, y1 = B.armY + d1;
    const out = h => f(xin + sgn * h * 2);
    const sw = sgn > 0 ? 1 : 0;                       // 마개를 도는 방향
    // ⚠️ **마개 둘이 서로를 넘어서면 옆선이 «거꾸로» 흘러 가시가 된다.**
    // 퍼프 소매가 실제로 그랬다 — 폭에 7px 을 얹는데 높이는 24px 뿐이라,
    // 위 마개가 제 높이(반폭의 1.8배 = 22.9px)를 다 쓰면 아래 마개(12.7px)와 겹쳐
    // **어깨 밖으로 뾰족한 조각이 삐져나왔다** (「퍼프 드레스가 깨진다」로 신고받은 것).
    // 남은 높이 안으로 위 마개를 접는다 — 긴 팔에서는 여유가 넘쳐 아무것도 안 바뀐다.
    const room = Math.max(0, (capBot ? y1 - h1 : y1) - y0);
    const rt = Math.min(h0 * ARM_CAP_H, room);        // 위 마개의 세로 반지름
    const t0 = capTop ? y0 + rt : y0, t1 = capBot ? y1 - h1 : y1;
    const m = (t1 - t0) * 0.5;                        // 제어점 높이 — 양 끝에서 접선이 세로
    let d = capTop
      ? `M${f(xin)},${f(t0)} A${f(h0)},${f(rt)} 0 0 ${sw} ${out(h0)},${f(t0)}`
      : `M${f(xin)},${f(y0)} L${out(h0)},${f(y0)}`;
    d += ` C${out(h0)},${f(t0 + m)} ${out(h1)},${f(t1 - m)} ${out(h1)},${f(t1)}`;
    d += capBot ? ` A${f(h1)},${f(h1)} 0 0 ${sw} ${f(xin)},${f(t1)}`
                : ` L${f(xin)},${f(y1)}`;
    return d + ' Z';
  }

  function armShape(side, fill, pad, h, tune, opts) {
    const B = BODY, left = side === 'L', o = opts || {};
    const d = armShift(tune) * (left ? 1 : -1);       // 어깨선을 따라 팔을 옮긴다
    const x0 = (left ? B.armX_L : B.armX_R) + d;
    const ka = armK(tune);
    // **안쪽 변은 고정이다** — 굵기가 어떻든 팔이 몸통에서 안 떨어진다.
    // sgn 은 안쪽에서 바깥쪽으로 가는 방향
    const sgn = left ? -1 : 1;
    const xin = +((left ? x0 + B.armW + pad : x0 - pad)).toFixed(2);
    const rot = left ? B.armRot : -B.armRot;
    const bend = left ? -B.elbowRot : B.elbowRot;     // 안쪽(몸 쪽)으로
    const pivot = (left ? B.armPivotL : B.armPivotR) + d;
    const upLen = B.armH * B.elbowT;                  // 팔꿈치까지의 길이
    const cx = +(xin + sgn * armHalf(upLen, ka, pad)).toFixed(2);   // 팔꿈치 회전축
    const elbowY = B.armY + upLen;
    // 그릴 구간을 팔 위 끝(armY)에서 잰 거리로 바꾼다
    const from = (o.yFrom != null ? o.yFrom : B.armY - pad) - B.armY;
    const to = from + h;
    const baseRot = `rotate(${rot} ${+pivot.toFixed(2)} ${B.armPivotY})`;
    // 그릴 조각들을 먼저 모은다 — 테두리가 있으면 두 번 그려야 해서(아래 참조) 목록이 필요하다
    const segs = [];
    // 윗팔 조각 — 팔꿈치에서 **딱 끊는다** (아래 joint 가 이음매를 메운다)
    const upFrom = from, upTo = Math.min(to, upLen);
    if (upTo > upFrom) segs.push({ y: B.armY + upFrom, h: upTo - upFrom, tr: baseRot });
    // 아랫팔 조각 — 팔꿈치 기준 회전이 하나 더 붙는다 (기울기 → 굽힘 순으로 적용된다)
    const foFrom = Math.max(from, upLen), foTo = to;
    if (foTo > foFrom) {
      segs.push({ y: B.armY + foFrom, h: foTo - foFrom,
        tr: `${baseRot} rotate(${bend} ${+cx.toFixed(2)} ${+elbowY.toFixed(2)})` });
    }
    // ─── 팔꿈치 이음매는 **관절에 놓은 원 하나**로 메운다 ───────
    //
    // 마디 둘을 그냥 맞대면 아랫팔이 굽는 만큼(elbowRot) 윗변이 기울어
    // 바깥쪽에 얇은 쐐기 틈이 남는다. 예전에는 윗팔을 **고정된 반폭(w/2)만큼
    // 아래로 늘려** 덮었는데, 그 늘린 조각은 **굽힘을 안 타서** 팔꿈치 바깥에
    // 네모난 턱으로 삐져나왔다 — 팔이 가늘수록 더 튀어나온다 (늘린 길이가
    // 굵기와 무관한 고정값이라 그렇다).
    //
    // 굽힘의 회전축이 관절 한가운데(cx, elbowY)이므로 **그 점을 중심으로 한 원은
    // 굽혀도 제자리다.** 반지름을 팔꿈치의 반폭으로 잡으면 두 마디 어느 쪽에서 봐도
    // 안에 들어가 있어(원은 이차로 좁아지고 팔은 그보다 느리게 좁아진다) 밖으로 안 나온다.
    const hE = armHalf(upLen, ka, pad);
    const jy0 = Math.max(elbowY - hE, B.armY + from);
    const jy1 = Math.min(elbowY + hE, B.armY + to);
    const joint = (color, extra) => {
      if (!(from < upLen && to > upLen) || jy1 - jy0 <= 0.01) return '';
      const f = n => +n.toFixed(2);
      const wAt = y => Math.sqrt(Math.max(0, hE * hE - (y - elbowY) * (y - elbowY)));
      const w0 = wAt(jy0), w1 = wAt(jy1);
      return `<path d="M${f(cx + w0)},${f(jy0)} A${f(hE)},${f(hE)} 0 0 1 ${f(cx + w1)},${f(jy1)}`
        + ` L${f(cx - w1)},${f(jy1)} A${f(hE)},${f(hE)} 0 0 1 ${f(cx - w0)},${f(jy0)} Z"`
        + ` fill="${color}"${extra || ''} transform="${baseRot}"/>`;
    };
    // ⚠️ **둥근 어깨 마개는 「팔의 진짜 위 끝」에서만 씌운다.**
    // `i === 0` 만 보고 씌우고 있었는데, 그러면 **중간부터 그리는 조각**에도 마개가 붙는다 —
    // 치마 위로 팔을 다시 찍을 때(`armsOverSkirt`, 허리부터 아래)가 그렇다.
    // 허리선에서 팔이 갑자기 둥글게 오므라들어 **그 틈으로 치마가 비쳤다**
    // (「하의가 팔 위에 그려진다」로 신고받은 것이 이것이다 — 실제로는 팔이 패인 것이다).
    const capTop = from <= 0.01;
    const emit = (list, color, extra) => list.map((g, i) =>
      `<path d="${armSegPath(xin, sgn, g.y - B.armY, g.y - B.armY + g.h, ka, pad,
                             i === 0 && capTop, i === list.length - 1)}"
        fill="${color}"${extra || ''} transform="${g.tr}"/>`).join('');
    // 몸통과 팔이 같은 색이라 **겹치면 팔이 사라진다.** 테두리를 두르면 어깨에서 팔로
    // 이어지는 선을 막아서 없앴는데(4f58adb), 그러자 이번엔 구별이 안 됐다.
    // 그래서 **같은 모양을 몸 쪽으로 조금 밀어 한 단 어둡게** 깔아 둔다 —
    // 팔에 가려 **안쪽 겨드랑이 선만 그늘로 남는다.** 테두리처럼 실루엣을 끊지 않는다.
    //
    // ⚠️ **그늘은 팔이 시작하는 선에서 바로 긋지 않는다.** 어깨에서 팔로 넘어가는
    // 자리에 선이 생겨 애써 이은 실루엣을 도로 끊는다. ARM_SHADE_FROM 만큼 내려와
    // **겨드랑이 아래에서** 시작한다 (위 끝은 둥근 마개라 스르르 시작한다).
    const sFrom = B.armY + ARM_SHADE_FROM;
    const shadeSegs = segs.map(g => ({ y: Math.max(g.y, sFrom), h: g.h - Math.max(0, sFrom - g.y), tr: g.tr }))
      .filter(g => g.h > 0.5);
    const sc = shade(fill, 8);
    // ─── 옷과 같은 색으로 겹쳐야 할 때는 **윤곽선**을 두른다 ─────
    //
    // 공주 드레스처럼 소매가 몸판과 같은 색이면 팔이 통째로 묻힌다. 그렇다고 소매를
    // 어둡게 칠하면 **소매만 다른 옷** 처럼 보인다 — 「팔은 원래 드레스 색으로 두고
    // 윤곽선만 남긴다」가 이 그림체에 맞는다.
    //
    // ⚠️ **조각마다 선을 그으면 안 된다.** 팔은 마디 둘 + 관절 원 셋이라, 각각에
    // 선을 두르면 **팔꿈치 이음매에 가로줄**이 그어진다. 그래서 같은 모양을
    // **선 두께만큼 부풀려 밑에 깔고**(fill 과 stroke 를 같은 색으로) 그 위에 제 색을
    // 덮는다 — 밖으로 삐져나온 만큼만 테두리로 남고 내부 이음매는 덮여 안 보인다.
    const outline = o.outline
      ? emit(segs, o.outline, ` stroke="${o.outline}" stroke-width="${ARM_OUTLINE * 2}"`
          + ` stroke-linejoin="round"`)
        + joint(o.outline, ` stroke="${o.outline}" stroke-width="${ARM_OUTLINE * 2}"`)
      : '';
    // 윤곽선을 두르면 그늘은 안 깐다 — 둘 다 두면 안쪽에 선이 두 줄이 된다
    const shadeLayer = o.outline ? ''
      : `<g transform="translate(${(-sgn * armShadeW(ka)).toFixed(2)},0)">`
        + emit(shadeSegs, sc) + joint(sc) + '</g>';
    return shadeLayer + outline
      + emit(segs, fill, o.extra) + joint(fill, o.extra);
  }

  // 팔 중심선 위의 한 점 — dist 는 팔 위 끝(armY)에서 잰 거리.
  // 손 위치 계산용이라 armShift(체형 이동)는 넣지 않는다 (기존 손 계산과 같은 기준).
  function armPoint(side, dist, tune) {
    const B = BODY, left = side === 'L', k = armK(tune), sgn = left ? -1 : 1;
    const rot = (left ? B.armRot : -B.armRot) * Math.PI / 180;
    const bend = (left ? -B.elbowRot : B.elbowRot) * Math.PI / 180;
    // 팔이 가늘어지면 중심선도 안쪽으로 온다 — 안쪽 변이 고정이기 때문이다.
    // 손을 옛 고정값에 두면 가는 팔에서 손만 바깥에 남는다
    //
    // ⚠️ **`armShift` 를 여기서도 더해야 한다.** `armShape` 는 몸통 배율만큼 팔을
    // 옆으로 옮기는데(`armShift`) 이 함수만 그걸 빼먹고 있었다 — 몸통이 100% 가
    // 아니면 **손이 팔에서 최대 16px 떨어져** 옷 위에 동동 떴다
    // (몸통 50% 에서 +16 · 150% 에서 −16 · 100% 에서만 0 이라 기본 체형에서는 안 보인다).
    // 「손이 붙어 나오지 않는다」가 이것이다. **기준선 두 개를 반드시 같이 옮긴다** —
    // 팔의 안쪽 변(xin)과 어깨 회전축(pivot) 둘 다 `armShape` 와 같은 값이어야 한다
    const shift = armShift(tune) * (left ? 1 : -1);
    const xin = (left ? B.armX_L + B.armW : B.armX_R) + shift;
    const at = d => xin + sgn * armHalf(d, k, 0);
    const pivot = (left ? B.armPivotL : B.armPivotR) + shift;
    const upLen = B.armH * B.elbowT, elbowY = B.armY + upLen;
    const cx = at(upLen);
    const rotAbout = (p, a, o) => ({
      x: o.x + (p.x - o.x) * Math.cos(a) - (p.y - o.y) * Math.sin(a),
      y: o.y + (p.x - o.x) * Math.sin(a) + (p.y - o.y) * Math.cos(a),
    });
    let p = { x: at(dist), y: B.armY + dist };
    if (dist > upLen) p = rotAbout(p, bend, { x: cx, y: elbowY });   // 굽힘 먼저
    return rotAbout(p, rot, { x: pivot, y: B.armPivotY });           // 그다음 팔 기울기
  }

  // ─── 손 — **벙어리장갑 한 덩어리** ──────────────────────────
  //
  // 예전에는 손이 아예 없었다. 팔이 손목에서 둥근 마개로 뚝 끝나서 **잘린 것처럼**
  // 보였다 (소매를 그리는 옷 몇 벌만 소매 끝에 살색 동그라미를 하나 얹고 있었다).
  //
  // 듀오링고풍이라 손가락은 그리지 않는다(`ART_POLICY`) — **손목보다 조금 넓은 덩어리에
  // 엄지 혹 하나**면 손으로 읽힌다. 팔과 같은 살색이라 **실루엣으로만** 구분되므로
  // 손목보다 넓은 것이 핵심이다. 그리고 **손목에 선을 긋지 않는다** — 잘린 것처럼
  // 보이던 바로 그 모양이 된다.
  //
  // ⚠️ **팔의 기울기를 그대로 받는다.** 팔은 어깨에서 armRot, 팔꿈치에서 elbowRot 만큼
  // 도므로 아랫팔의 최종 기울기는 **그 둘의 합**이다. 안 맞추면 손만 삐딱하게 붙는다.
  // ⚠️ 자리는 `armPoint` 로 잡는다. 굵기를 바꾸면 팔의 중심선이 움직이는데(안쪽 변이
  // 고정이라 그렇다), 고정값에 두면 가는 팔에서 **손만 바깥에 남는다.**
  // ⚠️ 엄지는 **몸 쪽**에 붙인다. 팔을 내리고 서면 엄지가 안쪽을 향한다
  // 손목 반폭의 몇 배. ⚠️ **팔을 깎을 때마다 같이 올려야 한다** — 손은 손목 폭을
  // 따라가므로(`HAND_FOLLOW`) 팔만 깎으면 손이 팔보다 좁아져 **마개처럼** 보인다
  // (`checkavatar` 의 「손」이 부푼 폭 0.6~1.3px 로 지킨다). 1.36 → 1.4 → 1.46 → 1.38
  // (손목을 8.7 로 굵히면서 손도 같이 커져 1.46 은 팔 밖으로 나갔다)
  const HAND_W = 1.38;
  const HAND_H = 1.12;      // 손 반폭 대비 높이
  const HAND_THUMB = 0.4;   // 엄지 반지름 (손 반폭 대비)
  // ─── 손은 팔을 따라 가늘어지되 **조금 덜 따라간다** ──────────
  //
  // 예전에는 **기본 손목의 0.85** 를 바닥으로 깔았다. 그 바닥은 하필 **팔 50%
  // 에서만** 걸려서, 팔이 가장 가는 자리에서 손만 33% 부풀었다(3.04 → 4.04) —
  // **손이 팔보다 2.45px 넓은 공**이 된다. 가는 팔은 안쪽 변이 고정이라 몸 실루엣
  // **안으로 물러나 안 보이는데** 그 공만 골반 밖으로 튀어나와, 팔에 안 달린
  // **구슬 하나가 몸에 붙은 것**처럼 보였다 (「몸통·팔 50% 일 때 손이 떨어짐」).
  //
  // ⚠️ **그렇다고 팔을 그대로 따라가게 하면 안 된다.** 손이 손목보다 0.5px 밖에
  // 안 넓어져 **다시 마개**가 된다 (`checkavatar` 의 「손」이 0.6px 에서 잡는다).
  // 그래서 **무릎·팔꿈치와 같은 규칙**을 쓴다 — 따라가되 덜 따라간다.
  // 손이 팔 굵기를 따라가는 몫 (1 이면 그대로 따라간다).
  // ⚠️ **위아래로 다른 값을 쓴다.** 팔에 몫(`TUNE_GAIN.arm`)이 붙으면서 하나로는
  // 안 맞는다 — 한 값으로 맞추면 굵은 쪽에서 손이 같이 커져 팔 밖으로 1.8px 나오거나
  // (천장 1.3), 가는 쪽에서 손만 안 줄어 역시 1.8px 이 된다.
  // 굵어질 때는 덜 따라가고, 가늘어질 때는 잘 따라가야 한다.
  // ⚠️ **`TUNE_GAIN.arm` 을 바꾸면 여기도 같이 다시 잡아야 한다.** 팔이 4.4 → 3.0
  // 으로 가늘어지자 같은 0.55 에서 손이 0.25px 밖에 안 부풀어 마개가 됐다 → 0.70.
  // 0.78 은 반대로 1.5px 로 천장을 넘는다 — 창이 좁으니 바꿀 때마다 재 볼 것.
  const HAND_FOLLOW = { under: 0.75, over: 0.70 };
  function handShape(side, tune, color, dist) {
    const B = BODY, left = side === 'L', sgn = left ? -1 : 1;   // sgn 은 바깥 방향
    const ka = armK(tune);
    const p = armPoint(side, dist == null ? B.armH : dist, tune);
    const w0 = armHalf(B.armH, 1, 0);                  // 기본 손목
    const aw = armHalf(B.armH, ka, 0);
    const wristHalf = w0 + (aw - w0) * (aw < w0 ? HAND_FOLLOW.under : HAND_FOLLOW.over);
    const hw = wristHalf * HAND_W, hh = hw * HAND_H;
    const th = left ? (B.armRot - B.elbowRot) : (B.elbowRot - B.armRot);
    const f = n => +n.toFixed(2);
    // 팔과 **같은 그늘**을 몸 쪽으로 깔아 둔다 (armShape 의 ARM_SHADE 와 같은 규칙).
    // 가는 팔은 몸 실루엣 안에 들어가는데, 같은 살색이라 그늘이 없으면 손이
    // **어디서 시작하는지 안 보인다** — 그늘 한 줄이면 몸 위에 얹혀도 손으로 읽힌다
    const body = c => `<circle cx="${f(p.x - sgn * hw * 0.95)}" cy="${f(p.y + hh * 0.2)}"`
        + ` r="${f(hw * HAND_THUMB)}" fill="${c}"/>`
      + `<ellipse cx="${f(p.x)}" cy="${f(p.y + hh * 0.58)}" rx="${f(hw)}" ry="${f(hh)}" fill="${c}"/>`;
    return `<g transform="rotate(${th} ${f(p.x)} ${f(p.y)})">`
      + `<g transform="translate(${(-sgn * ARM_SHADE).toFixed(2)},0)">${body(shade(color, 8))}</g>`
      + body(color) + '</g>';
  }
  // `data-part="hand"` 를 붙여 둔다 — 검사기가 **손이 있어야 할 자리**를 이걸로 잡고,
  // 완성된 그림에서 그 자리가 아직 손인지(옷에 덮이지 않았는지) 본다.
  // 공주 드레스가 손을 통째로 덮고 있던 것을 아무도 못 잡던 이유가 이 표시가 없어서였다
  const hands = (tune, color, dist) =>
    `<g data-part="hand">${handShape('L', tune, color, dist)}`
    + `${handShape('R', tune, color, dist)}</g>`;

  // 장갑 — 팔 아래쪽(손목 쪽)부터 len 비율만큼 덮는다
  function renderGlove(it, tune) {
    if (isNone(it)) return '';
    const B = BODY, c = it.color, c2 = shade(c, 18);
    const pad = 1.5;                                  // 팔보다 아주 살짝 넓게
    const len = Math.max(0.08, Math.min(0.95, Number(it.len) || 0.22));
    const h = B.armH * len + pad;
    const yFrom = B.armY + B.armH - h + pad;          // 팔 끝(손목)에 맞춰 아래로 정렬
    // 마감(finish) — 장갑 **입구**를 어떻게 처리하는가. 길이(len)와 함께 두 축이다.
    // 옛 세이브는 kind 로만 갈렸다 — finish 가 없으면 그때 규칙으로 떨어진다
    const finish = it.finish || ((it.kind === 'lace') ? 'frill'
      : (it.kind === 'satin' || it.kind === 'opera') ? 'cuff'
      : (it.kind === 'leather') ? 'strap' : 'plain');
    // 입구 장식은 팔 모양을 그대로 따라야 팔 밖으로 삐져나오지 않는다 — armShape 로 그린다
    const bandAt = (col, thick, at) =>
      armShape('L', col, pad, thick, tune, { yFrom: at }) + armShape('R', col, pad, thick, tune, { yFrom: at });
    let trim = '';
    if (finish === 'cuff')       trim = bandAt(c2, 3, yFrom);                       // 얇은 띠
    else if (finish === 'frill') trim = bandAt(c2, 3, yFrom) + bandAt(c2, 2, yFrom + 5);  // 두 겹 프릴
    else if (finish === 'ribbon') trim = bandAt(c2, 4, yFrom + 2);                  // 굵은 띠(리본 자리)
    else if (finish === 'strap') trim = bandAt(c2, 2.4, yFrom + 3) + bandAt(c2, 2.4, yFrom + h - 8); // 위아래 스트랩
    // **손도 장갑 색이다.** 팔만 덮으면 장갑 아래로 살색 손이 삐져나온다
    return `<g data-part="glove">
      ${armShape('L', c, pad, h, tune, { yFrom })}
      ${armShape('R', c, pad, h, tune, { yFrom })}
      ${trim}
      ${hands(tune, c)}
    </g>`;
  }

  // 구두 — 발(ellipse cx 86/114, cy BODY.footY)을 덮는다. rise 만큼 발목 위로 올라온다.
  // 높이는 전부 footY 에서 상대로 잡는다 — 다리가 움직이면 구두도 같이 따라와야 한다
  function renderShoes(it, tune) {
    if (isNone(it)) return '';
    const c = it.color, c2 = shade(c, 22), rise = Number(it.rise) || 0;
    const FY = BODY.footY;
    const fin = it.finish || ({ maryjane: 'strap', ballet: 'ribbon', sneaker: 'sole',
      glass: 'gloss', boots: 'plain' }[it.kind] || 'plain');
    const foot = (cx) => {
      let s = '';
      if (rise > 0) {   // 부츠·스니커즈: 발목을 감싸는 통
        s += `<rect x="${cx - 9}" y="${FY - rise}" width="18" height="${rise + 4}" rx="5" fill="${c}"/>`;
      }
      s += `<ellipse cx="${cx}" cy="${FY}" rx="13" ry="7.6" fill="${c}"/>`;
      // 마감(finish) — 목 높이(rise)와 함께 두 축이다.
      // 옛 세이브는 kind 로만 갈렸다 — finish 가 없으면 그때 규칙으로 떨어진다
      if (fin === 'strap')      s += `<path d="M${cx - 9},${FY - 4} L${cx + 9},${FY - 4}" stroke="${c2}" stroke-width="2" stroke-linecap="round"/>`;
      else if (fin === 'ribbon') s += `<path d="M${cx - 7},${FY - 5} Q${cx},${FY - 1} ${cx + 7},${FY - 5}" stroke="${c2}" stroke-width="1.8" fill="none" stroke-linecap="round"/>`
        + `<circle cx="${cx}" cy="${FY - 5}" r="2" fill="${c2}"/>`;
      else if (fin === 'sole')  s += `<ellipse cx="${cx}" cy="${FY + 3}" rx="13" ry="3.4" fill="${c2}"/>`;
      else if (fin === 'gloss') s += `<ellipse cx="${cx - 3}" cy="${FY - 2}" rx="5" ry="2.4" fill="#fff" opacity="0.75"/>`;
      // 목이 있는 구두는 입구에 띠를 하나 둘러 발목과 경계가 보이게 한다
      if (rise > 0) s += `<path d="M${cx - 9},${FY - rise + 5} L${cx + 9},${FY - rise + 5}" stroke="${c2}" stroke-width="2" stroke-linecap="round"/>`;
      return s;
    };
    const fx = footX(tune);
    return `<g data-part="shoes">${foot(fx)}${foot(200 - fx)}</g>`;
  }

  // 몸통 배율이 바뀌면 몸통 옆선이 안팎으로 움직인다. 팔이 제자리면 몸통에서 떨어지므로
  // **옆선이 움직인 만큼 팔도 같이 옮긴다** — 그래야 붙어 있는 관계가 그대로 유지된다.
  // (몸통은 x=100 을 축으로 늘어나므로 옆선은 100-(100-기준)*k 로 간다)
  //
  // 기준은 어깨 최대폭(torsoL=64)이 아니라 **팔 중간 높이의 몸통 옆선**이다.
  // 몸통은 허리로 갈수록 좁아지는데 어깨 폭으로 맞추면 그 차이가 배율만큼 커져,
  // 몸통을 키웠을 때 팔 아래쪽이 다시 떨어진다. 64·66·68·70·72 를 실측으로
  // 쓸어 본 결과 68 만 50~200% 전 구간에서 틈이 0 이었다.
  const ARM_ANCHOR_X = 68;
  function armShift(tune) {
    return (100 - ARM_ANCHOR_X) * (1 - tuneOf(tune, 'torso'));
  }

  // ─── 어깨 끝은 팔의 바깥 변을 넘지 않는다 ────────────────────
  //
  // 넘으면 어깨가 팔보다 튀어나와 **부리처럼 뾰족한 턱**이 생긴다. 팔을 가늘게 하면
  // (팔 배율 50%) 팔의 바깥 변이 안으로 들어오는데 어깨는 제자리라 실제로 났다.
  //
  // ⚠️ **팔을 바깥으로 밀어서 맞추면 안 된다.** 굵기 배율의 축을 바깥 변으로 옮겨
  // 봤더니 어깨는 붙었지만 **팔이 허리에서 몸통과 떨어졌다** — 팔은 허리에서 몸통과
  // 1.6px 밖에 안 겹쳐 있어서, 가늘어진 만큼 안쪽 변이 밖으로 나가면 곧바로 배경이 비친다
  // (팔 50% 에서 4.75px 벌어졌다 — 팔이 몸 옆에 떠 있는 막대로 보인다).
  // 폭이 15px 뿐이라 「허리에 닿으면서 어깨 끝까지 닿는」 팔은 만들 수가 없다.
  //
  // 그래서 **어깨 쪽을 팔에 맞춘다.** 어깨 끝이 팔의 바깥 변보다 나가면 그만큼만 좁힌다.
  // 팔이 어깨보다 바깥이면(기본값 · 팔을 굵게 한 경우) 1 이라 아무것도 안 바뀐다.
  //
  // ⚠️ **넓히는 쪽으로도 따라가게 해 봤다가 되돌렸다.** 삼각근을 넓히면 옷이 그것을
  // 덮어야 해서 그렇게 했는데, 어깨가 팔의 «제 폭»까지 나가면 **팔의 둥근 마개 위로
  // 부리처럼** 솟는다 (몸통 50% · 팔 200% 에서 4.0px). 팔 위 끝은 아직 제 폭이
  // 아니라서다 — 넓히려면 «한 점»이 아니라 «높이마다» 견줘야 한다.
  function shoulderSquash(tune) {
    const B = BODY;
    const tip = 100 + (B.torsoR - 100) * tuneOf(tune, 'torso');
    // 팔의 바깥 변. **둥근 어깨 마개(cap) 몫으로 2px 물린다** — 팔 위 끝은 둥글어서
    // 맨 위에서는 아직 제 폭이 아니다. 그만큼 어깨가 마개 밖으로 삐져나온다
    // (팔 50% 에서 y≈111 에 2px 짜리 혹). 기본값은 팔이 어깨보다 5px 바깥이라 안 바뀐다
    // ⚠️ **폭은 `armWidths` 에서 가져온다.** 예전에는 `B.armW` 를 따로 읽고 있었는데,
    // 어깨만 넓히자 두 값이 갈려 **안 좁혀도 될 어깨를 좁혔다** — 같은 수를 두 군데
    // 적어 두면 한쪽만 고쳤을 때 조용히 어긋난다 (이 파일이 여러 번 겪은 일이다)
    // ⚠️ 물리는 폭을 2 → 3.4 로 키웠다. 팔을 가늘게(어깨 15 → 14.1 · 아랫팔 −15%) 하자
    // 몸통 50% · 팔 75% 에서 어깨가 다시 1.25px 튀어나왔다 — 마개가 길어서(`ARM_CAP_H`)
    // 어깨 높이의 팔은 아직 제 폭이 한참 아니다. **기본 체형에서는 여전히 안 좁힌다**
    // (팔이 어깨보다 0.7px 바깥이라 `armOuter >= tip` 이다) — 거기서 좁아지면
    // 어깨가 통째로 줄어들어 「어깨↔머리카락」 틈이 다시 벌어진다.
    const armOuter = B.armX_R + armWidths(armK(tune)).S - armShift(tune) - 3.4;
    return armOuter >= tip ? 1 : (armOuter - 100) / (tip - 100);
  }
  // 어깨 쪽 x 를 중심선(100) 기준으로 f 배 좁힌다(f>1 이면 넓힌다).
  // 몸통·옷이 같은 함수를 지난다
  const sqx = (x, f) => f === 1 ? x : +(100 + (x - 100) * f).toFixed(2);

  // 무릎 높이 — 허벅지 아래 끝(263)과 종아리 위 끝(256)이 겹치는 자리.
  // 옷이 종아리까지 덮는지 판정하는 기준이다. **다리를 옮기면 여기도 같이 옮긴다**
  const KNEE_LINE = 259;

  // 허리 반폭 — 몸과 옷이 **같은 값**을 본다. 옷은 CLOTH_PAD 만큼 넉넉하게.
  // ⚠️ **`tuneOf` 가 아니라 `fatOf` 다.** 「지금 130% 인 허리가 150% 가 되도록」이라
  // 몫(`TUNE_GAIN.waist` 0.6)을 붙였다 — 100% 를 넘는 만큼만 0.6배로 얹으므로
  // 150% 에서 1.30배(반폭 44.75 → 38.75px)이고 **100% 이하는 한 톨도 안 변한다.**
  const waistHalf = tune => BODY.waistHalf * fatOf(tune, 'waist');
  // ⚠️ **몸통 배율까지 태워야 몸의 허리와 같은 자리가 된다.** 몸의 허리는
  // `waistHalf * torso` 인데(torsoArms 의 `wRa`) 옷은 `torso` 를 빼먹고 있었다.
  // 그래도 오래 안 들킨 이유: 옷을 통째로 `wrapX(tuneMax(...))` 로 늘리고 있었는데
  // 그 배율이 **1 밑으로 안 내려가서**(`tuneMax` 가 1 을 바닥으로 깐다) 살을 찌울 때만
  // 맞고 **뺄 때는 옷만 그대로 남았다** — 「살이 빠졌을 때 옷이 안 맞는다」가 이것이다.
  const clothWaistHalf = tune => waistHalf(tune) * tuneOf(tune, 'torso') + CLOTH_PAD;
  // 옷 옆선의 **가운데 제어점**. 기본값에서는 늘 `wR + 4` 라 그림이 그대로인데,
  // 허리가 어깨에 비해 아주 가늘어지면(허리 50%) 옷이 몸보다 **먼저** 좁아져
  // 어깨와 허리 사이에 1px 짜리 살 조각이 비쳤다. 어깨에서 잰 값으로 바닥을 깔아 둔다
  const CLOTH_SIDE_C = 0.55;
  const clothSideC = (eR, wR) => +Math.max(wR + 4, eR - (eR - wR) * CLOTH_SIDE_C).toFixed(2);
  // ─── 허벅지 윗머리는 **골반을 따라 들어온다** ────────────────
  //
  // 허벅지가 붙는 자리가 곧 골반이다. 그래서 이 둘은 서로의 하한 노릇을 하는데,
  // 허벅지 쪽만 일방적으로 하한이면 **엉덩이 슬라이더가 통째로 죽는다** —
  // 실제로 `LEG.hipW` 를 20 → 36 으로 올린 뒤 엉덩이 20%~150% 가 전부
  // 38.0~38.6px 로 나왔다 (좌우 폭이 하나도 안 변한다는 신고가 이것이다).
  //
  // 골반이 좁은 몸은 허벅지도 위쪽부터 모여서 붙는다 — **무릎이 허벅지·종아리를
  // 따라가는 것(`KNEE_K`)과 같은 규칙**이다. 다만 관절이니 절반만 따라간다.
  //   · 엉덩이 100% 이상이면 한 톨도 안 움직인다 (기본 체형은 그대로다)
  //   · 엉덩이 20% 면 윗머리가 60% 로 들어오고, 그만큼 엉덩이도 같이 좁아진다
  // **무릎 쪽으로는 저절로 사라진다** — 아래의 `thighOuterAt` 이 무릎(`kneeX`)까지
  // 보간하므로, 골반이 건드리는 것은 윗머리 하나뿐이다.
  const HIP_PULL = 0.5;
  const thighTop = tune => Math.max(innerX(LEG.hipY) + 2,
    (THIGH_GAP + LEG.hipW * fatOf(tune, 'thigh'))
      * (1 - HIP_PULL * (1 - Math.min(1, fatOf(tune, 'hip')))));
  // 허벅지 바깥 변 — **높이에 따라 다르다.** 위(엉덩이 밑)가 가장 굵고 무릎으로 가늘어진다.
  // 엉덩이가 붙을 자리를 잡으려면 「그 높이의」 허벅지 폭을 알아야 한다
  // ⚠️ **재는 곡선과 그리는 곡선이 같아야 한다.**
  // 예전에는 여기서 smoothstep 으로 «모델»을 세우고 `limbPath` 는 큐빅으로 그렸다.
  // 둘이 달라서 엉덩이가 「허벅지가 여기 있다」고 믿는 자리보다 허벅지가
  // **7.3px 더 바깥**에 있었고, 그 차이가 이음매에 각진 턱을 만들었다
  // (「엉덩이랑 허벅지 연결 부분이 부드럽지 않다」로 신고받은 자리다).
  // 지금은 `limbPath` 가 그리는 큐빅을 **그대로 풀어** 답한다.
  function thighOuterAt(tune, y) {
    const L = LEG, top = thighTop(tune), kx = kneeX(tune);
    // limbPath 의 둥근 마개와 같은 반지름 — 곡선이 시작·끝나는 높이가 그만큼 안으로 들어온다
    const cap = (yy, half) => Math.max(1, Math.min(5, (half - innerX(yy)) / 2));
    const y0 = L.hipY + cap(L.hipY, top), y1 = L.kneeY - cap(L.kneeY, kx);
    if (y <= y0) return top;
    if (y >= y1) return kx;
    // limbPath(허벅지) 와 **같은** 제어점 높이 — 비대칭이다
    const ha = (y1 - y0) * THIGH_C[0], hb = (y1 - y0) * THIGH_C[1];
    const bx = kx + (top - kx) * thighBul(tune);             // 셋째 제어점의 x (바깥으로)
    const yAt = t => { const u = 1 - t;
      return u * u * u * y0 + 3 * u * u * t * (y0 + ha) + 3 * u * t * t * (y1 - hb) + t * t * t * y1; };
    let lo = 0, hi = 1;                              // y(t) 는 단조로우므로 이분법으로 푼다
    for (let i = 0; i < 24; i++) { const m = (lo + hi) / 2; if (yAt(m) < y) lo = m; else hi = m; }
    const t = (lo + hi) / 2, u = 1 - t;
    return top * (u * u * u + 3 * u * u * t) + bx * (3 * u * t * t) + kx * (t * t * t);
  }
  // 가장 굵은 곳 (엉덩이 바로 밑) — 기본값이면 122
  const thighOuter = tune => thighOuterAt(tune, LEG.hipY);
  // 발(과 구두)의 중심 x — **발목을 따라간다.**
  // 발목은 배율을 안 타므로 종아리를 굵게 해도 발은 제자리다. 가늘게 하면 같이 들어온다.
  // (발목 한가운데에서 바깥으로 6px — 기본값에서 85.4 / 114.6 이 되는 자리다)
  // 안쪽 변은 발목에서 조금 벌어져 있다(innerX) — 그 자리를 그대로 읽어야 발이 발목 밑에 온다
  const footX = tune => +(100 - ((innerX(LEG.ankleY) + ankleX(tune)) / 2 + 6)).toFixed(2);
  // 엉덩이가 허벅지에 내려꽂는 자리는 **바깥 변보다 1px 안쪽**이다.
  //
  // ⚠️ 딱 맞추거나(122) 밖으로 물리면(123) 그 높이에서 실루엣이 1px 턱을 져
  // **허벅지와 엉덩이가 만나는 곳에 가느다란 선**이 보인다. 예전 값이 123 이었다.
  // 안쪽에 두면 그 아래부터는 **허벅지의 제 옆선이 그대로 이어받아** 선이 안 생긴다
  // (엉덩이는 허벅지 위에 그려지므로, 안쪽으로 물러나면 허벅지가 드러난다).
  // ⚠️ **허벅지가 아래로 가늘어진다는 것을 빼먹으면 안 된다.** 가장 굵은 곳(122)을
  // 기준으로 잡아 두었더니, 붙는 높이(224)에서 허벅지는 이미 119.5 라 그 사이로
  // **세로 틈**이 벌어졌다 (기본 1.6px · 엉덩이 150% 에서 3.8px).
  // 붙는 높이에서 재면 그 위 구간에서도 허벅지가 늘 더 굵어 틈이 안 생긴다.
  // ⚠️ **1px 은 너무 깊었다.** 도착 접선을 허벅지에 맞춘 뒤로는(`hipLean`) 1px 만
  // 물려도 **허벅지가 BY 보다 두 줄 위에서 먼저 튀어나온다** — 그 자리에서
  // 엉덩이는 아직 3px/줄 로 내려오는 중이고 허벅지는 1.6px/줄 이라, 옆선의
  // 기울기가 한 줄 만에 반으로 꺾인다. 「울퉁불퉁하다」의 정체가 이것이었다.
  // 0.3 이면 만나는 자리가 BY 바로 위로 붙어 기울기가 이어진다
  // (그래도 «닿게» 두지는 않는다 — 딱 맞추면 이음매에 가느다란 선이 생긴다).
  const THIGH_JOIN_IN = 0.3;
  const thighJoin = tune => thighOuterAt(tune, hipBlendY(tune)) - THIGH_JOIN_IN;
  // 엉덩이 반폭 — 옷은 여기도 덮어야 한다 (치마·바지·드레스가 이 값을 본다).
  //
  // **허벅지보다 좁을 수 없다.** 좁으면 허벅지가 엉덩이 밖으로 튀어나와 이음매에
  // 계단이 생긴다. 그 허벅지 윗머리가 이제 골반을 따라 같이 들어오므로(`thighTop`),
  // 이 하한은 엉덩이를 붙잡아 두지 않고 **같이 내려온다.**
  //
  // ⚠️ **허리 하한은 허리의 3/4 까지만이다.** 예전에는 허리 자체가 하한이라
  // 기본 허리(30)에서 엉덩이가 30px 밑으로 못 내려갔다 — 슬라이더 아래쪽 절반이
  // 죽는다. 엉덩이가 허리보다 좁은 몸은 실제로 있다(사과형). 다만 아주 좁으면
  // 허리에서 골반까지 34px 만에 떨어뜨려야 해서 **쐐기**가 되므로 선은 그어 둔다.
  // 허리 → 엉덩이 봉우리 곡선의 제어점 높이 (구간 길이에 대한 몫 · 위 · 아래).
  // ⚠️ **둘을 같은 값(0.45)으로 두면 마름모가 된다.** 그러면 곡선이 허리에서 오래
  // 세로로 버티다가 한꺼번에 벌어져, 옆선이 기울기 1.5짜리 «사선 한 줄»이 된다.
  // 위를 짧게·아래를 길게 잡으면 세로에서 일찍 벗어나 봉우리 전에 눕는다.
  // ⚠️ 허리에서 접선이 세로인 것은 **고쳐서는 안 된다** — 허리는 옆선의 최솟점이라
  // 위(좁아짐)와 아래(넓어짐)의 기울기가 거기서 0 으로 만나야 몸통과 안 꺾인다.
  // 그래서 허리 바로 밑 몇 줄이 오목한 것은 «허리가 있다»는 뜻이고 없앨 수 없다 —
  // 없앨 것은 그 뒤의 **긴 직선**이다.
  // 지금 값은 재고 그려 보고 고른 것이다 — 같은 폭인데 [0.45,0.45] 은 마름모,
  // [0.20,0.70] 은 둥근 덩어리로 보인다. 오목한 구간도 24줄 → 13줄로 줄었다.
  const HIP_UP_C = [0.20, 0.70];
  const HIP_WAIST_MIN = 0.75;
  // ⚠️ **엉덩이는 허벅지보다 «넓어야» 한다** — 「빌렌도르프의 비너스」처럼 옆선이
  // 하나의 난형이 되려면 그렇다. 예전에는 `thighOuter` 를 **바닥으로만** 삼아서,
  // 허벅지를 키우면 엉덩이가 딱 그만큼만 따라왔다 — 재어 보니 허리(67.5)에서
  // 봉우리(73)까지 **33줄에 5.5px** 밖에 안 벌어져 옆선이 «평평한 면»이었고,
  // 그 위아래 끝이 「뾰족하다」로 신고받은 자리다.
  // 100% 를 넘는 만큼만 얹는다 — 가는 다리는 지금 그대로다.
  //
  // ⚠️ **여기도 0.14 → 0.10 으로 같이 내렸다.** 슬라이더를 전부 최대로 밀면
  // 엉덩이 반폭을 정하는 것은 `TUNE_GAIN.hip` 이 아니라 **이 줄**이다
  // (허벅지가 96.5 까지 굵어져 `thighOuter × hipOverK` 가 셋 중 제일 크다).
  // 그래서 몫만 내리면 **정작 제일 넓은 몸에서는 아무것도 안 변한다** —
  // 재어 보니 113.8 그대로였다. 0.10 에서 허리 84.5 · 봉우리 **107.3**
  // (몫 29.3 → 22.8 · 역시 −22%). 두 자리를 같이 봐야 하는 이유다.
  const HIP_OVER = 0.10;
  const hipOverK = tune => 1 + HIP_OVER * overOf(tune, 'thigh');
  const hipBaseHalf = tune => Math.max(
    BODY.hipHalf * fatOf(tune, 'hip'),
    waistHalf(tune) * tuneOf(tune, 'torso') * HIP_WAIST_MIN,
    thighOuter(tune) * hipOverK(tune));
  const clothHipHalf = tune => hipHalf(tune) + CLOTH_PAD;

  // ─── 엉덩이는 아래로 처진다 ─────────────────────────────────
  //
  // 튀어나온 만큼(=낙차) **내려올 거리도 길어지고 봉우리도 아래로 내려온다.**
  // 짧은 거리에 억지로 밀어 넣으면 옆으로 뾰족한 날개가 된다 — 실제 몸은 커질수록
  // 뾰족해지는 게 아니라 **중력으로 처지면서 더 둥글어진다.**
  //
  // 몸과 하의가 **같은 값을 본다** — 안 그러면 넓은 엉덩이가 바지 옆으로 삐져나온다.
  // 낙차는 **가장 굵은 곳**으로 잰다 — thighJoin 이 hipBlendY 를 보므로 여기서
  // thighJoin 을 쓰면 서로를 부르며 돈다
  //
  // ⚠️ **낙차는 「배율이 만든 폭」(hipBaseHalf)으로만 잰다.** 아래 hipNeedHalf 가
  // 허벅지를 덮으려고 폭을 더 얹는데, 그건 **엉덩이가 허벅지 쪽으로 손을 뻗은 것**이지
  // 허벅지 밖으로 더 나온 살이 아니다 — 처질 것이 없다. 여기에 얹은 폭까지 넣으면
  // 넓어질수록 봉우리가 내려가고, 내려가면 위쪽 옆선이 좁아져 또 넓혀야 해서
  // **서로 물고 발산한다** (허리 50% · 허벅지 200% 에서 엉덩이가 삼각형이 됐다).
  //
  // ─── 가장 넓은 곳은 **점이 아니라 짧은 곧은 구간**이다 ──────
  //
  // 위아래 두 마디가 봉우리에서 세로 접선으로 만나므로 수학적으로는 매끄러운데,
  // 그 자리의 **곡률 반지름이 1.5·ha²/(h−w)** 라 허리가 가늘고 엉덩이가 넓을수록
  // 급격히 작아진다 — 12px 쯤 되면 사람 눈에는 그냥 **뾰족한 모서리**로 읽힌다.
  // 제어점 비율(0.45)로는 못 키운다. 0.5 가 상한이라 반지름이 1.2배밖에 안 는다
  // (비율을 **낮추는** 것은 더 나쁘다 — 마디 가운데는 펴지지만 봉우리가 연처럼 뾰족해진다).
  //
  // 그래서 봉우리를 **짧은 세로 직선**으로 벌린다. 그 구간의 곡률은 0 이라 어떤 배율에서도
  // 뾰족해질 수가 없고, 실제 몸도 가장 넓은 곳은 한 점이 아니라 한 뼘이다.
  // 길이는 **허리·허벅지보다 얼마나 나왔는지**에 비례한다 — 안 나온 몸은 0 이다.
  // ⚠️ **곧은 구간이 길면 그게 곧 「평평한 면 + 모서리」다.** 엉덩이가 허벅지보다
  // 넓어지면서(`HIP_OVER`) 이 구간이 8줄까지 자랐고, 그 위아래 끝이
  // 「뾰족하다」로 신고받은 자리다. 봉우리는 «짧게 한 뼘»이면 족하다.
  const HIP_APEX_RUN = 0.18, HIP_APEX_RUN_MAX = 4;
  function hipGeom(tune) {
    const base = hipBaseHalf(tune);
    const drop = Math.max(0, base - thighOuter(tune));
    // 붙는 높이. 아무리 커도 **무릎 10px 위**에서는 붙는다 (그 아래는 종아리다)
    // ⚠️ **여분의 폭을 «긴 거리»에 걸쳐 털어야 옆선이 둥글다** (2.2 → 5).
    // 엉덩이가 허벅지보다 넓어진 만큼(`drop`)을 짧은 거리에 떨구면, 만나는 자리에서
    // 기울기가 −2.38 → −0.62 로 튀어 **모서리**가 된다. 5 로 늘리면 기울기가
    // 0 → −0.13 → −0.25 → … → −2 로 **끊김 없이 가속**한다 — 원의 옆선이 그 모양이다.
    const BY = Math.min(KNEE_LINE - 10, Math.max(BODY.hipBottom, BODY.hipY + drop * 5));
    // 가장 넓은 높이 — 처진 만큼 hipY 보다 아래다. 내려갈 수 있는 거리의 35% 를 넘지는
    // 않는다 (봉우리가 허벅지에 너무 붙으면 다시 뾰족해진다)
    const room = BY - BODY.hipY;
    const HY = BODY.hipY + Math.min(drop * 0.5, room * 0.35);
    const w = waistHalf(tune) * tuneOf(tune, 'torso');
    const stand = base - Math.max(w, thighOuterAt(tune, BY) - 1);   // 허리·허벅지보다 나온 만큼
    // 위아래 마디를 반 넘게 잡아먹지 않는다 — 이을 곡선이 남아 있어야 한다
    const run = Math.max(0, Math.min(HIP_APEX_RUN_MAX, stand * HIP_APEX_RUN,
      (HY - BODY.waistY) * 0.5, (BY - HY) * 0.5));
    return { drop: drop, BY: +BY.toFixed(1), HY: +HY.toFixed(1),
             HY1: +(HY - run / 2).toFixed(1), HY2: +(HY + run / 2).toFixed(1) };
  }

  // ─── 엉덩이는 **허벅지 윗머리까지 감싸야 한다** ──────────────
  //
  // 허벅지의 맨 위(LEG.hipY=186)는 엉덩이의 봉우리(BODY.hipY=198)보다 **12px 위**다.
  // 그래서 반폭을 허벅지와 같게 맞춰 놔도, 그 높이에서 옆선은 아직 허리에서 내려오는
  // 중이라 좁다 — **허벅지의 둥근 윗머리가 엉덩이 밖으로 혹처럼 튀어나온다**
  // (허벅지 200% 에서 4px · 둥근 마개라 눈에 잘 띈다).
  //
  // ⚠️ **덮어야 할 것은 「그려진」 허벅지다.** 위 끝은 둥근 마개(limbPath 의 r0)라
  // 맨 윗줄에서는 마개 반지름만큼 좁고, **가장 굵어지는 자리는 186+r0 쯤**이다.
  // 186 에서 제 폭을 다 덮으려 들면 있지도 않은 살을 덮느라 엉덩이가 크게 부푼다.
  function thighDrawnAt(tune, y) {
    const top = thighOuterAt(tune, LEG.hipY);
    const r = Math.max(1, Math.min(5, (top - innerX(LEG.hipY)) / 2));
    const taper = thighOuterAt(tune, y);
    if (y >= LEG.hipY + r) return taper;
    const dy = LEG.hipY + r - y;                  // 마개 원의 중심에서 위로
    return Math.min(taper, top - r + Math.sqrt(Math.max(0, r * r - dy * dy)));
  }

  // 옆선을 따라가며 **「이 높이의 허벅지를 덮으려면 봉우리가 얼마나 넓어야 하는가」**
  // 를 되풀어 가장 큰 값을 쓴다. x 는 봉우리 폭 h 에 대해 **1차**라 바로 풀린다:
  //   윗마디(허리→봉우리)   x = w + (h−w)·B   → h ≥ w + (T−w)/B
  //   아랫마디(봉우리→허벅지) x = h + (tJ−h)·B → h ≥ (T − tJ·B)/(1−B)
  //
  // ⚠️ **양 끝 언저리는 빼야 한다.** 끝점에서는 B 가 0 이나 1 로 가서 나눗셈이 터진다 —
  // 게다가 아랫마디의 끝은 엉덩이가 **일부러** 허벅지보다 1px 안쪽인 자리다
  // (thighJoin 참고 — 딱 맞추면 이음매에 가느다란 선이 생긴다). 그래서 **B 로 자른다** —
  // 높이로 자르면 마디 길이가 배율마다 달라져 어떤 조합에서는 끝까지 재게 된다
  // (그 바람에 엉덩이가 반폭 70px 짜리 삼각형이 됐다).
  //
  // ⚠️ 그리고 **얹는 폭에 상한을 둔다.** 이 식은 못 덮을 자리를 만나면 얼마든지
  // 커지는데, 커진 엉덩이는 봉우리에서 허벅지까지를 짧은 거리에 깎아 내리느라
  // 옆구리에 **선반(날개)** 을 만든다 — 사람이 보기에는 그쪽이 더 나쁘다.
  // ─── 엉덩이 아랫마디(봉우리→허벅지)도 «비대칭»이다 ─────────
  // ⚠️ 위아래를 같은 값(0.45)으로 두면 가장 가파른 곳이 **가운데**에 온다. 그런데
  // 허벅지는 그보다 아래에서 튀어나오므로, 만나는 자리에서 기울기가 한 줄 만에
  // 반으로 꺾인다 — 「울퉁불퉁하다」의 나머지 절반이 이것이다.
  // 앞을 짧게(봉우리를 빨리 떠나고) 뒤를 길게(허벅지에 완만히 붙는다) 잡는다.
  // 봉우리에서의 접선은 어느 값이든 세로다(제어점의 x 가 같다) — 곡률만 조여진다.
  // ⚠️ **여기도 합이 1 에 붙으면 안 된다** (허벅지의 `THIGH_C` 와 같은 함정).
  // 0.32 · 0.64 는 두 제어점이 HY2+0.32h 와 HY2+0.36h 로 **거의 같은 높이**라
  // 봉우리 밑이 직선이 됐다.
  const HIP_C = [0.45, 0.45];
  const HIP_B_LO = 0.35, HIP_B_HI = 0.5;   // 마디의 어느 구간까지 재는가
  const HIP_COVER_PAD = 0.6;               // 딱 맞추면 반올림·계단 탓에 반 픽셀이 남는다
  const HIP_SPREAD_MAX = 13;               // 얹을 수 있는 폭의 한계 (px)
  function hipNeedHalf(tune, half, HY1, HY2, BY) {
    const w = waistHalf(tune) * tuneOf(tune, 'torso');
    const WY = BODY.waistY, HY = HY1;
    const ha = (HY1 - WY) * 0.45, hb1 = (BY - HY2) * HIP_C[0], hb = (BY - HY2) * HIP_C[1];
    const tJ = thighOuterAt(tune, BY) - 1;
    let need = half;
    for (let i = 1; i <= 160; i++) {
      const t = i / 160, u = 1 - t;
      const B = 3 * u * t * t + t * t * t;                 // x 가 끝점 쪽으로 간 비율
      const y1 = u*u*u*WY + 3*u*u*t*(WY + ha) + 3*u*t*t*(HY - ha) + t*t*t*HY;
      if (y1 >= LEG.hipY && B > HIP_B_LO) {
        need = Math.max(need, w + (thighDrawnAt(tune, y1) + HIP_COVER_PAD - w) / B);
      }
      const y2 = u*u*u*HY2 + 3*u*u*t*(HY2 + hb1) + 3*u*t*t*(BY - hb) + t*t*t*BY;
      if (y2 >= LEG.hipY && B < HIP_B_HI) {
        need = Math.max(need, (thighDrawnAt(tune, y2) + HIP_COVER_PAD - tJ * B) / (1 - B));
      }
    }
    for (let y = HY1; y <= HY2; y += 1) {          // 봉우리의 곧은 구간
      if (y >= LEG.hipY) need = Math.max(need, thighDrawnAt(tune, y) + HIP_COVER_PAD);
    }
    return Math.min(need, half + HIP_SPREAD_MAX);
  }
  // 세 값(반폭 · 봉우리 · 붙는 높이)이 한 묶음으로 나온다. 한 렌더에서 여러 번 불리므로
  // 마지막 결과만 기억해 둔다 — 배율이 그대로면 다시 풀지 않는다
  let hipMemo = null;
  function hipSolve(tune) {
    const key = ['hip', 'waist', 'torso', 'thigh', 'calf'].map(k => tuneOf(tune, k)).join(',');
    if (hipMemo && hipMemo.key === key) return hipMemo.v;
    const g = hipGeom(tune);
    const v = { half: +hipNeedHalf(tune, hipBaseHalf(tune), g.HY1, g.HY2, g.BY).toFixed(2),
                HY: g.HY, HY1: g.HY1, HY2: g.HY2, BY: g.BY };
    hipMemo = { key: key, v: v };
    return v;
  }
  const hipHalf   = tune => hipSolve(tune).half;
  const hipApexY  = tune => hipSolve(tune).HY;
  const hipApexTop = tune => hipSolve(tune).HY1;   // 곧은 구간의 위 끝
  const hipApexBot = tune => hipSolve(tune).HY2;   // 아래 끝
  const hipBlendY = tune => hipSolve(tune).BY;
  // 엉덩이 옆선 (오른쪽 반) — 봉우리에서 허벅지까지 내려오는 3차 곡선의 제어점.
  //   x0 봉우리 폭 · x3 허벅지에 닿는 폭 (하의는 여기에 제 여유를 얹어 부른다)
  //   cutY 를 주면 그 높이에서 **잘라** 돌려준다 (de Casteljau).
  //
  // ⚠️ **밑단이 짧다고 곡선을 눌러 담으면 안 된다.** 예전에는 하의가
  // `min(엉덩이 끝, 밑단-6)` 에서 다리 폭이 되도록 곡선을 억지로 세웠는데,
  // 그러면 하의가 몸보다 가팔라져 **그 사이로 엉덩이가 비쳤다** (반바지에서 y 224~236).
  // 몸과 **같은 곡선**을 쓰고 밑단에서 자르면 어디서 잘라도 몸 바깥에 남는다.
  // ─── 엉덩이는 허벅지에 «기대어» 닿는다 ────────────────────
  //
  // ⚠️ **수직으로 내려앉으면 허벅지와 만나는 자리에 모서리가 진다.** 마지막 제어점을
  // 끝점과 같은 x 에 두면 도착 접선이 세로인데, 그 아래 허벅지는 이미 비스듬히
  // 내려가는 중이라 둘이 각을 이룬다 — 옆선이 「울퉁불퉁」해 보이던 것이 이것이다.
  // 제어점을 **그 높이의 허벅지만큼** 밖으로 물려 두면 접선이 그대로 이어진다.
  // 자리는 안 바뀐다 — 끝점은 그대로다.
  //
  // ⚠️ **몸과 옷이 같은 값을 봐야 한다.** 몸의 엉덩이 path 는 `torsoArms` 안에 손으로
  // 적혀 있고 하의는 `hipSideCurve` 를 쓴다 — 두 자리가 이 함수 하나를 부른다.
  function hipLean(tune, x0, x3) {
    const HY = hipApexBot(tune), BY = hipBlendY(tune), hb = (BY - HY) * HIP_C[1];
    // **접선**으로 잡는다 — 1px 위아래의 기울기 × 제어점 높이.
    // 활(secant)로 재면(`BY-hb` 와 `BY` 의 차) 볼록한 곡선에서는 늘 더 커서
    // 엉덩이가 허벅지 밖으로 부풀고, 그만큼 그림 상자를 넘본다 (실제로 25줄이 잘렸다)
    const slope = thighOuterAt(tune, Math.max(LEG.hipY, BY - 1)) - thighOuterAt(tune, BY);
    return Math.max(0, Math.min(slope * hb, Math.max(0, (x0 - x3) * 0.6)));
  }
  function hipSideCurve(tune, x0, x3, cutY) {
    const HY = hipApexBot(tune), BY = hipBlendY(tune);
    const hb1 = (BY - HY) * HIP_C[0], hb = (BY - HY) * HIP_C[1];
    const lean = hipLean(tune, x0, x3);
    let P = [[x0, HY], [x0, HY + hb1], [x3 + lean, BY - hb], [x3, BY]];
    if (cutY != null && cutY < BY) {
      const yAt = t => {
        const u = 1 - t;
        return u * u * u * P[0][1] + 3 * u * u * t * P[1][1] + 3 * u * t * t * P[2][1] + t * t * t * P[3][1];
      };
      let lo = 0, hi = 1;                     // y 는 t 에 대해 단조증가한다
      for (let i = 0; i < 24; i++) { const m = (lo + hi) / 2; if (yAt(m) < cutY) lo = m; else hi = m; }
      const t = (lo + hi) / 2;
      const mid = (a, b) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
      const a1 = mid(P[0], P[1]), b1 = mid(P[1], P[2]), c1 = mid(P[2], P[3]);
      const a2 = mid(a1, b1), b2 = mid(b1, c1);
      P = [P[0], a1, a2, mid(a2, b2)];
    }
    return P.map(pt => [+pt[0].toFixed(2), +pt[1].toFixed(2)]);
  }

  // 다리 — 허리(waistY)를 올린 만큼 통째로 올라오고 그만큼 길어진다.
  // 바닥은 고정이므로 위 끝만 올라가고 길이가 늘어난다: 허벅지 186~263 · 종아리 256~331.
  // (예전 값 204~272 / 266~332 를 k=1.1266 으로 늘린 자리다 — BODY.waistY 주석 참고)
  // 허벅지 아래 끝과 종아리 위 끝은 7px 겹쳐 둔다. 안 겹치면 무릎에서 배경이 비친다
  //
  // ⚠️ **굵기 배율의 축은 안쪽 변이다** — 가운데가 아니다.
  // 가운데를 축으로 하면 가늘게 만들 때 안쪽 변도 같이 밖으로 밀려 **다리 사이가 벌어진다**
  // (허벅지 60% 에서 틈이 4px → 12px). 체지방이 빠져도 다리 사이는 그대로 붙어 있고
  // 살은 **바깥쪽에서** 빠진다 — 체지방 15~45% 사진을 견줘 보면 그렇다.
  // 안쪽 변을 축으로 두면 굵어지든 가늘어지든 **틈이 일정**하다.
  // ─── 다리는 원통이 아니다 ──────────────────────────────────
  //
  // 예전에는 허벅지·종아리가 **네모(rect)를 가로로 늘린 것**이었다. 그래서 굵게 하면
  // 무릎도 발목도 같이 굵어져 **통나무**가 됐다. 실제 여자 다리는 그렇게 안 생겼다 —
  // **관절(무릎·발목)은 거의 그대로**고, 허벅지 위쪽과 장딴지만 곡선으로 부푼다.
  //
  // 그래서 마디마다 「살이 붙는 곳」과 「안 붙는 곳」을 나눠 둔다:
  //   허벅지  위(엉덩이 밑)가 가장 굵다 → 무릎으로 가늘어진다
  //   종아리  무릎에서 장딴지로 부풀었다가 → 발목으로 가늘어진다
  //
  // ⚠️ **관절은 「중심선에서 잰 거리」로 잡는다.** 허벅지와 종아리는 안쪽 변이 서로 달라서
  // (2 / 3), 폭을 맞추면 무릎에서 바깥 변이 어긋나 1px 턱이 진다.
  //
  // ⚠️ **안쪽 변은 배율을 안 탄다** — 가늘게 만들어도 다리 사이가 안 벌어진다.
  // 체지방이 빠져도 살은 **바깥쪽에서** 빠진다 (체지방 15~45% 사진).
  // 살을 재는 기준선 (중심선에서 잰 거리). **둘이 같아야** 무릎 안쪽이 안 어긋난다.
  // 실제로 그려지는 안쪽 변은 아래의 `innerX` 다 — 이 값은 「살이 여기서부터 붙는다」는 기준일 뿐
  const THIGH_GAP = 2, CALF_GAP = 2;
  const LEG = {
    hipY: 186, kneeY: 263, calfY: 256, ankleY: 331,
    bellyT: 0.28,                         // 장딴지가 가장 굵은 곳 (종아리 구간의 비율)
    // ⚠️ 허벅지의 기본 폭은 **한 번 올렸다** (20 → 36). 「예전 150% 가 지금 100%」다.
    // 200% 의 두께는 그대로 두려고 `TUNE_GAIN.thigh` 를 1.6 → 0.444 로 같이 낮췄다
    // ⚠️ 종아리 살(`bellyW`)을 한 번 10% 줄였다 (18 → 16.2). 「모든 파츠를 최소로
    // 했을 때 종아리가 아직 굵다」는 판단이었다 — 실루엣으로 50% 에서 9.3 → 8.4px 다.
    // 이 값 하나가 종아리·무릎 상한·발목·무릎 불룩까지 다 정한다 (허벅지는 `hipW` 다)
    hipW: 36, bellyW: 16.2,               // 배율을 타는 살 (안쪽 변에서 잰 폭)
    kneeX: 17, ankleX: 14,                // 배율을 **안 타는** 관절 (중심선에서 잰 거리)
  };
  // ─── 관절도 살을 타긴 탄다 — 다만 훨씬 덜 탄다 ───────────────
  //
  // 무릎을 **아예 고정**해 두었더니 허벅지 200% 에서 42 → 17 로 좁아져 **깔때기**가 됐다.
  // 종아리까지 200% 면 그 아래가 다시 38 로 부풀어, 무릎만 잘록한 모래시계가 된다.
  // 살이 찐 사람은 무릎도 굵다 — 다만 허벅지·장딴지만큼은 아니다.
  // **팔의 팔꿈치와 같은 몫(40%)** 을 태운다 (`ARM_W` · `armWidths` 참고).
  //
  // ⚠️ **발목은 그대로 둔다.** 「굵은 종아리에 가는 발목」은 일부러 그렇게 잡은 그림이고
  // (`checkavatar` 의 「발목」이 지킨다), 발목까지 굵어지면 다시 통나무가 된다.
  //
  // ⚠️ 무릎은 **허벅지·종아리 중 굵은 쪽**을 따른다. 둘을 평균 내면 한쪽만 굵게 했을 때
  // 무릎이 어중간하게 굵어져 가는 쪽 마디에 턱이 진다. 그리고 아래의 상한이 있어서
  // **가는 쪽보다 굵어지지는 않는다** — 허벅지만 200% 면 무릎은 종아리에 막혀 그대로다.
  const KNEE_K = 0.4;                       // 관절이 배율을 타는 몫
  // ─── 무릎은 **허벅지와의 비율**을 지킨다 ───────────────────────
  //
  // 위의 40% 만으로는 모자랐다. 허벅지 윗머리는 38 → 57.6 으로 1.5배가 되는데
  // 무릎은 17 → 21 로 1.24배밖에 안 커서, **허벅지 아래쪽이 무릎 쪽으로 끌려 내려가
  // 깔때기가 됐다** — 슬라이더를 전부 끝까지 올렸을 때 무릎(20.5)이 장딴지(30.5)보다
  // 가늘어, 다리 위쪽이 아래쪽보다 얇아 보였다 (실제로 그런 신고를 받았다).
  //
  // `thighOuterAt` 이 허벅지를 «윗머리 → 무릎» 으로 잇기 때문에, 무릎이 안 따라오면
  // 허벅지 전체가 같이 가늘어진다. **무릎을 고치는 것이 곧 허벅지를 고치는 것이다.**
  // 그래서 기본 그림의 비율(17/38)을 바닥으로 깔아 둔다 — 100% 에서는 딱 17 이라
  // 기본 체형이 한 톨도 안 움직인다.
  // 다리 바깥 변(허벅지·종아리)의 제어점 높이 비율.
  // ⚠️ **`limbPath`(그리는 곳)와 `thighOuterAt`(재는 곳)이 반드시 같은 값을 써야 한다.**
  // 두 벌로 두었다가 7.3px 어긋나 엉덩이 이음매에 턱이 졌던 자리다.
  // 값을 키우면 곡선이 양 끝을 더 오래 붙들어 **가운데가 둥글어지고**, 낮추면
  // 곧은 사선에 가까워진다 — 「허벅지 라인을 둥글게」가 이 값이다 (0.45 → 0.52).
  const LIMB_C = 0.52;
  // ─── 허벅지만 «비대칭»이다 ─────────────────────────────────
  //
  // ⚠️ 위아래를 같은 값으로 두면(대칭) 허벅지가 **넓은 채로 한참 내려오다가 갑자기**
  // 좁아진다 — 종아리 옆으로 자락이 길게 늘어져 「울퉁불퉁」해 보이던 것이 그것이다.
  // 실제 다리는 **엉덩이 밑에서 빨리 빠지고 무릎으로는 완만히** 붙는다.
  //   앞(위) 값이 작을수록 윗머리를 빨리 떠나고, 뒤(아래) 값이 클수록 무릎에 일찍
  //   나란해진다. 둘의 합이 1 을 넘으면 곡선이 스스로를 넘어가니 그 밑으로 둔다.
  // ⚠️ **둘의 합이 1 이 되면 안 된다.** 앞을 0.34 · 뒤를 0.66 으로 두었더니
  // 위 제어점(y0+0.34h)과 아래 제어점(y1−0.66h = y0+0.34h)이 **정확히 같은 높이**에
  // 겹쳤다 — 그러면 곡선이 위에서만 돌고 **아래는 직선으로 내리꽂는다.**
  // 재어 보니 통통 최대에서 **36줄이 기울기 −1.12 로 똑같았다** (거의 자로 그은 선).
  // 부풀림(셋째 값)을 아무리 키워도 안 먹히던 이유가 이것이다.
  const THIGH_C = [0.45, 0.45];
  // ─── 굵어질수록 옆선이 «볼록»해진다 ───────────────────────
  //
  // ⚠️ **늘 같은 모양으로 두면 안 된다.** 셋째 제어점을 끝점(무릎)의 x 에 두면
  // 옆선이 위는 볼록 · 아래는 «오목»한 S 가 된다. 가는 다리에서는 그게 맞지만
  // **굵은 다리에서는 종아리 옆으로 꼬리가 늘어져 뾰족해 보인다** —
  // 그 제어점을 바깥으로 물리면 옆선이 통째로 **볼록한 덩어리**가 된다.
  //
  // ⚠️ **100% 이하는 건드리지 않는다** (가는 다리까지 부풀리면 통나무가 된다).
  // 배율이 100% 를 «넘는 만큼»만 태운다 — 100% 0 → 200% THIGH_BULGE.
  const THIGH_BULGE = 1.4;
  const thighBul = tune => THIGH_BULGE * overOf(tune, 'thigh');
  const thighC = tune => [THIGH_C[0], THIGH_C[1], thighBul(tune)];
  const KNEE_THIGH = LEG.kneeX / (THIGH_GAP + LEG.hipW);      // 0.447 — 기본 그림의 비율
  // ⚠️ **종아리 상한을 「장딴지의 85%」로 못 박아 두면 안 된다.** 허벅지만 200% 로
  // 올렸을 때 윗머리는 61.5 인데 무릎이 17 에 묶여 **다리가 막대기로 끝났다.**
  // 규칙 한 줄로 다시 잡는다 — **무릎은 허벅지를 따라가되, 장딴지보다 굵어지지는 않는다.**
  //   · 평소(허벅지가 가만히 있을 때)는 예전 그대로 장딴지의 85% 다
  //   · 허벅지가 커지면 거기까지 따라 올라가고, 장딴지의 제일 굵은 곳에서 멈춘다
  const kneeCalfCap = tune => Math.min(
    CALF_GAP + LEG.bellyW * fatOf(tune, 'calf'),                        // 장딴지보다는 안 굵다
    Math.max(CALF_GAP + LEG.bellyW * fatOf(tune, 'calf') * 0.85,        // 평소엔 그 85%
             thighTop(tune) * KNEE_THIGH));                             // 허벅지가 크면 거기까지
  const kneeX = tune => Math.min(
    Math.max(
      LEG.kneeX * (1 - KNEE_K + KNEE_K * Math.max(fatOf(tune, 'thigh'), fatOf(tune, 'calf'))),
      thighTop(tune) * KNEE_THIGH),
    thighTop(tune) * 0.85,          // 골반이 좁아 윗머리가 들어오면 무릎도 따라 들어온다
    kneeCalfCap(tune));
  const ankleX = tune => Math.min(LEG.ankleX, CALF_GAP + LEG.bellyW * fatOf(tune, 'calf') * 0.8);
  // 장딴지가 가장 굵은 자리 — **불어나는 양이 클수록 아래로 내려간다.**
  // 자리를 붙박아 두면 무릎(263)에서 장딴지(277)까지 **14px 안에** 살을 다 붙여야 해서,
  // 종아리 200% 에서는 그 사이에 19px 이 불어나 **바깥으로 뾰족한 마름모**가 됐다.
  // 엉덩이가 처지는 것(`hipGeom`)과 같은 규칙이다 — 많이 나온 것은 내려갈 거리도 길다.
  // 기본값(불어나는 양 3px)에서는 한 톨도 안 움직인다
  const BELLY_SLIDE = 0.008, BELLY_SLIDE_MAX = 0.18;
  function bellyYOf(tune) {
    const rise = (CALF_GAP + LEG.bellyW * fatOf(tune, 'calf')) - kneeX(tune);
    const base = LEG.bellyW - LEG.kneeX + CALF_GAP;      // 기본값의 불어나는 양 (3)
    const t = LEG.bellyT + Math.min(BELLY_SLIDE_MAX, Math.max(0, rise - base) * BELLY_SLIDE);
    return +(LEG.calfY + (LEG.ankleY - LEG.calfY) * t).toFixed(1);
  }

  // ─── 안쪽 변도 곧은 선이 아니다 ────────────────────────────
  //
  // 바깥 변은 마디마다 곡선인데 **안쪽 변만 자로 그은 세로선**이라, 허리 아래부터
  // 발목까지 145px 이 폭 하나 없이 내려왔다 — 다리 사이가 칼로 벤 틈처럼 보였다.
  // 살이 붙은 자리는 안쪽에도 붙는다:
  //   허벅지 위(내전근)가 가장 두꺼워 **거의 붙고** → 무릎 위에서 벌어졌다가
  //   무릎에서 다시 모이고 → 장딴지 안쪽이 볼록했다가 → 발목에서 발만큼 벌어진다
  //
  // ⚠️ **배율을 안 탄다.** 허벅지·종아리를 가늘게 해도 다리 사이는 그대로여야 한다
  // (「다리는 일정 간격을 두고 모여 있어야 한다」 — 위의 축 주석과 같은 규칙).
  // 여기에 배율을 태우면 살을 뺄 때 다리가 벌어진다.
  //
  // ⚠️ **허벅지와 종아리가 같은 함수를 지난다.** 둘은 7px 겹쳐 있어서, 안쪽 변을
  // 따로 잡으면 겹치는 구간에서 둘 중 안쪽에 있는 것이 이겨 이음매에 턱이 진다.
  const INNER = [
    [186, 0.9],    // 허벅지 맨 위 — 엉덩이에 가려 안 보이는 자리
    [216, 1.1],    // 엉덩이 밑(hipBottom+2) — 내전근이 가장 두꺼워 거의 붙는다 (틈 2.2)
    [238, 2.6],    // 허벅지 가운데 — 가장 벌어진다 (틈 5.2)
    [263, 2.1],    // 무릎 — 다시 모인다 (틈 4.2)
    [286, 1.4],    // 장딴지 — 안쪽으로 볼록 (틈 2.8)
    [331, 3.4],    // 발목 — 발이 벌어진 만큼 (틈 6.8)
  ];
  function innerX(y) {
    if (y <= INNER[0][0]) return INNER[0][1];
    for (let i = 1; i < INNER.length; i++) {
      const p = INNER[i - 1], q = INNER[i];
      if (y > q[0]) continue;
      const u = (y - p[0]) / (q[0] - p[0]);
      return p[1] + (q[1] - p[1]) * u * u * (3 - 2 * u);   // 매듭에서 접선이 세로
    }
    return INNER[INNER.length - 1][1];
  }
  // 구간 [y0,y1] 안의 안쪽 변 매듭 (양 끝 포함) — 위→아래
  function innerPts(y0, y1) {
    const pts = [[y0, innerX(y0)]];
    INNER.forEach(k => { if (k[0] > y0 + 0.5 && k[0] < y1 - 0.5) pts.push(k); });
    pts.push([y1, innerX(y1)]);
    return pts;
  }

  // ─── 가랑이 홈 (바지·반바지) ─────────────────────────────────
  //
  // ⚠️ **홈은 다리 사이 틈을 그대로 따라간다.** 예전에는 폭 14(x 93~107)짜리 고정 V
  // 였는데, 그 높이의 실제 틈은 5 밖에 안 된다 — 그래서 **홈 안으로 허벅지 안쪽
  // 살이 그대로 드러났다** (반바지에서 제일 크게 보였다).
  //
  // 틈보다 `INSEAM_OVER` 만큼 **좁게** 판다. 그래야 천이 다리 안쪽을 조금 덮어
  // 어느 배율에서도 사이로 살이 안 비친다. 좁아지다 0 이 되는 높이에서 홈이 닫힌다.
  const INSEAM_OVER = 1.0;
  const inseamHalf = y => innerX(y) - INSEAM_OVER;
  // 홈이 닫히는 높이. **엉덩이 아래(hipBottom+2)보다 위로는 안 판다** —
  // 거기부터는 엉덩이라, 파면 엉덩이 살이 홈으로 드러난다
  function inseamTop(hemY) {
    const lo = BODY.hipBottom + 2;
    for (let y = hemY; y > lo; y -= 0.5) if (inseamHalf(y) <= 0) return +y.toFixed(1);
    return lo;
  }
  // 밑단에서 시작해 꼭짓점을 돌아 다시 밑단으로 내려오는 홈.
  // 다리 안쪽 변과 **같은 방식**(매듭마다 세로 접선)으로 그려 이음매가 안 진다
  function inseam(hemY) {
    const half = inseamHalf(hemY);
    if (half <= 0) return { x0: 100, x1: 100, d: '' };   // 틈이 없으면 안 판다
    const top = inseamTop(hemY);
    const up = innerPts(top, hemY).map(k => [k[0], Math.max(0, k[1] - INSEAM_OVER)]).reverse();
    const seg = (p, q, s) => {
      const h = (q[0] - p[0]) * 0.45;
      return ` C${(100 + s * p[1]).toFixed(2)},${(p[0] + h).toFixed(1)}`
        + ` ${(100 + s * q[1]).toFixed(2)},${(q[0] - h).toFixed(1)}`
        + ` ${(100 + s * q[1]).toFixed(2)},${q[0].toFixed(1)}`;
    };
    let d = '';
    for (let i = 1; i < up.length; i++) d += seg(up[i - 1], up[i], 1);    // 오른쪽 변을 타고 올라간다
    for (let i = up.length - 1; i >= 1; i--) d += seg(up[i], up[i - 1], -1); // 왼쪽 변으로 내려온다
    return { x0: +(100 + half).toFixed(2), x1: +(100 - half).toFixed(2), d };
  }

  // 다리 마디 하나. 마디마다 **세로 접선**으로 이어져 어느 배율에서도 안 꺾인다.
  //   s 오른쪽이면 +1 · pts [[y, 중심선에서 잰 바깥 거리], ...] 위→아래
  //   (안쪽 변은 innerX 가 정한다)
  function limbPath(s, pts, c) {
    const ca = (c && c[0]) || LIMB_C, cb = (c && c[1]) || LIMB_C, bul = (c && c[2]) || 0;
    const X = n => +(100 + s * n).toFixed(2);
    const a = pts[0], z = pts[pts.length - 1];
    // 마개는 폭의 절반을 못 넘는다 (안쪽 변이 y 마다 다르므로 그 자리의 폭으로 잰다)
    const cap = p => Math.max(1, Math.min(5, (p[1] - innerX(p[0])) / 2));
    const r0 = cap(a), r1 = cap(z);
    const iTop = X(innerX(a[0])), iBot = X(innerX(z[0]));
    let d = `M${iTop},${a[0]} L${X(a[1] - r0)},${a[0]} Q${X(a[1])},${a[0]} ${X(a[1])},${(a[0] + r0).toFixed(1)}`;
    for (let i = 1; i < pts.length; i++) {
      const p = pts[i - 1], q = pts[i];
      const y0 = i === 1 ? p[0] + r0 : p[0];
      const y1 = i === pts.length - 1 ? q[0] - r1 : q[0];
      // thighOuterAt 와 **같은** 값이어야 한다 (허벅지는 비대칭이다)
      const ha = (y1 - y0) * ca, hb = (y1 - y0) * cb;
      const bx = q[1] + (p[1] - q[1]) * bul;                 // thighOuterAt 와 **같은** 값
      d += ` C${X(p[1])},${(y0 + ha).toFixed(1)} ${X(bx)},${(y1 - hb).toFixed(1)} ${X(q[1])},${y1.toFixed(1)}`;
    }
    d += ` Q${X(z[1])},${z[0]} ${X(z[1] - r1)},${z[0]} L${iBot},${z[0]}`;
    // 안쪽 변을 **아래에서 위로** 되짚어 올라간다 (바깥과 같은 세로 접선)
    const ip = innerPts(a[0], z[0]).reverse();
    for (let i = 1; i < ip.length; i++) {
      const p = ip[i - 1], q = ip[i];
      const h = (q[0] - p[0]) * 0.45;                       // 위로 가므로 음수다
      d += ` C${X(p[1])},${(p[0] + h).toFixed(1)} ${X(q[1])},${(q[0] - h).toFixed(1)} ${X(q[1])},${q[0].toFixed(1)}`;
    }
    return `<path d="${d} Z" fill="${SKIN}"/>`;
  }

  function legs(tune) {
    const L = LEG, kt = fatOf(tune, 'thigh'), kc = fatOf(tune, 'calf');
    const kx = kneeX(tune), ax = ankleX(tune);
    const bellyY = bellyYOf(tune);
    // 윗머리는 **골반을 따라 들어온다** — 그리는 값도 `thighTop` 한 곳에서 나와야
    // 엉덩이가 재는 폭(`thighOuterAt`)과 어긋나지 않는다
    const thigh = [[L.hipY, thighTop(tune)], [L.kneeY, kx]];
    const calf = [[L.calfY, kx], [bellyY, CALF_GAP + L.bellyW * kc], [L.ankleY, ax]];
    const fy = BODY.footY, fx = footX(tune);
    return `
      <g data-part="calf">
        ${limbPath(-1, calf)}
        ${limbPath(1, calf)}
      </g>
      <ellipse cx="${fx}" cy="${fy}" rx="12" ry="7" fill="${SKIN_SH}"/>
      <ellipse cx="${200 - fx}" cy="${fy}" rx="12" ry="7" fill="${SKIN_SH}"/>
      <g data-part="thigh">
        ${limbPath(-1, thigh, thighC(tune))}
        ${limbPath(1, thigh, thighC(tune))}
      </g>`;
  }

  // ─── 목 ───────────────────────────────────────────────────────
  //
  // 턱 밑 그늘은 **아래로 갈수록 사라진다.** 예전에는 통째로 SKIN_SH 인 네모라
  // 턱과 몸통(둘 다 SKIN) 사이에 어두운 띠가 딱 잘려 보였다 — 넥라인을 파고 나서
  // 목이 드러나자 그 띠가 그대로 눈에 띄었다.
  //
  // 끝나는 높이를 **몸통 맨 윗선(108)** 에 맞추는 것이 핵심이다. 거기서 색이
  // SKIN 과 같아지므로 몸통이 목을 덮는 자리에 경계가 아예 생기지 않는다.
  // 시작(98)은 턱보다 위다 — 턱은 체형에 따라 101~106 사이를 오르내리는데(머리 배율),
  // 어디에 있든 그 지점의 그러데이션 중간값에서 시작해 자연스럽게 옅어진다.
  const NECK_SHADE_TOP = 98;

  // 목은 아래에서 **어깨 쪽으로 벌어진다.** 곧은 네모로 두면 넥라인을 판 자리 옆에
  // 옷도 몸도 없는 곳이 생겨 배경이 비쳤다 (몸통 돔은 가운데만 높아서, 목 옆
  // x 109~113 은 y 110 이 되어야 비로소 몸통이 올라온다).
  // 벌어지는 곳(y 104~)은 턱보다 아래라 얼굴 밑이 넓어 보이지도 않는다.
  // 목 굵기는 **얼굴 반폭과 어깨 반폭의 평균**에서 나온다.
  //
  // 고정 폭이면 안 되는 이유: 머리는 등신 비율(headK)과 「얼굴」 배율을, 어깨는 체형과
  // 「몸통」 배율을 탄다. 목만 고정이면 얼굴을 키웠을 때 목이 가늘어 보이고,
  // 어깨를 넓혔을 때 목이 몸에 안 붙어 보인다 — 어느 쪽도 사람 몸으로 안 읽힌다.
  //
  // 두 계수는 **지금 모습(반폭 9)을 기준으로 역산한 값**이다. 기본값에서는
  // (32.3×0.27 + 36×0.26) / 2 ≈ 9.0 이라 예전 그림과 같다.
  const NECK_OF_FACE = 0.27, NECK_OF_SHOULDER = 0.26;

  //   top   목의 윗변 y (**턱에 맞춘다** — build 가 계산해서 넘긴다)
  //   half  목의 반폭
  //
  // ⚠️ 윗변을 96 으로 박아 두면 안 된다. 머리는 NECK_LIFT 만큼 위로 올라가는데
  // 목이 그 자리에 남아 **턱과 목 사이가 벌어진다** (실제로 그렇게 배포됐다).
  //   maxR 목이 벌어져도 좋은 가장 바깥 x (= 몸통 어깨 끝). 넘으면 몸통이 못 덮는다
  function neckShape(uid, top, half, maxR) {
    const B = BODY;
    const L = +(100 - half).toFixed(1), R = +(100 + half).toFixed(1);
    // 벌어지기 시작하는 곳은 **몸통 윗선(108) 바로 위**다. 그보다 위에서 벌리면
    // 안 판 옷(폴라)의 어깨선 위로 살이 1px 삐져나온다. 108 아래는 어차피 몸통도
    // 같은 살색이라 어떤 모양이든 이음매가 안 보인다 — 그래서 아래에서만 크게 벌린다
    //
    // ⚠️ **벌어지는 폭은 어깨를 넘지 못한다.** 목은 몸통보다 **먼저** 그려져 몸통이 덮어
    // 주는데, 몸통 배율을 줄이면 어깨가 좁아져 이 자락이 어깨 밖으로 삐져나온다 —
    // 몸통 50% 에서 어깨 끝 117.5 / 목자락 123.5 로 **6px 짜리 부리**가 생겼다.
    // 팔이 100% 일 때는 팔이 그 위를 덮어 안 보였고, 팔까지 가늘게 하면 드러났다.
    // (「몸통50 팔50 에서만 어깨가 튀어나온다」의 정체가 이것이다)
    const mid = B.torsoTopY - 1, bot = B.neckBottom;
    const F = maxR == null ? 17 : Math.max(0, Math.min(17, maxR - R - 1));
    return `<path d="M${L},${+top.toFixed(1)} L${R},${+top.toFixed(1)} L${R},${mid}
        C${R + 3},${mid + 1} ${R + F},${mid + 3} ${R + F},${bot} L${L - F},${bot}
        C${L - F},${mid + 3} ${L - 3},${mid + 1} ${L},${mid} Z" fill="url(#neckG_${uid})"/>`;
  }

  // 몸통 윗선(오른쪽 반)의 x 에서의 y.
  // **넥라인은 이 선보다 위를 팔 수 없다** — 파면 옷도 몸도 없는 자리가 되어 배경이 비친다.
  // x 는 t 에 대해 단조증가하므로 이분법으로 찾는다.
  function torsoTopAtX(x) {
    const P = [[100, BODY.torsoTopY]].concat(BODY.shoulderC);
    const at = t => {
      const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
      return [a * P[0][0] + b * P[1][0] + c * P[2][0] + d * P[3][0],
              a * P[0][1] + b * P[1][1] + c * P[2][1] + d * P[3][1]];
    };
    let lo = 0, hi = 1;
    for (let i = 0; i < 24; i++) { const m = (lo + hi) / 2; if (at(m)[0] < x) lo = m; else hi = m; }
    return at((lo + hi) / 2)[1];
  }
  function neckDefs(uid) {
    return `<linearGradient id="neckG_${uid}" gradientUnits="userSpaceOnUse"
        x1="0" y1="${NECK_SHADE_TOP}" x2="0" y2="${BODY.torsoTopY}">
        <stop offset="0" stop-color="${SKIN_SH}"/><stop offset="1" stop-color="${SKIN}"/>
      </linearGradient>`;
  }

  function torsoArms(tune, uid, neck) {
    const kb = tuneOf(tune, 'torso');   // 팔 배율은 armShape 이 알아서 따른다
    const B = BODY, wh = waistHalf(tune);
    const wL = +(100 - wh).toFixed(2), wR = +(100 + wh).toFixed(2);
    // ─── 엉덩이 — 허리와 허벅지를 **접선이 이어지게** 잇는다 ───
    //
    // 허리·엉덩이·허벅지는 배율이 서로 다르다. 예전에는 엉덩이 path 를 통째로
    // `sx(kh, 100)` 으로 늘려서 **허리에 닿는 점과 허벅지에 닿는 점까지 같이 늘어났다** —
    // 엉덩이만 키우면 위 이음매가 몸통 옆선 밖으로 튀어나오고, 아랫변이 허벅지보다
    // 넓어져 두 자리에 계단이 생겼다 (허리를 줄이면 위쪽이, 엉덩이를 키우면 아래쪽이).
    //
    // 그래서 세 점을 **각자 제 배율로 절대 좌표에 놓고** 그 사이를 곡선으로 잇는다.
    // 세 점 모두 **세로 접선**이라 어느 배율을 움직여도 이음매가 꺾이지 않는다:
    //   · 허리(WY)      실루엣의 가장 좁은 곳 — 몸통 옆선도 여기서 세로로 들어온다
    //   · 엉덩이(HY)    가장 넓은 곳. **중력으로 처져서** hipY 보다 아래에 온다
    //   · 허벅지(BY)    허벅지 바깥 변에 세로로 내려꽂아 그대로 다리로 이어진다.
    //                   **바깥 변보다 1px 안쪽**이라 그 아래는 허벅지 제 옆선이 이어받는다
    //                   (딱 맞추면 1px 턱이 져서 **가느다란 선**으로 보인다)
    // 제어점의 높이는 구간 길이의 45% 다 — 비율이라 구간이 길어지면 봉우리도 같이 둥글어진다.
    const WY = B.waistY, HB = B.hipBottom;
    const HY1 = hipApexTop(tune), HY2 = hipApexBot(tune), BY = hipBlendY(tune);
    const wRa = +(100 + wh * kb).toFixed(2), wLa = +(200 - wRa).toFixed(2);
    const tRa = +(100 + thighJoin(tune)).toFixed(2), tLa = +(200 - tRa).toFixed(2);
    const hRa = +(100 + hipHalf(tune)).toFixed(2), hLa = +(200 - hRa).toFixed(2);
    // 허리 → 엉덩이 봉우리 곡선의 제어점 높이 (구간 길이에 대한 몫).
    // 위쪽을 짧게·아래쪽을 길게 잡으면 **세로에서 빨리 벗어나 일찍 눕는다** —
    // 같은 폭을 더 완만하게 벌린다
    const haT = +((HY1 - WY) * HIP_UP_C[0]).toFixed(1);
    const haB = +((HY1 - WY) * HIP_UP_C[1]).toFixed(1);
    // ⚠️ **허리→엉덩이 옆선의 위쪽 절반은 «오목»할 수밖에 없다.** 허리에서 접선이
    // 세로여야 몸통과 안 꺾이는데(그 위 `wR` 주석), 세로로 출발해서 바깥으로 벌어지는
    // 곡선은 출발부가 반드시 현(弦) 안쪽을 지난다 — 재어 보면 y176~198 이 곡률 −0.5 다.
    // ⚠️ **위 제어점을 엉덩이 쪽으로 밀어 봤는데 더 나빴다** (0.5 로 밀었을 때
    // y180 의 곡률이 −0.5 → **−1.25**). 벌어지는 것을 몇 줄에 몰아넣을 뿐이라
    // 「완만한 오목」이 「급한 꺾임」이 된다. 되돌렸다 — 여기서 고칠 것이 아니다.
    const hb1 = +((BY - HY2) * HIP_C[0]).toFixed(1), hb = +((BY - HY2) * HIP_C[1]).toFixed(1);
    // 허벅지에 기대어 닿는 몫 — 하의(`hipSideCurve`)와 **같은 함수**에서 나온다
    const ln = +hipLean(tune, hipHalf(tune), thighJoin(tune)).toFixed(2);
    const tRc = +(tRa + ln).toFixed(2), tLc = +(tLa - ln).toFixed(2);

    // 몸통 옆선이 허리로 좁아지는 곡선. 제어점을 어깨(133)~허리 사이의 **비율**로 잡아,
    // waistY 를 올리고 내려도 곡선 모양이 그대로 따라오게 한다.
    // 마지막 제어점의 x 는 **허리와 같다** — 그래야 허리에서 접선이 세로가 되어
    // 엉덩이 곡선과 꺾이지 않고 이어진다. 예전에는 `wR + 3` 이라 몸통이 안쪽으로
    // 기울어 들어오는데 엉덩이는 바깥으로 나가, 허리에 40°짜리 꺾임이 있었다
    // 어깨 곡선 — 오른쪽 반은 그대로, 왼쪽 반은 x 를 100 기준으로 뒤집어 쓴다.
    // **팔보다 튀어나오지 않게 좁힌다** (shoulderSquash 참고). f=1 이면 그대로다
    const f = shoulderSquash(tune);
    const sc = B.shoulderC.map(pt => [sqx(pt[0], f), pt[1]]);
    const shR = sqx(B.torsoR, f), shL = sqx(B.torsoL, f);
    const mir = (pt) => [200 - pt[0], pt[1]];
    const cy1 = +(133 + (B.waistY - 133) * 0.46).toFixed(1);
    const cy2 = +(133 + (B.waistY - 133) * 0.68).toFixed(1);
    // 목이 벌어져도 좋은 한계 = 몸통의 어깨 끝(절대 좌표).
    // 몸통은 kb 로 늘어나지만 목은 그 그룹 밖이라 여기서 직접 환산해 넘긴다
    const tipAbs = 100 + (shR - 100) * kb;
    return `
      ${neckShape(uid, neck.top, neck.half, tipAbs)}
      <g data-part="hip">
        <path d="M${wLa},${WY}
          C${wLa},${WY + haT} ${hLa},${HY1 - haB} ${hLa},${HY1}
          L${hLa},${HY2}
          C${hLa},${HY2 + hb1} ${tLc},${BY - hb} ${tLa},${BY}
          L${tLa},${HB}
          L${tRa},${HB}
          L${tRa},${BY}
          C${tRc},${BY - hb} ${hRa},${HY2 + hb1} ${hRa},${HY2}
          L${hRa},${HY1}
          C${hRa},${HY1 - haB} ${wRa},${WY + haT} ${wRa},${WY} Z" fill="${SKIN}"/>
      </g>
      <g data-part="torso">
        <g${sx(kb, 100)}><path d="M100,${B.torsoTopY}
          C${sc[0][0]},${sc[0][1]} ${sc[1][0]},${sc[1][1]} ${sc[2][0]},${sc[2][1]}
          C${shR},${cy1} ${wR},${cy2} ${wR},${B.waistY}
          L${wL},${B.waistY}
          C${wL},${cy2} ${shL},${cy1} ${shL},${sc[2][1]}
          C${mir(sc[1])[0]},${sc[1][1]} ${mir(sc[0])[0]},${sc[0][1]} 100,${B.torsoTopY} Z" fill="${SKIN}"/></g>
      </g>
      <g data-part="arm">
        ${armShape('L', SKIN, 0, BODY.armH, tune)}
        ${armShape('R', SKIN, 0, BODY.armH, tune)}
        ${hands(tune, SKIN)}
      </g>`;
  }

  // 얼굴(피부) + 귀 + 표정
  // ═══════════════════════════════════════════════════════════════
  //  아바타 얼굴의 부품 표 (「표정」 옷장 항목이 쓴다)
  // ═══════════════════════════════════════════════════════════════
  //
  // ⚠️ **여섯 가지뿐이었다.** 초상화(`portrait.js`)와 인트로 그림(`intro.js`)은
  // 서른여덟으로 늘렸는데 **마이 룸의 얼굴만 여섯**이라, 「표정 6/6」이 그대로 남아 있었다.
  // 계통이 셋인데 이름만 늘려서는 안 늘어난다 — 세 곳 다 손대야 한다.
  //
  // ⚠️ **원래 있던 여섯은 `switch` 로 그대로 둔다.** 세이브에 그 id 가 들어 있고
  // (`exp_puzzled` 는 시작 아이템이다) 이미 눈에 익은 얼굴이라 바뀌면 안 된다.
  // 이 표는 **그 뒤에** 걸린다.
  //
  // 좌표: 눈 (87,75)·(113,75) · 입 (100,89)
  // ─── 얼굴 부품의 «자리» ──────────────────────────────────────
  //
  // ⚠️ **인트로 공주의 좌표를 그대로 옮겨 왔다가 되돌렸다.** 두 얼굴 타원을 맞춰
  // 옮기면 눈 75 → 65.8 · 입 89 → 81.7 이 되는데, 화면에서 보니 **눈이 이마 쪽으로
  // 몰려 얼굴이 위아래로 갈라져** 보였다. 공주는 반신·정면 한 컷이고 아바타는
  // 전신에 표정 서른여덟이라, **같은 좌표가 같은 인상을 주지 않는다.**
  // 「이 둘을 닮게 한다」는 좌표를 맞추는 것이 아니라 **머리 모양과 앞머리**로 할 일이다.
  const AV = { L: 87, R: 113, Y: 75, MX: 100, MY: 89, INK: '#4a3a42', LIP: '#c97b86' };
  // ─── 눈 — **크고 반짝인다** ──────────────────────────────────
  //
  // 결은 「스파이 패밀리」의 아냐 쪽이다: **눈이 얼굴의 반**이고 하이라이트가 둘 이상,
  // 입은 작고, 감정은 눈썹과 눈의 «모양»이 진다. 그래서 기본 눈부터 키웠다
  // (예전 rx5 → 6.4). 작은 눈은 「점눈」처럼 **일부러 작게 하는 것**만 남긴다.
  // ⚠️ **한 번 「아니메답게」 층으로 다시 짰다가 되돌렸다.**
  // 흰자·홍채·아래쪽 밝은 반달·동공·속눈썹으로 겹을 쌓아 봤는데,
  // 그림은 «사실적»이 됐지만 **귀엽지 않았다** — 이 얼굴의 결은 치비 쪽이고,
  // 거기서는 **먹으로 꽉 찬 큰 눈동자에 하이라이트 둘**이 더 세다.
  // 다시 층을 쌓으려거든 그 판단부터 다시 할 것 (`git show ab5968a` 에 그 판이 있다).
  //
  // 원래 있던 여섯(`switch`)이 쓰는 눈 — 「어리둥절」 크기로 맞췄다.
  // ⚠️ 예전에는 방긋·윙크가 rx 5, 놀람이 r 6, 어리둥절만 rx 7 이라 **같은 얼굴인데
  // 표정만 고르면 눈 크기가 들쭉날쭉**했다
  function bigEye(x, o) {
    o = o || {};
    const y = AV.Y + (o.dy || 0), rx = o.rx || 7, ry = o.ry || 8;
    return `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${AV.INK}"/>`
      + `<circle cx="${x + 2.5}" cy="${y - 3.5}" r="2.6" fill="#fff"/>`
      + `<circle cx="${x - 2.5}" cy="${y + 3.5}" r="1.2" fill="#fff" opacity="0.7"/>`;
  }
  const aEye = {
    // 기본 — 큰 눈에 하이라이트 둘 (위 큰 것 · 아래 작은 것). 이 둘이 「촉촉함」을 만든다
    open:  x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.4" ry="8" fill="${AV.INK}"/>`
              + `<circle cx="${x + 2.2}" cy="${AV.Y - 3.2}" r="2.4" fill="#fff"/>`
              + `<circle cx="${x - 2.2}" cy="${AV.Y + 3.4}" r="1.2" fill="#fff" opacity="0.85"/>`,
    // 더 크게 — 놀람·궁금. 흰자가 보여 눈을 「부릅뜬」 느낌이 난다
    big:   x => `<ellipse cx="${x}" cy="${AV.Y}" rx="8" ry="9.6" fill="#fff" stroke="${AV.INK}" stroke-width="1.2"/>`
              + `<ellipse cx="${x}" cy="${AV.Y + 0.6}" rx="5.4" ry="6.6" fill="${AV.INK}"/>`
              + `<circle cx="${x + 2}" cy="${AV.Y - 2.6}" r="2.2" fill="#fff"/>`
              + `<circle cx="${x - 2}" cy="${AV.Y + 4}" r="1.1" fill="#fff" opacity="0.85"/>`,
    // 반짝 — 기대·감탄. 하이라이트가 «별»이다
    sparkle: x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.6" ry="8.2" fill="${AV.INK}"/>`
              + `<path d="M${x + 1.8},${AV.Y - 6} l1.1,2.4 2.4,1.1 -2.4,1.1 -1.1,2.4 -1.1,-2.4 -2.4,-1.1 2.4,-1.1 Z" fill="#fff"/>`
              + `<circle cx="${x - 2.4}" cy="${AV.Y + 3.4}" r="1.6" fill="#fff"/>`,
    // 그렁그렁 — 울먹임·부탁. **아냐의 대표 얼굴**이다: 눈물이 고여 흔들린다
    wobble: x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.8" ry="8.4" fill="${AV.INK}"/>`
              + `<ellipse cx="${x}" cy="${AV.Y + 3.4}" rx="5.4" ry="3.4" fill="#bfe3f5" opacity="0.9"/>`
              + `<circle cx="${x + 2.2}" cy="${AV.Y - 3.4}" r="2.4" fill="#fff"/>`
              + `<circle cx="${x - 2.4}" cy="${AV.Y + 1.2}" r="1.3" fill="#fff"/>`,
    // 점눈 — 김빠짐·질색. **작아지는 것 자체가 농담**이라 크게 만들지 않는다
    dot:   x => `<circle cx="${x}" cy="${AV.Y}" r="2.2" fill="${AV.INK}"/>`,
    // ─── 무거운 윗눈꺼풀 ─────────────────────────────────────
    // 결은 「장송의 프리렌」 쪽이다: **두꺼운 윗꺼풀 한 줄**로 눈을 거의 덮고,
    // 감정은 그 꺼풀의 «기울기»와 아주 작은 입으로만 진다. 아냐(큰 눈)와 반대 축이라
    // 둘을 같이 두면 표정의 폭이 넓어진다.
    lid:   x => `<path d="M${x - 6.6},${AV.Y - 1.6} q6.6,-1.2 13.2,0" stroke="${AV.INK}" stroke-width="3.4" fill="none" stroke-linecap="round"/>`
              + `<path d="M${x - 4.6},${AV.Y + 1.8} q4.6,1.6 9.2,0" stroke="${AV.INK}" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.55"/>`,
    // 바깥이 처진 꺼풀 — 나른함·체념. 같은 부품에서 각만 바꾼다
    lidLow: (x) => {
      const f = x < 100 ? 1 : -1;
      return `<path d="M${x - 6.6},${AV.Y - 3.4 + f * 1.6} q6.6,0.6 13.2,${-f * 3.2}" stroke="${AV.INK}" stroke-width="3.4" fill="none" stroke-linecap="round"/>`;
    },
    // ─── 「페른」 결 — 곧은 윗꺼풀이 큰 눈의 위를 «자른다» ─────
    // 위의 `lid`(프리렌)가 눈을 거의 덮어 버리는 것과 반대다: **눈은 크게 열려 있는데
    // 윗꺼풀만 곧게 내려와** 있어서, 눈빛의 힘은 그대로인 채 못마땅함이 얹힌다.
    // 이 한 부품이 「조용히 화난 얼굴」을 맡는다 — 눈썹을 낮게(`aBrow` 의 low) 깔면 완성된다
    jito:  x => `<ellipse cx="${x}" cy="${AV.Y + 0.6}" rx="6.4" ry="7.4" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<circle cx="${x}" cy="${AV.Y + 1.2}" r="4.6" fill="${AV.INK}"/>`
              + `<circle cx="${x + 1.8}" cy="${AV.Y - 0.8}" r="1.5" fill="#fff"/>`
              + `<path d="M${x - 6.6},${AV.Y - 4.8} L${x + 6.6},${AV.Y - 4.8}" stroke="${AV.INK}" stroke-width="4.2" stroke-linecap="round"/>`,
    // 같은 꺼풀에 눈동자만 옆으로 — 곁눈질. 「말은 안 하지만 보고 있다」
    jside: x => `<ellipse cx="${x}" cy="${AV.Y + 0.6}" rx="6.4" ry="7.4" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<circle cx="${x + 2.4}" cy="${AV.Y + 1.2}" r="4.4" fill="${AV.INK}"/>`
              + `<circle cx="${x + 3.8}" cy="${AV.Y - 0.6}" r="1.4" fill="#fff"/>`
              + `<path d="M${x - 6.6},${AV.Y - 4.8} L${x + 6.6},${AV.Y - 4.8}" stroke="${AV.INK}" stroke-width="4.2" stroke-linecap="round"/>`,
    // >_< — 박장대소·질색. 감은 눈보다 힘이 세다
    tight: x => `<path d="M${x - 6},${AV.Y - 4.4} L${x + 1},${AV.Y} L${x - 6},${AV.Y + 4.4}"`
              + ` stroke="${AV.INK}" stroke-width="2.8" fill="none" stroke-linecap="round" stroke-linejoin="round"`
              + ` transform="${x > 100 ? `scale(-1,1) translate(${-2 * x},0)` : ''}"/>`,
    arc:   x => `<path d="M${x - 6.4},${AV.Y + 1.4} Q${x},${AV.Y - 7} ${x + 6.4},${AV.Y + 1.4}" stroke="${AV.INK}" stroke-width="3" fill="none" stroke-linecap="round"/>`,
    shut:  x => `<path d="M${x - 6.4},${AV.Y - 1.4} Q${x},${AV.Y + 6} ${x + 6.4},${AV.Y - 1.4}" stroke="${AV.INK}" stroke-width="2.8" fill="none" stroke-linecap="round"/>`,
    half:  x => `<path d="M${x - 6.4},${AV.Y - 3.4} L${x + 6.4},${AV.Y - 3.4}" stroke="${AV.INK}" stroke-width="2.6" stroke-linecap="round"/>`
              + `<path d="M${x - 5.4},${AV.Y - 3.4} a5.4,6.4 0 0 0 10.8,0 Z" fill="${AV.INK}"/>`
              + `<circle cx="${x + 1.8}" cy="${AV.Y - 0.4}" r="1.4" fill="#fff"/>`,
    slit:  x => `<path d="M${x - 6.4},${AV.Y - 1.8} q6.4,-2.4 12.8,0 q-6.4,5 -12.8,0 Z" fill="${AV.INK}"/>`,
    sharp: x => `<path d="M${x - 6.8},${AV.Y - 3.8} L${x + 6.8},${AV.Y} L${x - 6.8},${AV.Y + 3.8} Z" fill="${AV.INK}"/>`
              + `<circle cx="${x - 3}" cy="${AV.Y - 0.6}" r="1.2" fill="#fff" opacity="0.8"/>`,
    low:   x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.4" ry="7.6" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<ellipse cx="${x}" cy="${AV.Y + 2.6}" rx="4.4" ry="4.8" fill="${AV.INK}"/>`
              + `<circle cx="${x + 1.6}" cy="${AV.Y + 0.8}" r="1.5" fill="#fff"/>`,
    up:    x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.4" ry="7.8" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<ellipse cx="${x}" cy="${AV.Y - 2.6}" rx="4.4" ry="4.8" fill="${AV.INK}"/>`
              + `<circle cx="${x + 1.6}" cy="${AV.Y - 4.4}" r="1.5" fill="#fff"/>`,
    side:  x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.4" ry="7.4" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<ellipse cx="${x + 2.4}" cy="${AV.Y}" rx="4.2" ry="4.8" fill="${AV.INK}"/>`
              + `<circle cx="${x + 3.6}" cy="${AV.Y - 1.8}" r="1.4" fill="#fff"/>`,
    wide:  x => `<ellipse cx="${x}" cy="${AV.Y}" rx="7.4" ry="9" fill="#fff" stroke="${AV.INK}" stroke-width="1.2"/>`
              + `<circle cx="${x}" cy="${AV.Y}" r="4.2" fill="${AV.INK}"/><circle cx="${x + 1.6}" cy="${AV.Y - 2.4}" r="1.6" fill="#fff"/>`,
    glare: x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.6" ry="7.8" fill="#fff" stroke="${AV.INK}" stroke-width="1.1"/>`
              + `<circle cx="${x}" cy="${AV.Y - 2.4}" r="3.6" fill="${AV.INK}"/>`
              + `<path d="M${x - 7},${AV.Y - 6} L${x + 7},${AV.Y - 6}" stroke="${AV.INK}" stroke-width="2.6" stroke-linecap="round"/>`,
    star:  x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.6" ry="8.2" fill="${AV.INK}"/>`
              + `<circle cx="${x + 2}" cy="${AV.Y - 3.2}" r="2.6" fill="#fff"/><circle cx="${x - 2.4}" cy="${AV.Y + 3.2}" r="1.5" fill="#fff"/>`,
    heart: x => `<path d="M${x},${AV.Y + 6} C${x - 8},${AV.Y - 2} ${x - 7},${AV.Y - 10} ${x - 2.8},${AV.Y - 10} q2.8,0 2.8,3.4 q0,-3.4 2.8,-3.4 c4.2,0 5.6,8 -2.8,16 Z" fill="#e2557f"/>`
              + `<circle cx="${x - 2}" cy="${AV.Y - 3}" r="1.4" fill="#fff" opacity="0.9"/>`,
    cross: x => `<path d="M${x - 5},${AV.Y - 4.6} L${x + 5},${AV.Y + 4.6} M${x + 5},${AV.Y - 4.6} L${x - 5},${AV.Y + 4.6}" stroke="${AV.INK}" stroke-width="2.8" stroke-linecap="round"/>`,
    dizzy: x => `<path d="M${x},${AV.Y} m-5.4,0 a5.4,5.4 0 1 1 3.6,5.2 a3.6,3.6 0 1 1 2,-6.8" stroke="${AV.INK}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    teary: x => `<ellipse cx="${x}" cy="${AV.Y}" rx="6.4" ry="8" fill="${AV.INK}"/>`
              + `<circle cx="${x + 2.2}" cy="${AV.Y - 3.2}" r="2.4" fill="#fff"/>`
              + `<path d="M${x + 5},${AV.Y + 5.4} q2.6,4.8 0,7.2 q-2.6,-2.4 0,-7.2 Z" fill="#8fc5e8"/>`,
  };
  // ─── 입 — **작다** ──────────────────────────────────────────
  // 눈이 커진 만큼 입은 작아야 균형이 맞는다. 「ω」 같은 고양이 입이 이 결의 핵심이다
  const aMouth = {
    calm:  `<path d="M${AV.MX - 4},${AV.MY} q4,2.6 8,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    // 아주 작은 입 — 프리렌 결. 얼굴이 커도 입이 작으면 표정이 «조용»해진다
    tiny:  `<path d="M${AV.MX - 2.6},${AV.MY} q2.6,2 5.2,0" stroke="${AV.LIP}" stroke-width="2" fill="none" stroke-linecap="round"/>`,
    // 작은 ω — 같은 결의 «조용한 귀여움»
    wee:   `<path d="M${AV.MX - 4},${AV.MY} q2,2.8 4,0 q2,2.8 4,0" stroke="${AV.LIP}" stroke-width="2" fill="none" stroke-linecap="round"/>`,
    smile: `<path d="M${AV.MX - 5},${AV.MY} q5,4.6 10,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    // ω — 고양이 입. 아무 감정에도 안 붙는 대신 **귀여움 그 자체**를 맡는다
    w:     `<path d="M${AV.MX - 6},${AV.MY} q3,4 6,0 q3,4 6,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    grin:  `<path d="M${AV.MX - 6},${AV.MY - 1} q6,8 12,0 z" fill="#e98a9a"/><path d="M${AV.MX - 4.4},${AV.MY} q4.4,2 8.8,0" fill="#fff"/>`,
    haha:  `<path d="M${AV.MX - 8},${AV.MY - 1} q8,12 16,0 z" fill="#b5566a"/><path d="M${AV.MX - 5.6},${AV.MY} q5.6,2.6 11.2,0" fill="#fff"/>`
         + `<ellipse cx="${AV.MX}" cy="${AV.MY + 5.4}" rx="3" ry="2" fill="#d98f96"/>`,
    flat:  `<path d="M${AV.MX - 4},${AV.MY + 1} L${AV.MX + 4},${AV.MY + 1}" stroke="${AV.LIP}" stroke-width="2.2" stroke-linecap="round"/>`,
    // へ — 못마땅하게 꾹 다문 작은 입 (페른 결). `frown` 보다 작고 얕다 —
    // 슬픔이 아니라 «참고 있는 것»이라 크게 그리면 울상이 된다
    hmm:   `<path d="M${AV.MX - 3.6},${AV.MY + 2.2} q3.6,-3.2 7.2,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    frown: `<path d="M${AV.MX - 5},${AV.MY + 3.4} q5,-5 10,0" stroke="${AV.LIP}" stroke-width="2.4" fill="none" stroke-linecap="round"/>`,
    small: `<ellipse cx="${AV.MX}" cy="${AV.MY + 1}" rx="2.6" ry="3" fill="#b5566a"/>`,
    ohh:   `<ellipse cx="${AV.MX}" cy="${AV.MY + 1}" rx="3.4" ry="4.4" fill="#b5566a"/>`,
    smirk: `<path d="M${AV.MX - 5},${AV.MY + 2} q6,2.6 10,-3" stroke="${AV.LIP}" stroke-width="2.4" fill="none" stroke-linecap="round"/>`,
    meh:   `<path d="M${AV.MX - 5},${AV.MY + 1} q2.5,-2.4 5,0 q2.5,2.4 5,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    wavy:  `<path d="M${AV.MX - 6},${AV.MY + 1} q2,-2.6 4,0 q2,2.6 4,0 q2,-2.6 4,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`,
    grit:  `<rect x="${AV.MX - 7}" y="${AV.MY - 1.6}" width="14" height="6" rx="2" fill="#b5566a"/>`
         + `<rect x="${AV.MX - 6}" y="${AV.MY - 0.8}" width="12" height="4.4" rx="1.4" fill="#fff"/>`,
    bite:  `<path d="M${AV.MX - 5},${AV.MY} q5,2.2 10,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`
         + `<path d="M${AV.MX - 2.6},${AV.MY + 2.2} q2.6,2.4 5.2,0" stroke="#c9808a" stroke-width="1.8" fill="none" stroke-linecap="round"/>`,
    pout:  `<path d="M${AV.MX - 5},${AV.MY + 2} q5,-2 10,2.4" stroke="${AV.LIP}" stroke-width="2.4" fill="none" stroke-linecap="round"/>`,
    tongue: `<path d="M${AV.MX - 5},${AV.MY} q5,4.4 10,0" stroke="${AV.LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`
          + `<path d="M${AV.MX - 2.6},${AV.MY + 1.4} q2.6,5.6 5.2,0 z" fill="#e2557f"/>`,
  };
  // ─── 눈썹 — **안쪽과 바깥쪽을 나눈다** ───────────────────────
  //
  // ⚠️ 예전 식은 안팎을 안 가르고 y 만 `f` 로 흔들었다. 그래서 화난 얼굴인데
  // **왼쪽 눈썹은 평평하고 오른쪽만 기울어** 있었다 — 좌우가 안 맞는 것이
  // 「딱딱하다」의 큰 몫이었다. 눈(87·113) 기준으로 **안쪽은 x+7f · 바깥쪽은 x−7f**
  // 라고 적으면 대칭은 저절로 따라온다 (f = +1 왼눈 · −1 오른눈).
  //
  // ⚠️ **곧은 선(`L`)으로 긋지 않는다.** 사람 눈썹에는 늘 결이 있어서 화난 눈썹도
  // 얕게 휜다. 1px 도 안 되는 휨인데 얼굴이 통째로 부드러워진다.
  //   [안쪽 y, 바깥쪽 y, 휨(음수면 위로 아치)]
  const BROW = {
    flat:  [62.2, 62.2, -1.2],
    up:    [59.8, 58.4, -1.6],   // 둘 다 치켜올림 — 놀람·의문·우쭐
    angry: [65.4, 57.8, -1.0],   // 안쪽이 내려온다
    sad:   [57.6, 64.6,  1.2],   // 팔자 — 안쪽이 올라간다
    beg:   [56.6, 65.4,  2.2],   // 팔자를 더 세게 (애원)
    droop: [61.2, 65.4, -1.2],   // 바깥이 처진다 (지침·안도)
    low:   [65.4, 64.4, -0.8],   // 낮고 곧게 (페른 결)
  };
  // ⚠️ **지금은 눈썹을 안 그린다.** 표를 다 만들어 놓고 재어 본 결과 —
  // 눈이 얼굴의 반이나 되는 치비 얼굴에서는 **눈썹이 없는 쪽이 더 귀엽다.**
  // 화남·슬픔처럼 눈썹이 맡던 몫은 **만화 기호**(💢 · 절망선 · 💧)가 대신 진다.
  // 표와 함수는 그대로 둔다 — 되살리려면 이 한 줄만 true 로 바꾸면 된다.
  const SHOW_BROW = false;
  const aBrow = (kind) => (x, f) => {
    const b = BROW[kind] || BROW.flat;
    const xi = x + 7 * f, xo = x - 7 * f;
    const cy = (b[0] + b[1]) / 2 + b[2] * 2;
    return `<path d="M${xo},${b[1]} Q${(xi + xo) / 2},${cy.toFixed(1)} ${xi},${b[0]}"`
      + ` stroke="${AV.INK}" stroke-width="2.3" fill="none" stroke-linecap="round"/>`;
  };
  // ─── 만화 기호 — «과장»은 얼굴 밖에서 온다 ──────────────────
  //
  // ⚠️ **눈·입만 키워서는 과장이 안 된다.** 놀란 얼굴과 그냥 눈을 부릅뜬 얼굴이
  // 안 갈린다. 아니메가 쓰는 것은 **얼굴에 붙는 기호**다 — 땀방울 · 💢 · 볼의
  // 세로선 · 반짝임 · 소용돌이 · 한숨. 이 한 겹이 표정의 세기를 통째로 올린다.
  //
  // ⚠️ **머리 위에는 못 둔다** — 앞머리가 덮는다 (「어리둥절」의 물음표를
  // 눈썹으로 바꿔야 했던 것과 같은 이유다). 그래서 전부 **관자놀이~볼**에 붙인다.
  // 얼굴 타원은 cx100 rx33 이고 귀가 67·133 이라, 안전한 자리는 x 70~80 · 120~130 이다.
  // ⚠️ **눈썹을 피해야 한다.** 눈썹이 x 80~94 · 106~120 을 쓰므로 기호는 그 «바깥»이다 —
  // 안쪽에 두면 화난 눈썹 위에 💢 가 겹쳐 둘 다 못 알아본다
  const FX_L = 74, FX_R = 126;                 // 왼·오른 관자놀이
  const aFx = {
    // 땀방울 — 놀람·당황·미안. 한 방울이면 족하다 (둘이면 아파 보인다)
    sweat: `<path d="M${FX_R + 2},64 q3.2,4.6 0,6.6 q-3.2,-2 0,-6.6 Z" fill="#9ad4f0"/>`
         + `<ellipse cx="${FX_R + 1.2}" cy="${68.4}" rx="0.8" ry="1.2" fill="#e6f5fc"/>`,
    // 💢 — 화남·노려봄. **네 변이 안으로 패인 네모**가 그 기호의 모양이다
    // (귀퉁이 선 넷으로 그렸더니 그냥 점선 네모로 보였다)
    // ⚠️ 45도 돌려야 한다 — 안 돌리면 그냥 **네 갈래 별**이라 「반짝임」으로 읽힌다
    anger: `<path transform="translate(${FX_R + 3},70) rotate(45)"`
         + ` d="M0,-5.4 Q1.1,-1.1 5.4,0 Q1.1,1.1 0,5.4 Q-1.1,1.1 -5.4,0 Q-1.1,-1.1 0,-5.4 Z" fill="#e2557f"/>`,
    // 볼의 세로선 — 부끄러움. 홍조 «위»에 얹혀야 부끄러움이 된다
    blush: `<g stroke="#ff8fb0" stroke-width="1" stroke-linecap="round" opacity="0.8">`
         + [-4.4, 0, 4.4].map(d => `<path d="M${77 + d},83.4 L${77 + d},88.4"/><path d="M${123 + d},83.4 L${123 + d},88.4"/>`).join('')
         + `</g>`,
    // 반짝 — 기대·감탄·결심. 크기가 다른 별 둘이라야 「반짝인다」
    spark: [[FX_L - 2, 62, 3.2], [FX_R + 2, 66, 2.2], [FX_R - 1, 58, 1.6]]
      .map(([x, y, r]) => `<path d="M${x},${y - r} l${r * 0.42},${r * 0.58} ${r * 0.58},${r * 0.42}`
        + ` -${r * 0.58},${r * 0.42} -${r * 0.42},${r * 0.58} -${r * 0.42},-${r * 0.58}`
        + ` -${r * 0.58},-${r * 0.42} ${r * 0.58},-${r * 0.42} Z" fill="#ffd76e"/>`).join(''),
    // 소용돌이 — 어질어질
    swirl: `<path d="M${FX_R + 2},62 m-4,0 a4,4 0 1 1 2.6,3.8 a2.6,2.6 0 1 1 1.4,-4.9"`
         + ` stroke="#9a8aa6" stroke-width="1.5" fill="none" stroke-linecap="round"/>`,
    // 한숨 — 지침·안도. 입가에서 옆으로 새어 나간다
    puff:  `<g fill="#cfd8e0" opacity="0.75"><circle cx="${FX_R - 8}" cy="92" r="2.2"/>`
         + `<circle cx="${FX_R - 3.4}" cy="94" r="1.6"/><circle cx="${FX_R}" cy="95.4" r="1"/></g>`,
    // 💤 — 졸림
    zzz:   `<g stroke="#8fa6bd" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round">`
         + `<path d="M${FX_R},62 h4 l-4,4 h4"/><path d="M${FX_R + 5},56 h3 l-3,3 h3"/></g>`,
    // 하트가 튀어오른다 — 반함
    hearts: [[FX_L - 3, 62, 1], [FX_R + 3, 65, 0.8], [FX_R - 1, 57, 0.6]]
      .map(([x, y, k]) => `<path transform="translate(${x},${y}) scale(${k})"`
        + ` d="M0,4 C-4.4,-0.6 -3.8,-5.2 -1.4,-5.2 q1.4,0 1.4,1.8 q0,-1.8 1.4,-1.8 c2.4,0 3,4.6 -1.4,9.2 Z" fill="#e2557f"/>`).join(''),
    // 절망의 세로선 — 슬픔·기절. 볼에 드리운다 (이마는 앞머리가 덮는다)
    gloom: `<g stroke="#7d8a99" stroke-width="1.1" stroke-linecap="round" opacity="0.5">`
         + [0, 3.4, 6.8].map(d => `<path d="M${71 + d},84 L${71 + d},93"/><path d="M${122 + d},84 L${122 + d},93"/>`).join('')
         + `</g>`,
    // ? — 궁금·미심쩍음
    q:     `<g stroke="${AV.INK}" stroke-width="1.7" fill="none" stroke-linecap="round" opacity="0.75">`
         + `<path d="M${FX_R},60 q0,-3.4 2.8,-3.4 q2.8,0 2.8,2.6 q0,2.2 -2.8,3 v1.2"/></g>`
         + `<circle cx="${FX_R + 2.8}" cy="66.4" r="1" fill="${AV.INK}" opacity="0.75"/>`,
    // ♪ — 다정·활짝
    note:  `<g fill="${AV.INK}" opacity="0.6"><path d="M${FX_R + 1},58 v7.4" stroke="${AV.INK}" stroke-width="1.4" stroke-linecap="round"/>`
         + `<ellipse cx="${FX_R - 0.6}" cy="65.6" rx="2" ry="1.5" transform="rotate(-18 ${FX_R - 0.6} 65.6)"/>`
         + `<path d="M${FX_R + 1},58 q2.6,0.8 3,3" stroke="${AV.INK}" stroke-width="1.4" fill="none" stroke-linecap="round"/></g>`,
    // 눈물이 튄다 — 울음. 눈 «바깥»으로 날아간다
    splash: [[FX_L - 1, 76, 1], [FX_R + 1, 76, 1], [FX_L - 4, 70, 0.7], [FX_R + 4, 70, 0.7]]
      .map(([x, y, k]) => `<ellipse cx="${x}" cy="${y}" rx="${1.8 * k}" ry="${2.6 * k}" fill="#9ad4f0" opacity="0.9"/>`).join(''),
  };
  // 원래 있던 여섯(puzzled · smile · wink · happy · surprise · cool)에 «없는» 것만
  const AV_FACE = {
    warm:    { e: 'arc',     m: 'wee', fx: 'note' },
    proud:   { e: 'sharp',   m: 'smirk',  b: 'up', fx: 'spark' },
    smirk:   { e: 'side',    m: 'smirk' },
    flat:    { e: 'lid',     m: 'tiny' },
    meh:     { e: 'lidLow',  m: 'meh' },
    sleepy:  { e: 'lidLow',  m: 'wee', fx: 'zzz' },
    think:   { e: 'up',      m: 'small' },
    doubt:   { e: 'side',    m: 'meh',    b: 'up', fx: 'q' },
    worry:   { e: 'wobble',  m: 'wavy',   b: 'sad', fx: 'sweat' },
    sad:     { e: 'low',     m: 'frown',  b: 'sad', fx: 'gloom' },
    cry:     { e: 'teary',   m: 'wavy',   b: 'sad', fx: 'splash' },
    angry:   { e: 'sharp',   m: 'frown',  b: 'angry', fx: 'anger' },
    grit:    { e: 'tight',   m: 'grit',   b: 'angry', fx: 'sweat' },
    shy:     { e: 'shut',    m: 'w',      b: 'sad', fx: 'blush' },
    ohh:     { e: 'big',     m: 'ohh' },
    star:    { e: 'sparkle', m: 'grin',   b: 'up', fx: 'spark' },
    love:    { e: 'heart',   m: 'grin', fx: 'hearts' },
    faint:   { e: 'cross',   m: 'ohh', fx: 'gloom' },
    haha:    { e: 'tight',   m: 'haha',   b: 'up', fx: 'note' },
    // 😝 는 눈을 «질끈» 감는다 — 그냥 감은 눈(‿‿)으로 그리면 이모지와 딴 얼굴이 된다
    tease:   { e: 'tight',   m: 'tongue' },
    // 😒 · 😑 는 **페른** 결이다 — 큰 눈 위를 곧은 꺼풀이 자르고 눈썹이 낮게 깔린다.
    // 화난 얼굴(`glare`)과 갈리는 자리라서 눈썹을 세우지 않는다: 조용히 못마땅한 것이지
    // 노려보는 것이 아니다
    pout:    { e: 'jito',    m: 'hmm',    b: 'low', fx: 'anger' },
    glare:   { e: 'glare',   m: 'flat',   b: 'angry', fx: 'anger' },
    suspect: { e: 'jside',   m: 'meh',    b: 'low' },
    dizzy:   { e: 'dizzy',   m: 'wavy', fx: 'swirl' },
    weary:   { e: 'lidLow',  m: 'wavy',   b: 'droop', fx: 'puff' },
    relief:  { e: 'lid',     m: 'wee',    b: 'droop', fx: 'puff' },
    sorry:   { e: 'low',     m: 'small',  b: 'beg', fx: 'gloom' },
    // **아냐의 대표 얼굴** — 눈물이 그렁그렁 고인 채 올려다본다
    plead:   { e: 'wobble',  m: 'small',  b: 'beg', fx: 'sweat' },
    blush:   { e: 'shut',    m: 'bite',   b: 'beg', fx: 'blush' },
    resolve: { e: 'sharp',   m: 'grit',   b: 'flat', fx: 'spark' },
    awe:     { e: 'sparkle', m: 'ohh', fx: 'spark' },
    curious: { e: 'big',     m: 'ohh',    bL: 'up', bR: 'flat', fx: 'q' },
  };

  // ─── 코 ────────────────────────────────────────────────────
  // ⚠️ **코가 아예 없었다.** 치비 얼굴이라 없어도 되긴 하는데, 눈과 입 사이가
  // 14px 나 비어 있어서 얼굴이 «판판»해 보였다. 아니메가 쓰는 것은 선 하나 —
  // 콧등의 그늘만 아주 옅게 찍는다. 진하면 어른 얼굴이 된다
  const NOSE = `<path d="M98.8,81.6 q1.8,2 3,0.4" stroke="#d09a8e" stroke-width="1.4"`
    + ` fill="none" stroke-linecap="round" opacity="0.6"/>`;
  // 손으로 그린 여섯에도 기호를 붙인다 — 표는 위의 `aFx` 를 그대로 쓴다
  const HAND_FX = { surprise: 'sweat', happy: 'note', wink: 'spark', puzzled: 'q' };
  // ⚠️ **기호는 머리카락 «위»에 그린다.** 얼굴 그룹 안에 두었더니 앞머리가
  // 관자놀이를 덮어 땀방울도 💢 도 반쪽만 보였다 (「어리둥절」의 물음표를 눈썹으로
  // 바꿔야 했던 것과 같은 함정이다). 얼굴 뒤에 숨을 수 없는 층에 따로 얹는다
  function faceFx(expItem) {
    const kind = (expItem && expItem.kind) || 'smile';
    const av = AV_FACE[kind];
    return aFx[av ? av.fx : HAND_FX[kind]] || '';
  }
  function faceAndExpression(expItem) {
    const kind = (expItem && expItem.kind) || 'smile';
    const EYE = '#4a3a42', LIP = '#c97b86';
    let eyes, mouth, extra = '';
    // ⚠️ **부품 표가 먼저다** — 원래 있던 여섯은 여기 없으니 아래 `switch` 로 내려간다
    const av = AV_FACE[kind];
    if (av) {
      eyes = aEye[av.e](AV.L) + aEye[av.e](AV.R);
      mouth = aMouth[av.m];
      const bL = av.bL || av.b, bR = av.bR || av.b;
      extra = !SHOW_BROW ? ''
        : (bL ? aBrow(bL)(AV.L, 1) : '') + (bR ? aBrow(bR)(AV.R, -1) : '');
    } else
    switch (kind) {
      case 'wink':
        eyes = bigEye(87) +
          `<path d="M108,76 Q113,71 118,76" stroke="${EYE}" stroke-width="2.6" fill="none" stroke-linecap="round"/>`;
        mouth = `<path d="M94,89 Q100,94 106,89" stroke="${LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`;
        break;
      case 'happy':
        eyes = `<path d="M82,77 Q87,71 92,77" stroke="${EYE}" stroke-width="2.8" fill="none" stroke-linecap="round"/>
          <path d="M108,77 Q113,71 118,77" stroke="${EYE}" stroke-width="2.8" fill="none" stroke-linecap="round"/>`;
        mouth = `<path d="M92,88 Q100,98 108,88 Z" fill="#e98a9a"/><path d="M92,88 Q100,98 108,88" stroke="${LIP}" stroke-width="2" fill="none"/>`;
        break;
      case 'surprise':
        eyes = bigEye(87) + bigEye(113);
        mouth = `<ellipse cx="100" cy="91" rx="3.6" ry="4.6" fill="#b5566a"/>`;
        break;
      case 'puzzled':
        // 어리둥절 — 큰 동그란 눈에 작게 벌린 입. 튜토리얼 직후의 얼굴이다
        eyes = bigEye(87, { dy: -1 }) + bigEye(113, { dy: -1 });
        mouth = `<ellipse cx="100" cy="90" rx="3.2" ry="3.8" fill="#b5566a"/>`;
        // 머리 위 물음표 대신 **작게 기울인 눈썹** — 이모지를 얹으면 헤어에 가린다.
        // ⚠️ 예전에는 `extra` 를 만들어 놓고 **그리지 않았다** (아래 return 에 빠져 있었다).
        // 지금은 `SHOW_BROW` 가 꺼져 있어 안 그린다 — 물음표는 `aFx.q` 가 맡는다
        extra = !SHOW_BROW ? ''
          : `<g stroke="${EYE}" stroke-width="2" fill="none" stroke-linecap="round" opacity="0.55">
            <path d="M80,63 L94,60"/><path d="M120,63 L106,60"/>
          </g>`;
        break;
      case 'cool':
        // 곧은 선 둘이던 것을 **살짝 휘게** 했다 — 그것만으로 「굳은 얼굴」이 「시크」가 된다
        eyes = `<path d="M81,76 q6,-1.6 12,-1" stroke="${EYE}" stroke-width="3" fill="none" stroke-linecap="round"/>
          <path d="M107,75 q6,0.6 12,1" stroke="${EYE}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
        mouth = `<path d="M95,90 L105,90" stroke="${LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`;
        break;
      default: // smile
        eyes = bigEye(87) + bigEye(113);
        mouth = `<path d="M94,89 Q100,94 106,89" stroke="${LIP}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`;
    }
    // '얼굴' 배율은 build() 의 H() 에서 머리 전체에 걸린다 (여기서 또 걸면 두 번 적용된다)
    return `
      <g data-part="head">
        <ellipse cx="100" cy="70" rx="33" ry="35" fill="${SKIN}"/>
        <ellipse cx="67" cy="76" rx="6" ry="9" fill="${SKIN}"/>
        <ellipse cx="133" cy="76" rx="6" ry="9" fill="${SKIN}"/>
        <ellipse cx="77" cy="86" rx="6" ry="4" fill="#ffb0c4" opacity="0.7"/>
        <ellipse cx="123" cy="86" rx="6" ry="4" fill="#ffb0c4" opacity="0.7"/>
        ${extra}
        ${eyes}
        ${NOSE}
        ${mouth}
      </g>`;
  }

  // ═══════════════════════════════════════════════════════════════
  //  헤어 (스타일 + 컬러)
  // ═══════════════════════════════════════════════════════════════
  // ─── 헤어 = 뒷머리 실루엣 × 앞머리 ───────────────────────────
  // 옷이 소매·넥라인으로 갈리듯, 머리는 이 두 축으로 갈린다.
  // 벌을 늘려도 여기 함수는 그대로다 — 데이터가 축 값만 바꿔 넣는다.
  function hairBack(kind, c) {
    const s = shade(c, 22);
    const crown = `<ellipse cx="100" cy="63" rx="40" ry="42" fill="${c}"/>`;
    switch (kind) {
      case 'bun':   // 올림머리 — 정수리 뒤로 묶은 덩어리
        return crown +
          `<ellipse cx="100" cy="27" rx="17" ry="14" fill="${c}"/>
           <ellipse cx="100" cy="27" rx="17" ry="14" fill="none" stroke="${s}" stroke-width="1.6"/>
           <path d="M74,44 Q100,34 126,44" stroke="${s}" stroke-width="2" fill="none"/>`;
      case 'bob':
        return crown +
          `<path d="M62,66 C58,92 62,110 75,112 C68,96 68,82 72,72 Z" fill="${c}"/>
           <path d="M138,66 C142,92 138,110 125,112 C132,96 132,82 128,72 Z" fill="${c}"/>`;
      case 'twin':
        return crown +
          `<ellipse cx="52" cy="132" rx="13" ry="36" fill="${c}" transform="rotate(10 52 132)"/>
           <ellipse cx="148" cy="132" rx="13" ry="36" fill="${c}" transform="rotate(-10 148 132)"/>
           <circle cx="64" cy="92" r="5.5" fill="${s}"/><circle cx="136" cy="92" r="5.5" fill="${s}"/>`;
      case 'ponytail':
        return crown +
          `<path d="M128,72 C154,92 152,150 138,182 C132,150 120,108 120,86 Z" fill="${c}"/>
           <circle cx="126" cy="78" r="5.5" fill="${s}"/>`;
      case 'wave':
        return crown +
          `<path d="M58,70 C48,100 68,120 54,152 C72,142 66,108 74,80 Z" fill="${c}"/>
           <path d="M142,70 C152,100 132,120 146,152 C128,142 134,108 126,80 Z" fill="${c}"/>`;
      default: // long
        return crown +
          `<path d="M61,66 C56,104 60,152 75,153 C66,120 66,92 72,72 Z" fill="${c}"/>
           <path d="M139,66 C144,104 140,152 125,153 C134,120 134,92 128,72 Z" fill="${c}"/>`;
    }
  }

  // 앞머리. 'wave' 는 옛 이름 — 사이드뱅과 같은 모양이라 그쪽으로 넘긴다
  function hairFront(kind, c) {
    switch (kind) {
      case 'wave':
      case 'side':        // 사이드뱅 — 한쪽으로 비스듬히 넘긴 가르마.
        // **바깥 윤곽(위쪽)은 일자뱅과 같게 둔다.** 예전에는 위가 y42 까지밖에 안 올라와
        // 얼굴 타원 꼭대기(y35)를 못 덮었고, 정수리에 살색이 그대로 드러났다.
        // 사이드뱅답게 보이는 것은 **아래쪽 가장자리의 사선**이 맡는다
        return `<path d="M68,60 C66,38 78,30 100,30 C122,30 134,38 132,60
            C131,50 126,45 118,46 C104,48 92,56 82,58 C75,59 70,56 68,60 Z" fill="${c}"/>`;
      case 'curtain':     // 커튼뱅 — 가운데를 열고 양옆으로 갈라 내린다.
        // 가르마는 **헤어라인 근처(y50)에서** 열어야 한다. 예전에는 y40 에서 갈라져
        // 정수리가 벌어져 보였다 (커튼이 아니라 가르마가 벗겨진 모양)
        return `<path d="M68,60 C66,38 78,30 100,30 C122,30 134,38 132,60
            C130,50 122,46 108,50 C104,56 101,62 100,70
            C99,62 96,56 92,50 C78,46 70,50 68,60 Z" fill="${c}"/>`;
      case 'sheer':       // 시스루뱅 — 성긴 잔머리 사이로 이마가 비친다.
        // **반투명한 면을 깔지 않는다.** 예전에는 앞머리 전체를 opacity 0.4 로 덮었는데,
        // 그 아래 살색과 섞여 이마에 **가로 띠**가 생겼다 — 시스루가 아니라 머리띠로 보였다.
        // 가닥을 따로 그리는 것도 안 됐다: 빗살처럼 규칙적이고, 가닥이 없는 양옆에는
        // 캡의 밑선이 직선으로 남았다.
        // 지금은 **한 겹의 밑단을 톱니로** 판다 — 파인 곳으로 살이 비치고 밑선이 사라진다.
        return `<path d="M68,57 C66,37 78,29 100,29 C122,29 134,37 132,57
            Q127.5,36 123,57 Q118.5,36 114,57 Q109.5,36 105,57 Q100.5,36 96,57
            Q91.5,36 87,57 Q82.5,36 78,57 Q73,36 68,57 Z" fill="${c}"/>`;
      case 'none':        // 이마 노출 — 앞머리 없이 뒤로 넘긴다
        return `<path d="M68,58 C68,38 80,30 100,30 C120,30 132,38 132,58
            C128,46 116,42 100,42 C84,42 72,46 68,58 Z" fill="${c}"/>`;
      default:            // 일자뱅 (스트레이트) — **인트로 공주와 같은 앞머리**
        // ⚠️ 밑단이 «물결»이었다 (`C126,52 116,50 108,58 C104,50 96,50 92,58 …` —
        // 봉우리 셋). 그래서 튜토리얼을 막 마친 플레이어의 아바타가 방금까지 보던
        // 인트로 공주와 **다른 사람**으로 보였다 — 공주의 앞머리는 매끈한 한 호다
        // (`intro.js` 의 `princessHead` · `M116,174 C114,146 … C132,152 120,160 116,174`).
        // 그 호를 아바타 머리 좌표로 옮겨 온 것이 아래다:
        //   세로 38(136~174) → 30(30~60) · 가로 반폭 34 → 32
        // 시작 착장이 `hair_long`(뒤=긴 생머리 · 앞=일자뱅)이라 여기 한 곳만 고치면
        // **처음 진입한 플레이어가 공주 그대로**가 된다.
        // ⚠️ 「일자뱅」을 쓰는 여섯 벌이 같이 바뀐다 — id 는 그대로라 세이브는 안전하다
        return `<path d="M68,60 C66,38 78,30 100,30 C122,30 134,38 132,60
          C128,49 117,43 100,43 C83,43 72,49 68,60 Z" fill="${c}"/>`;
    }
  }

  // 옷장 칸에 쓰는 작은 머리 그림. 30종에 겹치지 않는 이모지가 없어서,
  // **실루엣을 그대로 축소해서** 무엇인지 보이게 한다.
  // 아바타와 같은 hairBack/hairFront 를 쓰므로 머리 모양을 고치면 아이콘도 같이 바뀐다.
  function hairIcon(it, color, crop) {
    const c = color || HAIR_DEF;
    const back = (it && it.back) || (it && it.kind) || 'long';
    const bang = (it && it.bang) || 'straight';
    // 머리만 잘라 낸다. 꼬리 끝(양갈래 y168 · 포니테일 y182)까지 담으면 세로로 길어져
    // 옷장 칸에서 폭이 24px 밖에 안 나온다 — 앞머리가 구분되지 않았다.
    // 그래서 어깨 높이에서 자른다. 뒷머리 차이는 얼굴 옆 가닥에서 이미 보인다
    //
    // crop:'face' — **앞머리를 고르는 칸용.** 다섯 가지 차이는 전부 이마(y29~60)에 있는데
    // 머리 전체를 담으면 그 띠가 아이콘의 4분의 1로 줄어 사실상 같은 그림이 된다.
    // 이마부터 코까지만 담아 차이가 보이게 확대한다
    const box = crop === 'face' ? '54 18 92 76' : '42 12 116 128';
    return `<svg class="hair-icon" viewBox="${box}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      ${hairBack(back, c)}
      <ellipse cx="100" cy="78" rx="30" ry="34" fill="#ffe0cf"/>
      ${hairFront(bang, c)}
    </svg>`;
  }

  // ═══════════════════════════════════════════════════════════════
  //  옷 (상의 / 하의 / 원피스)
  // ═══════════════════════════════════════════════════════════════
  // ─── 옷의 공통 축 ─────────────────────────────────────────────
  // 실루엣(path)은 그대로 두고 **소매 길이 · 넥라인 · 단추**만 필드로 갈린다.
  // 이렇게 나눠 두면 새 옷 하나를 늘릴 때 렌더러를 건드릴 일이 없다.

  // 소매가 팔을 덮는 높이(px). BODY.armH 가 94 이므로 long 이 팔 전체다.
  // 소매 길이 — **팔 위 끝(armY)에서 잰다.** armY 를 8 올렸으므로 여기도 8 씩 더해야
  // 소매 밑단의 **절대 높이가 그대로**다 (안 더하면 모든 소매가 8px 씩 짧아진다).
  // long 이 armH 와 같은 값인 것은 「팔 끝까지」라는 뜻이다
  // 팔 길이(armH)에 맞춘 값이다 — **armH 를 바꾸면 여기도 같이 옮긴다.**
  // 안 옮기면 긴팔이 손목에 못 닿아 팔뚝이 드러난다
  const SLEEVE_H = { none: 0, cap: 27, short: 48, half: 71, long: 98 };
  function sleeveH(it) {
    const v = SLEEVE_H[it && it.sleeve];
    return v == null ? SLEEVE_H.short : v;
  }

  // ─── 넥라인 — **옷을 진짜로 판다** ───────────────────────────
  //
  // 예전에는 선으로만 그렸다. 라운드든 브이든 실루엣은 똑같고 그 위에 곡선 하나를
  // 얹을 뿐이라, 옷을 갈아입어도 목 부분이 하나도 안 변했다.
  // 지금은 몸판의 **윗변 자체**가 넥라인 모양이다.
  //
  // 파도 되는 이유는 **어깨를 안 건드리기 때문**이다. 파는 것은 가운데(±w)뿐이고
  // 어깨끈은 여전히 CLOTH_TOP_Y 에 있어서 몸통 옆·위를 그대로 덮는다.
  // 커버리지 검사는 파인 자리를 빼고 본다 (checkavatar.js) — 민소매의 팔 검사를
  // 건너뛰는 것과 같은 이유다. **파는 폭·깊이는 이 표가 유일한 원본이고,
  // 검사기도 같은 표를 읽는다** — 여기보다 크게 파면 그 바깥에서 살이 잡힌다.
  //   w = 파는 반폭 · d = CLOTH_TOP_Y 에서 내려오는 깊이
  // ⚠️ **파는 반폭은 «목에 붙여» 잡는다.** 예전에는 13·13·18 로 박혀 있었는데,
  // 목의 반폭은 얼굴 배율·몸통 배율을 타서 기본값이 **8.65** 다 — 넥라인의 입이
  // 목보다 4.35px 씩 넓어, 목의 곧은 옆선이 옷깃에 닿는 자리에서 **턱이 졌다**
  // (「옷의 목둘레랑 신체 목둘레가 안 맞는다」). 옷깃이 목의 실루엣을 가로질러
  // 자르는 모양이라, 그 사이에 뾰족한 살 조각이 남는다.
  // 이제 **목 반폭 + 스타일마다 정해진 여유**다 — 얼굴을 키워 목이 굵어지면
  // 옷깃도 같이 넓어진다.
  //   d = CLOTH_TOP_Y 에서 내려오는 깊이 (이건 스타일 그 자체라 그대로 둔다)
  //
  // ⚠️ **몸에 붙는 넥라인의 여유는 0 이다.** 목은 곧은 기둥이 아니라
  // `neckShape` 의 `mid`(=107) 부터 **바깥으로 벌어진다** — 몸통이 덮어 줄
  // 자락이라 원래 안 보여야 하는 부분이다. 여유를 조금이라도 주면 옷깃이
  // 그 자락을 **덮는 대신 비켜 가서** 벌어진 만큼이 그대로 드러난다:
  // 목 반폭 8.75 로 내려오다 옷깃 바로 위에서 10.75 로 부풀고, 옷깃은
  // 그것을 피해 11.0 에 선다 — 「옷의 목둘레와 신체 목둘레가 안 맞는」 그 턱이다.
  // 재 보면 **여유가 곧 턱의 크기**였다 (pad 1 → 1.0px · 0.5 → 0.5px · 0 → 0).
  // 0 이면 옷깃이 자락을 덮어 기둥이 그대로 이어진다 (`npm run neck` 으로 확인).
  const NECK_CUT = {
    round:  { pad: 0,  d: 13 },
    v:      { pad: 0,  d: 26 },
    // 스퀘어만 다르다 — **넓고 얕다.** 목에 붙여 파면 목이 그대로 이어져
    // 굴뚝처럼 보인다: 가슴이 양옆으로 보여야 네모로 읽힌다.
    // 여기서는 실루엣을 목이 아니라 **몸통 윗선**이 만들므로 턱이 안 진다
    square: { pad: 7,  d: 15 },
    polo:   { pad: null, d: 0 },   // 목까지 올라온다 — 안 판다
    none:   { pad: null, d: 0 },
  };
  // 목의 반폭 (몸통 좌표계). `build()` 의 `neck.half` 와 **같은 식**이다 —
  // 거기서는 몸무게까지 넣은 정확한 비(hx/kx)를 넘기고, 옷 쪽은 안 넘긴다:
  // ⚠️ hx/kx 는 몸무게 0→1 에서 0.979 → 1.024 로 **4.6% 밖에 안 움직인다**
  // (머리 배율과 가로 배율이 같이 커져 거의 상쇄된다). 옷은 몸 변환 안에서
  // 그려지므로 그 2% 를 무시하고 배율만 본다 — 대신 식은 여기 한 곳에 둔다.
  function neckHalfOf(tune, ratio) {
    const kFace = tuneOf(tune, 'face');
    const r = ratio == null ? HEAD_K_SLIM * kFace / bodyShrink(kFace) : ratio;
    return (33 * r * NECK_OF_FACE
          + (BODY.torsoR - 100) * tuneOf(tune, 'torso') * NECK_OF_SHOULDER) / 2;
  }
  function neckCut(kind, tune) {
    const c = NECK_CUT[kind] || NECK_CUT.round;
    if (c.pad == null || !c.d) return { w: 0, d: 0 };
    return { w: +(neckHalfOf(tune) + c.pad).toFixed(2), d: c.d };
  }

  // 파낸 자리 — 반폭 · 깊이 · **모서리 높이(top)**. 검사기가 이 셋을 그대로 읽는다.
  // top 을 여기서 같이 내주는 이유: 검사기가 몸통 윗선 계산을 따로 하면
  // 두 벌이 되고, 어긋나는 순간 검사가 헛돈다.
  function neckCutBox(kind, tune) {
    const cut = neckCut(kind, tune);
    if (!cut.w || !cut.d) return { w: 0, d: 0, top: 0 };
    return { w: cut.w, d: cut.d, top: +(torsoTopAtX(100 + cut.w) - 1).toFixed(1) };
  }

  // 몸판의 윗변 — 왼쪽 어깨 끝(60,132)에서 오른쪽 어깨 끝(140,132)까지.
  // `M` 부터 돌려주므로 몸판 path 의 맨 앞에 그대로 붙이면 된다.
  //
  // 파는 옷은 어깨끈이 넥라인 가장자리(100±w)에서 **수평 접선**으로 끝난다.
  // 그래야 어깨에서 목으로 넘어가는 곳이 꺾이지 않는다.
  // 파낸 **가운데 부분만.** 왼쪽 모서리(EL,K)에서 시작해 오른쪽 모서리(ER,K)로 간다.
  // 어깨는 옷마다 달라서(공주 드레스는 좁고 높다) 부르는 쪽이 각자 붙인다.
  function neckMid(kind, tune) {
    const T = CLOTH_TOP_Y, cut = neckCut(kind, tune);
    const w = cut.w, B = T + cut.d;
    const EL = 100 - w, ER = 100 + w;
    // 파낸 모서리는 **몸통 윗선 바로 위**에 둔다. 어깨끈처럼 평평하게(T) 두면
    // 모서리 안쪽에 옷도 몸도 없는 자리가 남아 배경이 비친다 — 넓게 파는
    // 스퀘어일수록 심하다 (몸통 윗선은 바깥으로 갈수록 내려간다)
    const K = neckCutBox(kind, tune).top;
    if (kind === 'v') return { K, EL, ER, d: `L100,${B} L${ER},${K}` };
    if (kind === 'square') return { K, EL, ER, d: `L${EL},${B} L${ER},${B} L${ER},${K}` };
    // 라운드 — 대칭 3차 곡선의 한가운데는 (끝점 + 제어점×3) / 4 에 온다.
    // 가운데가 정확히 B 에 닿도록 제어점을 역산한다
    const cy = +((4 * B - K) / 3).toFixed(1);
    return { K, EL, ER, d: `C${EL + 3},${cy} ${ER - 3},${cy} ${ER},${K}` };
  }

  // 옷의 어깨선 — **몸의 어깨 곡선(BODY.shoulderC)을 그대로 따라간다.**
  // 예전에는 `C120,107 140,116 140,132` 이 손으로 박혀 있었다. 몸의 어깨를 넓히자
  // x=127 에서 옷은 y=113.5 인데 몸은 y=109.4 라 **4px 짜리 살색 띠**가 어깨 위에 떴다
  // (터틀넥 30px · 블라우스 2px). 몸을 고치면 옷이 조용히 어긋나던 자리다.
  //
  // 몸보다 바깥으로 SH_PAD, 위로 1px 물러나 있어야 몸이 옷 밖으로 안 나온다.
  const SH_PAD = 4;
  // ⚠️ **위로 물러나는 것은 «가운데»뿐이다.** 어깨선을 사선으로 눕히자 같은 x 에서
  // 몸의 어깨가 더 아래에 와서, 1px 로는 모자라 **몸통 50% 에서 살이 1px 씩** 비쳤다
  // (폴라는 12px). 그렇다고 **끝점까지 올리면 거꾸로 된다** — 어깨 «끝»에서는
  // 옷이 몸보다 위에서 끝나 그 밑으로 살이 2px 보였다. 끝점은 몸과 같은 높이다.
  const shC = (i, f) => [sqx(BODY.shoulderC[i][0] + SH_PAD, f), BODY.shoulderC[i][1] - 2];
  const shoulderEndR = f => shC(2, f);
  // 옷의 어깨가 따라야 할 배율 — **몸통 배율까지 곱한다.**
  // 몸의 어깨는 `sqx(pt, squash)` 를 `sx(torso,100)` 그룹 안에서 그리므로 순 배율이
  // `squash × torso` 다. 옷이 `squash` 만 보면 몸통을 줄였을 때 **어깨만 제자리에
  // 남아** 옷이 어깨에서 붕 뜬다 (「살이 빠지면 특히 어깨가 안 맞는다」).
  const clothShoulderK = tune => shoulderSquash(tune) * tuneOf(tune, 'torso');
  function clothShoulderR(fromK, f) {
    const [a, b, c] = [shC(0, f), shC(1, f), shC(2, f)];
    // 넥라인을 판 옷은 파낸 모서리(y=fromK)에서 출발하므로 첫 제어점의 높이를 거기 맞춘다
    const y0 = fromK == null ? a[1] : fromK;
    return `C${a[0]},${y0} ${b[0]},${b[1]} ${c[0]},${c[1]}`;
  }
  function clothShoulderL(toK, f) {
    const [a, b] = [shC(0, f), shC(1, f)];
    const y0 = toK == null ? a[1] : toK;
    return `C${200 - b[0]},${b[1]} ${200 - a[0]},${y0} `;
  }
  function clothTopEdge(kind, tune) {
    const T = CLOTH_TOP_Y, cut = neckCut(kind, tune), f = clothShoulderK(tune);
    const e = shoulderEndR(f);
    const startL = `M${200 - e[0]},${e[1]}`;
    // 안 파는 옷 — 가운데가 가장 높은 돔
    if (!cut.w || !cut.d) {
      return `${startL} ${clothShoulderL(null, f)}100,${T} ${clothShoulderR(null, f)}`;
    }
    const m = neckMid(kind, tune);
    return `${startL} ${clothShoulderL(m.K, f)}${m.EL},${m.K} ${m.d} ${clothShoulderR(m.K, f)}`;
  }

  // 넥라인 위에 얹는 것 — 지금은 폴라(터틀넥)의 목 통 하나뿐이다.
  // 나머지는 파낸 모서리 자체가 넥라인이라 덧그릴 선이 없다.
  //   ty = 옷의 목 부분 윗선 y
  function neckLine(kind, c, c2, ty) {
    if (kind !== 'polo') return '';
    // ⚠️ **어깨선을 눕히면 이 통도 같이 길어져야 한다.** 20 이었을 때, 몸통 50% 에서
    // 통 아래끝과 옷의 어깨 곡선 사이로 **살이 2px** 비쳤다 (폴라만 걸렸다)
    return `<rect x="85" y="${ty - 14}" width="30" height="26" rx="9" fill="${c}"/>
      <path d="M88,${ty - 12} L112,${ty - 12}" stroke="${c2}" stroke-width="2.4" stroke-linecap="round"/>`;
  }

  // 앞섶 단추 — 중심선(x=100)에 세로로. 몸통 배율의 축도 100 이라 위치가 안 흔들린다
  function buttons(c2, y0, y1) {
    let s = '';
    for (let y = y0; y <= y1; y += 18) s += `<circle cx="100" cy="${y}" r="2.2" fill="${c2}"/>`;
    return s;
  }

  // 퍼프(어깨 볼륨) — 소매와 같은 팔 좌표를 쓰되 더 넓고 짧게 얹는다
  function puffShoulder(c, tune) {
    return armShape('L', c, 7, 24, tune) + armShape('R', c, 7, 24, tune);
  }

  // 소매는 팔을, 몸판은 몸통을 따라간다
  function renderTop(it, tune) {
    if (isNone(it)) return '';
    const B = BODY, c = it.color, c2 = shade(c);
    // ⚠️ **통째로 늘리지 않는다.** 좌표가 이미 제 몸 부위를 따라간다
    // (어깨 `clothShoulderK` · 허리 `clothWaistHalf`) — 거기에 또 곱하면 두 번 먹는다
    const ww = clothWaistHalf(tune);
    const wL = +(100 - ww).toFixed(2), wR = +(100 + ww).toFixed(2);
    // 밑단은 **골반 바로 위**까지 내려온다. 허리(WY)에 맞추면 배가 드러나 전부 크롭탑이 되고,
    // 하의 허리춤(WY 에서 시작)을 덮지 못해 그 사이로 살이 띠처럼 보인다.
    const WY = B.waistY, hem = B.hipY - 2;
    // 옷의 어깨 끝 — 몸과 **같은 자리**여야 한다 (손으로 140/60 을 박아 두면 안 된다)
    const [eR, eY] = shoulderEndR(clothShoulderK(tune)), eL = 200 - eR;
    const sc = clothSideC(eR, wR);
    return `
      ${garmentSleeves(it, tune)}
      ${it.puff ? puffShoulder(c, tune) : ''}
      <path data-part="cloth" d="${clothTopEdge(it.neck, tune)}
        C${eR},${WY - 34} ${sc},${WY - 18} ${wR},${WY}
        C${wR},${WY + 10} ${wR - 1},${hem - 8} ${wR - 4},${hem}
        C${wR - 14},${hem + 5} ${wL + 14},${hem + 5} ${wL + 4},${hem}
        C${wL + 1},${hem - 8} ${wL},${WY + 10} ${wL},${WY}
        C${200 - sc},${WY - 18} ${eL},${WY - 34} ${eL},${eY} Z" fill="${c}"/>
      ${neckLine(it.neck, c, c2, 110)}
      ${it.button ? buttons(c2, 132, hem - 14) : ''}`;
  }

  // 옷의 옆선(허리 → 엉덩이) 위에서 주어진 y 의 x 를 찾는다.
  //
  // 치마도 바지도 이 구간은 **같은 큐빅**이다:
  //   `C hR,(WY+6)  hR,(HY-6)  hR,HY`
  // ⚠️ **곡선을 두 번 적지 않는다.** 벨트가 옆선을 따라가야 하는데 좌표를 옮겨
  // 적어 두면 옆선을 고쳤을 때 벨트만 옛 자리에 남는다. 여기 한 곳에서 푼다
  function sideXAt(x0, x1, y0, y1, y) {
    const P = [[x0, y0], [x1, y0 + 6], [x1, y1 - 6], [x1, y1]];
    const at = t => {
      const u = 1 - t;
      const w = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
      return [P.reduce((a2, q, i) => a2 + w[i] * q[0], 0),
              P.reduce((a2, q, i) => a2 + w[i] * q[1], 0)];
    };
    // y 는 이 구간에서 단조 증가한다 — 이분법이면 충분하다
    let lo = 0, hi = 1;
    for (let i = 0; i < 40; i++) {
      const m = (lo + hi) / 2;
      if (at(m)[1] < y) lo = m; else hi = m;
    }
    return +at((lo + hi) / 2)[0].toFixed(2);
  }
  // 같은 옆선을 yA→yB 구간만큼 **점으로 훑는다.**
  // 위아래 두 점만 잡아 직선으로 이으면 그 사이가 곡선 «안쪽»으로 들어가
  // 띠 가운데가 2px 쯤 좁아진다 — 잰 값이 그랬다
  function sideRun(x0, x1, y0, y1, yA, yB, step) {
    const out = [];
    for (let y = yA; y < yB; y += (step || 3)) out.push([sideXAt(x0, x1, y0, y1, y), +y.toFixed(1)]);
    out.push([sideXAt(x0, x1, y0, y1, yB), +yB.toFixed(1)]);
    return out;
  }

  // 하의는 허리(몸통) + 자기가 덮는 다리 파츠를 따라간다.
  // 실루엣은 치마 계열과 바지 계열 둘뿐이고, **기장(hemY)·퍼짐(flare)·벌룬·벨트**는 필드가 정한다.
  function renderBottom(it, tune) {
    if (isNone(it)) return '';
    const B = BODY, c = it.color, c2 = shade(c);
    // 허리춤은 몸의 허리를, 옆선은 **엉덩이**를 따라간다.
    // (엉덩이가 허리보다 넓으므로 허리 폭만 보고 그리면 엉덩이 살이 옷 밖으로 나온다)
    const ww = clothWaistHalf(tune), hh = clothHipHalf(tune);
    const wL = +(100 - ww).toFixed(2), wR = +(100 + ww).toFixed(2);
    const hL = +(100 - hh).toFixed(2), hR = +(100 + hh).toFixed(2);
    const HY = hipApexY(tune), WY = B.waistY;   // 몸의 엉덩이 봉우리를 그대로 따라간다
    // 벨트 — **아래 모서리가 옷의 옆선 «위에» 있어야 한다.**
    // 옆선은 허리(wR, WY)에서 엉덩이(hR, HY)로 가는 큐빅이라 WY+14 에서는 이미
    // wR 보다 한참 바깥이다. 예전에는 허리 폭에 +1 만 해서 그렸는데,
    // 그 자리의 옷은 3.5~5.5px 더 넓어서 **띠 양옆에 옷색이 그대로 남았다**
    // (신고받았다 — 벨트가 허리를 못 두르고 가운데만 지나간 것처럼 보였다)
    const beltY = WY + 14;
    // 옆선을 **훑어서** 따라간다 (직선으로 이으면 가운데가 곡선 안쪽으로 들어간다)
    const bRun = sideRun(wR, hR, WY, HY, WY, beltY);
    const beltR = bRun.map(q => `L${q[0]},${q[1]}`).join('');
    const beltL = bRun.slice().reverse().map(q => `L${(200 - q[0]).toFixed(2)},${q[1]}`).join('');
    const belt = it.belt
      ? `<path d="M${wL},${WY} L${wR},${WY}${beltR}${beltL} Z" fill="${c2}"/>` : '';

    if (it.kind === 'skirt') {
      // 밑단은 엉덩이 폭 + flare. 벌룬은 중간이 더 부풀고 밑단이 다시 오므라든다
      const hemY = Number(it.hemY) || 252;
      const flare = Number(it.flare) || 0;
      // 퍼짐만 다리 배율을 탄다 — 허리춤·엉덩이는 이미 몸을 따라간 좌표다
      const kLeg = tuneMax(tune, hemY > KNEE_LINE ? ['thigh', 'calf'] : ['thigh']);
      const hemHalf = hh + (it.balloon ? flare * 0.25 : flare) * kLeg + 2;
      const midHalf = hh + (it.balloon ? flare + 12 : flare * 0.5) * kLeg + 2;
      const my = HY + (hemY - HY) * 0.45;      // 옆선이 가장 부푸는 높이
      const bulge = hemHalf * 0.55;            // 밑단 곡선이 아래로 처지는 폭
      // 무릎(259 = 허벅지 끝과 종아리 시작이 겹치는 자리) 아래까지 오는 치마는
      // 종아리까지 덮으므로 종아리 배율도 따라야 한다
      return `<path d="M${wL},${WY} L${wR},${WY}
          C${hR},${WY + 6} ${hR},${HY - 6} ${hR},${HY}
          C${(100 + midHalf).toFixed(1)},${my.toFixed(1)} ${(100 + hemHalf).toFixed(1)},${hemY - 18} ${(100 + hemHalf).toFixed(1)},${hemY}
          C${(100 + bulge).toFixed(1)},${hemY + 14} ${(100 - bulge).toFixed(1)},${hemY + 14} ${(100 - hemHalf).toFixed(1)},${hemY}
          C${(100 - hemHalf).toFixed(1)},${hemY - 18} ${(100 - midHalf).toFixed(1)},${my.toFixed(1)} ${hL},${HY}
          C${hL},${HY - 6} ${hL},${WY + 6} ${wL},${WY} Z" fill="${c}"/>${belt}`;
    }

    // 바지 계열 — 반바지도 같은 실루엣이고 기장만 다르다.
    // 가랑이 홈은 엉덩이 아래(hipBottom)에서 시작한다 — 위로 파면 엉덩이 살이 홈으로 드러난다
    const hemY = Math.max(B.hipBottom + 12, Number(it.hemY) || B.ankleY);
    // 옆선은 **몸의 엉덩이 곡선을 그대로 따라간다** — 다리 통 폭만 제 것으로 바꿔 끼운다.
    // 밑단이 곡선보다 위에서 끊기는 옷(반바지)은 **거기서 자른다.** 억지로 밑단까지
    // 다리 폭이 되게 눌러 담으면 하의가 몸보다 가팔라져 그 사이로 엉덩이가 비친다.
    // 다리 폭도 허벅지 배율을 따라간다 — 박아 두면 허벅지를 키웠을 때 그대로 드러난다.
    const legR = +(100 + thighOuter(tune) + CLOTH_PAD + 2).toFixed(2);
    const P = hipSideCurve(tune, hR, legR, hemY - 2);
    const by = P[3][1], bx = P[3][0], bxL = +(200 - bx).toFixed(2);
    const mirC = i => `${(200 - P[i][0]).toFixed(2)},${P[i][1]}`;
    // 가랑이 홈 — **다리 사이 틈을 그대로 따라간다** (위의 `inseam` 참고).
    // 폭을 박아 두면 그 자리의 실제 틈보다 넓어져 홈 안으로 살이 드러난다
    const cr = inseam(hemY);
    // 「바지처럼 보이게 하는 V」는 **구멍이 아니라 그늘**이다.
    // 뚫으면 그 자리의 실제 틈(반바지 밑단에서 5px)보다 넓어져 살이 드러난다 —
    // 뚫는 것은 틈만큼만 하고, 갈라진 느낌은 어두운 천으로 그린다 (ART_POLICY 플랫 2D).
    // **밑단이 가랑이 가까이 오는 옷(반바지)에만** 넣는다. 긴 바지는 홈 자체가
    // 발목까지 이어져 굳이 그늘로 알려 줄 필요가 없다
    const crease = hemY <= B.hipBottom + 44
      ? `<path d="M107,${hemY} L100,${B.hipBottom + 6} L93,${hemY} Z" fill="${shade(c, 34)}"/>` : '';
    return `<path d="M${wL},${WY} L${wR},${WY}
        C${hR},${WY + 6} ${hR},${HY - 6} ${hR},${HY}
        C${P[1][0]},${P[1][1]} ${P[2][0]},${P[2][1]} ${bx},${by}
        L${bx},${hemY} L${cr.x0},${hemY}${cr.d} L${bxL},${hemY} L${bxL},${by}
        C${mirC(2)} ${mirC(1)} ${hL},${HY}
        C${hL},${HY - 6} ${hL},${WY + 6} ${wL},${WY} Z" fill="${c}"/>${crease}${belt}`;
  }

  // 소매(팔을 덮는 부분)를 몸의 팔 좌표 그대로 만들어 준다.
  // len: 팔 길이의 몇 %까지 덮을지 (나머지는 손으로 드러남)
  //   yFrom 을 주면 그 높이부터 아래만 그린다 (치마 위에 다시 찍을 때 — armsOverSkirt)
  function sleeves(c, len, tune, yFrom, outline) {
    const B = BODY, pad = CLOTH_PAD;
    const end = B.armY - pad + B.armH * len + pad;   // 소매 끝의 절대 높이
    const from = yFrom == null ? B.armY - pad : yFrom;
    if (end <= from) return '';
    const opt = (yFrom == null && !outline) ? undefined
      : Object.assign({}, yFrom == null ? {} : { yFrom }, outline ? { outline } : {});
    // 손은 **소매 끝**에 온다 (팔 끝이 아니다) — handShape 가 armPoint 로 자리를 잡는다
    return `
      ${armShape('L', c, pad, end - from, tune, opt)}
      ${armShape('R', c, pad, end - from, tune, opt)}
      ${hands(tune, SKIN, B.armH * len)}`;
  }

  // 옷의 소매 — **한 곳에서만 만든다.** 하의 위에 다시 찍을 때도 같은 함수를 지나므로
  // 소매 길이·여유를 고치면 두 자리가 같이 따라온다.
  //   yFrom 을 주면 그 높이부터 아래만 그린다
  const SLEEVE_PAD = 2;
  const PRINCESS_LEN = 0.92;                       // 공주 드레스의 긴 소매
  function garmentSleeves(it, tune, yFrom) {
    if (isNone(it)) return '';
    const B = BODY;
    if (it.kind === 'princess') return sleeves(it.color, PRINCESS_LEN, tune, yFrom);
    const sh = sleeveH(it);
    if (!sh) return '';
    const end = B.armY - SLEEVE_PAD + sh;
    const from = yFrom == null ? B.armY - SLEEVE_PAD : yFrom;
    if (end <= from) return '';
    const opt = yFrom == null ? undefined : { yFrom };
    return armShape('L', it.color, SLEEVE_PAD, end - from, tune, opt)
         + armShape('R', it.color, SLEEVE_PAD, end - from, tune, opt);
  }

  // ─── 치마·바지보다 앞에 오는 팔 ──────────────────────────────
  //
  // 팔은 몸통과 같은 층(torsoArms)에 있어 **하의보다 뒤**다. 그런데 치마는 허리에서
  // 아래로 넓게 퍼지므로, 거기 있던 팔뚝과 손이 통째로 치마에 덮인다. 긴 치마에서는
  // 팔이 소매 끝 언저리에서 뚝 끊겨 **겨드랑이에 살색 조각만** 남는다 —
  // 「치마가 팔을 덮는다」와 「겨드랑이에 살색이 튀어나온다」가 같은 원인이다.
  //
  // ⚠️ **팔 전체를 옷 위로 올리면 안 된다.** 어깨에서 맨팔이 민소매 옷의 어깨끈을
  // 덮어 버리고(옷이 아니라 살이 보인다), 커버리지 검사의 몸통 창(x 72~128)에도 걸린다.
  // **허리 아래만 다시 찍는다** — 그 아래에 이미 같은 것이 그려져 있어 이음매가 없다.
  //
  // 공주 드레스만 예외다. 그것은 허리에서 시작하는 치마가 아니라 **어깨에서 바닥까지
  // 내려오는 종**이고, 팔은 그 안에 들어가 있다 (인트로 그림이 그렇다). 앞으로 꺼내면
  // 소매가 드레스와 같은 색이라 **손만 종 위에 동동 뜬 살색 덩어리**로 보인다.
  //
  // ⚠️ **허리부터 다시 찍으면 그 위에 «턱»이 남는다** (「옷이 팔을 파고든다」).
  // 몸판의 옆선은 허리에서 제일 좁은데(x 133) 팔의 안쪽 변은 그보다 안쪽(x 126)이라,
  // **허리 위 몇 줄만 팔이 옷 뒤에 있다.** 재어 보니 y 157~162 에서 팔의 안쪽 변이
  // 134 였다가 163 부터 126 으로 뚝 넓어졌다 — 소매 끝 바로 밑에서 팔이 8px 씩
  // 잘려 보인다. 짧은 소매·민소매 옷 **전부**가 그랬다.
  // 그래서 **소매가 끝나는 자리부터** 다시 찍는다 — 소매 밑은 곧 맨팔이어야 한다.
  // 소매도 같은 자리부터 다시 얹으므로(`garmentSleeves(wear, tune, from)`)
  // 소매가 허리보다 길든 짧든 이음매가 안 생긴다.
  //
  // ⚠️ **민소매(sleeve: 'none')는 허리 그대로 둔다.** 소매 끝이 곧 어깨라
  // 거기서부터 올리면 맨팔이 어깨끈을 덮고(옷이 아니라 살이 보인다),
  // 커버리지 검사의 몸통 창(x 72~128)에 팔의 안쪽 변(126)이 걸려
  // **민소매 상의 × 하의 전부에서 「허리 살색 15px」** 이 뜬다 (실제로 그랬다).
  // 민소매의 턱은 소매가 없어 「소매 밑에서 잘렸다」로 안 읽히므로 여기서는 손대지 않는다.
  // 소매 끝보다 이만큼 «위»에서 시작한다 — 소매 끝은 둥근 마개라 가로로 자를 수가 없다.
  // 딱 소매 끝에서 시작하면 마개가 좁아지는 두세 줄이 그대로 턱으로 남는다(7px).
  // 그 위는 소매를 같은 자리부터 다시 얹어 덮는다.
  const ARM_OVER_LAP = 12;
  const ARM_OVER_MIN = 16;      // armY 에서 이보다 위로는 못 올라간다 (어깨끈·커버리지)
  function armsOverSkirt(tune, wear) {
    const B = BODY;
    if (!isNone(wear) && wear.kind === 'princess') return '';
    const sh = isNone(wear) ? 0 : sleeveH(wear);
    const WY = sh > 0
      ? Math.max(B.armY + ARM_OVER_MIN, Math.min(B.waistY, B.armY - SLEEVE_PAD + sh - ARM_OVER_LAP))
      : B.waistY;
    const h = B.armY + B.armH - WY;
    if (h <= 0) return '';
    // data-part 를 붙여 둔다 — 검사기가 「팔」을 골라낼 때 이 조각도 같이 잡혀야 한다
    return `<g data-part="arm">${armShape('L', SKIN, 0, h, tune, { yFrom: WY })}`
         + `${armShape('R', SKIN, 0, h, tune, { yFrom: WY })}`
         + `${garmentSleeves(wear, tune, WY)}${hands(tune, SKIN)}</g>`;
  }

  // 몸통을 덮고 hemY 까지 퍼지는 드레스 (+ 팔 소매)
  // 어깨가 좁고 높은 드레스(공주 드레스). 넥라인 가운데는 다른 옷과 **같은 것**을 쓰고,
  // 어깨만 자기 것을 붙인다 — neckMid 참고
  function sleevedDress(c, c2, hemY, longSleeve, tune, neck) {
    const B = BODY, pad = CLOTH_PAD;
    // 어깨는 몸통보다 넓게. **몸통과 같이 좁아진다** — 안 그러면 팔을 가늘게 했을 때
    // 드레스의 어깨만 팔 밖으로 튀어나온다 (shoulderSquash 참고)
    const sf = clothShoulderK(tune);                      // 몸통 배율까지 따라간다
    const L = sqx(B.torsoL - pad, sf), R = sqx(B.torsoR + pad, sf);
    // ⚠️ **퍼짐만 다리 배율을 탄다.** 예전에는 종 전체를 `tuneMax(몸통·허벅지·종아리)`
    // 로 늘려서 허벅지를 키우면 어깨까지 같이 커졌다
    const kLeg = tuneMax(tune, ['thigh', 'calf']);
    const flare = 21 * kLeg;                              // 밑단이 퍼지는 정도
    const hemL = L - flare, hemR = R + flare;
    const cut = neck && neckCut(neck, tune).w ? neckMid(neck, tune) : null;
    const top = cut
      ? `C${L},${B.shoulderY} ${cut.EL - 14},${cut.K} ${cut.EL},${cut.K}
         ${cut.d}
         C${cut.ER + 14},${cut.K} ${R},${B.shoulderY} ${R},${B.shoulderY + 11}`
      : `C${L},${B.shoulderY} ${L + 16},${CLOTH_TOP_Y} 100,${CLOTH_TOP_Y}
         C${R - 16},${CLOTH_TOP_Y} ${R},${B.shoulderY} ${R},${B.shoulderY + 11}`;
    // ─── 소매는 **종 위에** 온다. 다만 한 톤 어둡게 ───────────
    //
    // 종보다 뒤에 두면 팔이 통째로 사라진다. 이 종은 어깨에서 바닥까지 내려오면서
    // 팔보다 3~14px 밖으로 퍼져 있어서, 뒤에 있는 팔은 **어느 높이에서도 안 비친다** —
    // 소매도 손도 없이 **삼각뿔 하나**가 됐다 (「공주 드레스 입으면 손 사라짐」).
    //
    // 그렇다고 드레스와 **같은 색으로** 앞에 얹으면 팔은 여전히 안 보이고 손만 보여,
    // 초록 종 한가운데에 **살색 덩어리 두 개가 동동 뜬 것**처럼 된다.
    // 그래서 앞에 얹되 **소매를 그림자 색으로** 칠한다 — 팔이 실루엣으로 읽히고
    // 그 끝에 손이 달린다. 허리선·밑단이 이미 쓰는 색이라 결이 어긋나지 않는다.
    // 인트로의 공주도 팔을 종 앞에 두고 손을 내놓는다(`princessArms`) — 거기서는
    // 팔이 종 **밖으로** 나가 있어 같은 색으로도 읽혔다.
    // ⚠️ 소매를 짧게 만든 변종을 붙인다면 **그 아래의 맨팔도 종 앞으로 꺼내야 한다** —
    // 지금은 팔이 종 뒤에 있어서, 소매만 앞에 두면 소매 끝에서 팔이 사라진다
    // (지금 이 함수를 부르는 곳은 공주 드레스 하나뿐이고 소매는 늘 길다)
    //
    // **소매는 드레스와 같은 색이고, 윤곽선으로만 구분한다.** 한 톤 어둡게 칠해 봤더니
    // 팔이 읽히기는 하는데 **소매만 다른 옷** 처럼 보였다 — 종 위에 팔이 얹힌 그림에는
    // 선 한 줄이 맞는다 (`armShape` 의 `outline` 참고)
    return `<g data-part="dress">
      <!-- 몸통 → 밑단까지 퍼지는 치마 (어깨 폭은 몸통 기준 + 여유) -->
      <path data-part="cloth" d="M${L},${B.shoulderY + 11}
        ${top}
        C${R + 6},${B.waistY - 18} ${hemR - 5},${hemY - 62} ${hemR},${hemY + 5}
        C${R - 18},${hemY + 15} ${L + 18},${hemY + 15} ${hemL},${hemY + 5}
        C${hemL + 5},${hemY - 62} ${L - 6},${B.waistY - 18} ${L},${B.shoulderY + 11} Z" fill="${c}"/>
      <!-- 허리 라인 -->
      <path d="M${L + 8},${B.waistY} L${R - 8},${B.waistY}" stroke="${c2}" stroke-width="4.5" stroke-linecap="round"/>
      <!-- 밑단 -->
      <path d="M${hemL + 3},${hemY - 8} C${L + 12},${hemY + 2} ${R - 12},${hemY + 2} ${hemR - 3},${hemY - 8}"
            stroke="${c2}" stroke-width="3.5" fill="none" stroke-linecap="round"/>
      ${cut ? '' : `<!-- 목선 — 안 파는 경우에만. 파냈으면 그 모서리가 곧 넥라인이다 -->
      <path d="M88,${B.shoulderY} Q100,${B.shoulderY + 9} 112,${B.shoulderY}"
            stroke="${c2}" stroke-width="2.6" fill="none" stroke-linecap="round"/>`}
      ${sleeves(c, longSleeve ? PRINCESS_LEN : 0.42, tune, null, c2)}
    </g>`;
  }

  function renderDress(it, tune) {
    if (isNone(it)) return '';
    const c = it.color, c2 = shade(c);

    // 튜토리얼 인트로의 공주 드레스 — 어깨에서 발목까지 내려오는 종 모양 + 소매
    // (인트로 princessFront 의 실루엣을 아바타 좌표계로 옮긴 것)
    if (it.kind === 'princess') {
      return sleevedDress(c, c2, BODY.ankleY, true, tune, it.neck);
    }

    // 기장·퍼짐·넥라인·소매는 전부 아이템 필드다 (없으면 예전 값 그대로)
    const B = BODY;
    const hemY = Number(it.hemY) || (it.kind === 'gown' ? 320 : 270);
    // ⚠️ **퍼짐만 다리 배율을 탄다.** 예전에는 옷 전체를 `tuneMax(몸통·허벅지·종아리)`
    // 로 통째로 늘려서, **허벅지를 키우면 어깨까지 두 배**가 됐다 (실제로 그랬다).
    // 어깨·허리·엉덩이는 이미 제 몸 부위를 따라간 좌표다 — 늘릴 것은 치마의 퍼짐뿐이다
    const kLeg = tuneMax(tune, hemY > KNEE_LINE ? ['thigh', 'calf'] : ['thigh']);
    const flare = (Number(it.flare) || (it.kind === 'gown' ? 40 : 46)) * kLeg;
    // 허리는 몸의 허리를 따라간다 (예전에는 78~122 로 박혀 있어 허리 살이 밖으로 나왔다)
    const ww = clothWaistHalf(tune), hhw = clothHipHalf(tune);
    const WY = B.waistY, HYd = hipApexY(tune);   // 몸의 엉덩이 봉우리를 그대로 따라간다
    const wL = +(100 - ww).toFixed(2), wR = +(100 + ww).toFixed(2);
    const hL = +(100 - hhw).toFixed(2), hR = +(100 + hhw).toFixed(2);
    const [eR, eY] = shoulderEndR(clothShoulderK(tune)), eL = 200 - eR;
    const sc = clothSideC(eR, wR);
    return `
      ${garmentSleeves(it, tune)}
      ${it.puff ? puffShoulder(c, tune) : ''}
      <path data-part="cloth" d="${clothTopEdge(it.neck, tune)}
        C${eR},${WY - 34} ${sc},${WY - 18} ${wR},${WY + 2}
        C${hR},${WY + 8} ${hR},${HYd - 6} ${hR},${HYd}
        C${hR},${HYd + 24} ${100 + flare},${hemY - 40} ${100 + flare + 8},${hemY}
        C${wR},${hemY + 14} ${wL},${hemY + 14} ${100 - flare - 8},${hemY}
        C${100 - flare},${hemY - 40} ${hL},${HYd + 24} ${hL},${HYd}
        C${hL},${HYd - 6} ${hL},${WY + 8} ${wL},${WY + 2}
        C${200 - sc},${WY - 18} ${eL},${WY - 34} ${eL},${eY} Z" fill="${c}"/>
      <path d="M${wL},${WY} L${wR},${WY}" stroke="${c2}" stroke-width="4" stroke-linecap="round"/>
      ${neckLine(it.neck, c, c2, 110)}`;
  }

  // ═══════════════════════════════════════════════════════════════
  //  악세사리 (서클렛 / 귀걸이 / 목걸이)
  // ═══════════════════════════════════════════════════════════════
  // ─── 악세사리 = 형태 축 × 장식 축 ────────────────────────────
  // 벌마다 그림을 하나씩 그리지 않는다. 축마다 조각 함수를 하나씩 두고 겹쳐 그린다
  // (옷의 소매·넥라인과 같은 방식). 벌을 늘려도 여기 함수는 그대로다.

  // 장식 조각 — 서클렛·귀걸이·목걸이가 같이 쓴다. cx,cy 에 크기 r 로 얹는다
  function charmShape(kind, cx, cy, r, c) {
    const c2 = shade(c, 30);
    switch (kind) {
      case 'gem':
      case 'drop':
        return `<path d="M${cx},${cy - r * 1.2} C${cx + r},${cy - r * 0.2} ${cx + r * 0.8},${cy + r} ${cx},${cy + r}
          C${cx - r * 0.8},${cy + r} ${cx - r},${cy - r * 0.2} ${cx},${cy - r * 1.2} Z" fill="${c}"/>
          <ellipse cx="${cx - r * 0.3}" cy="${cy}" rx="${r * 0.25}" ry="${r * 0.4}" fill="#fff" opacity="0.55"/>`;
      case 'star':
        return `<path d="${starPath(cx, cy, r * 1.15)}" fill="${c}"/>`;
      case 'heart':
        return `<path d="M${cx},${cy + r} C${cx - r * 1.4},${cy - r * 0.2} ${cx - r * 0.6},${cy - r * 1.2} ${cx},${cy - r * 0.35}
          C${cx + r * 0.6},${cy - r * 1.2} ${cx + r * 1.4},${cy - r * 0.2} ${cx},${cy + r} Z" fill="${c}"/>`;
      case 'flower': {
        const p = [0, 72, 144, 216, 288].map(a =>
          `<circle cx="${(cx + Math.cos(a * Math.PI / 180) * r * 0.8).toFixed(1)}"
             cy="${(cy + Math.sin(a * Math.PI / 180) * r * 0.8).toFixed(1)}" r="${(r * 0.55).toFixed(1)}" fill="${c}"/>`).join('');
        return p + `<circle cx="${cx}" cy="${cy}" r="${(r * 0.4).toFixed(1)}" fill="#fff3b0"/>`;
      }
      case 'ribbon':
        return `<path d="M${cx - r * 1.5},${cy - r * 0.7} L${cx},${cy} L${cx - r * 1.5},${cy + r * 0.7} Z" fill="${c}"/>
          <path d="M${cx + r * 1.5},${cy - r * 0.7} L${cx},${cy} L${cx + r * 1.5},${cy + r * 0.7} Z" fill="${c}"/>
          <circle cx="${cx}" cy="${cy}" r="${(r * 0.42).toFixed(1)}" fill="${c2}"/>`;
      case 'none':
        return '';
      default:   // circle — 동그란 알
        return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c}"/>
          <circle cx="${(cx - r * 0.3).toFixed(1)}" cy="${(cy - r * 0.3).toFixed(1)}" r="${(r * 0.3).toFixed(1)}" fill="#fff" opacity="0.55"/>`;
    }
  }

  // 서클렛 = 머리띠(band) × 가운데 장식(orn)
  function renderCirclet(it) {
    if (isNone(it)) return '';
    const c = it.color || '#ffd76a', c2 = shade(c, 34);
    const band = it.band || (it.kind === 'tiara' ? 'crown' : 'arch');
    const orn = it.orn || (it.kind === 'flower' ? 'flower' : it.kind === 'tiara' ? 'gem' : 'ribbon');
    let s = '';
    if (band === 'crown') {            // 왕관 톱니
      s = `<path d="M72,55 L82,43 L91,52 L100,38 L109,52 L118,43 L128,55 Z"
        fill="${c}" stroke="${c2}" stroke-width="1.5" stroke-linejoin="round"/>`;
    } else if (band === 'wide') {      // 넓은 밴드
      s = `<path d="M68,56 Q100,40 132,56 L132,62 Q100,47 68,62 Z" fill="${c}"/>`;
    } else if (band === 'chain') {     // 체인 — 알을 늘어놓은 띠
      for (let i = 0; i <= 10; i++) {
        const t = i / 10, x = 70 + t * 60, y = 55 - Math.sin(t * Math.PI) * 12;
        s += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="2.1" fill="${c}"/>`;
      }
    } else {                           // 가는 아치
      s = `<path d="M69,54 Q100,42 131,54" stroke="${c}" stroke-width="3.5" fill="none" stroke-linecap="round"/>`;
    }
    // 장식은 띠 한가운데 위에. 왕관은 톱니 꼭대기가 이미 높아 조금 더 위로 얹는다
    return s + charmShape(orn, 100, band === 'crown' ? 45 : 46, 4.6, c);
  }

  // 귀걸이 = 거는 형태(form) × 매다는 장식(charm). 양쪽 귀(x 66 / 134)에 같은 것을 단다
  function renderEarring(it) {
    if (isNone(it)) return '';
    const c = it.color || '#ffd76a';
    const form = it.form || (it.kind === 'hoop' ? 'hoop' : it.kind === 'star' ? 'stud' : 'drop');
    const charm = it.charm || (it.kind === 'hoop' ? 'circle' : it.kind === 'star' ? 'star' : 'drop');
    const one = (x) => {
      const pin = `<circle cx="${x}" cy="83" r="1.8" fill="${c}"/>`;   // 귓불 고정 알
      switch (form) {
        case 'stud':                                   // 스터드 — 귓불에 딱 붙는다
          return charmShape(charm, x, 85, 3.6, c);
        case 'hoop':                                   // 링 — 고리 아래에 장식
          return pin + `<circle cx="${x}" cy="89" r="5" fill="none" stroke="${c}" stroke-width="2.4"/>`
            + charmShape(charm, x, 94.5, 2.6, c);
        case 'chain':                                  // 체인 — 가늘고 길게 늘어뜨린다
          return pin + `<path d="M${x},85 L${x},96" stroke="${c}" stroke-width="1.4"/>`
            + charmShape(charm, x, 99, 3.4, c);
        case 'cluster':                                // 뭉치 — 작은 장식 셋
          return pin + charmShape(charm, x - 3, 90, 2.4, c) + charmShape(charm, x + 3, 90, 2.4, c)
            + charmShape(charm, x, 95, 2.8, c);
        case 'cuff':                                   // 이어커프 — 귀 위쪽을 감싼다
          return `<path d="M${x - 1},80 Q${x + (x < 100 ? -5 : 5)},85 ${x - 1},90"
              stroke="${c}" stroke-width="2.6" fill="none" stroke-linecap="round"/>`
            + charmShape(charm, x, 85, 2.4, c);
        default:                                       // 드롭 — 짧게 늘어뜨린다
          return pin + charmShape(charm, x, 90, 4, c);
      }
    };
    return one(66) + one(134);
  }

  // 목걸이 = 줄(chain) × 펜던트(pend)
  function renderNecklace(it) {
    if (isNone(it)) return '';
    const c = it.color || '#ffd76a', c2 = shade(c, 18);
    const chain = it.chain || (it.kind === 'choker' ? 'choker' : it.kind === 'pearl' ? 'pearl' : 'short');
    const pend = it.pend || (it.kind === 'pendant' ? 'circle' : 'none');
    // 줄마다 목 아래로 내려오는 깊이가 다르다. 펜던트는 그 끝에 매달린다
    const DEPTH = { choker: 8, short: 16, long: 28, pearl: 14, double: 22, ribbon: 12 };
    const dy = DEPTH[chain] || 16;
    const arc = (d, w, col) => `<path d="M85,113 Q100,${113 + d} 115,113" stroke="${col}" stroke-width="${w}" fill="none" stroke-linecap="round"/>`;
    let s = '';
    if (chain === 'pearl') {                     // 알줄 — 구슬을 늘어놓는다
      for (let i = 0; i <= 8; i++) {
        const t = i / 8;
        s += `<circle cx="${(83 + t * 34).toFixed(1)}" cy="${(116 + Math.sin(t * Math.PI) * 11).toFixed(1)}"
          r="2.4" fill="${c}" stroke="${c2}" stroke-width="0.5"/>`;
      }
    } else if (chain === 'double') {             // 이중 줄
      s = arc(14, 2, c) + arc(26, 2, c);
    } else if (chain === 'ribbon') {             // 리본 끈 — 굵은 띠에 리본 매듭
      s = arc(11, 4.5, c) + charmShape('ribbon', 100, 120, 3.4, c);
    } else if (chain === 'choker') {
      s = arc(8, 4, c);
    } else {
      s = arc(dy - 4, 2, c);
    }
    return s + charmShape(pend, 100, 113 + dy + 3, 4.6, c);
  }

  // ═══════════════════════════════════════════════════════════════
  //  문신 (얼굴/볼 — 헤어·옷에 가리지 않는 위치)
  // ═══════════════════════════════════════════════════════════════
  function renderTattoo(it) {
    if (isNone(it)) return '';
    const c = it.color || '#c98bd6';
    switch (it.kind) {
      case 'star':
        return `<path d="${starPath(120, 90, 3.4)}" fill="${c}"/>`;
      case 'tear':
        return `<path d="M80,84 L77.6,90 L82.4,90 Z" fill="${c}"/><circle cx="80" cy="90" r="2.5" fill="${c}"/>`;
      case 'heart':
        return `<path d="M120,88 q-2.7,-2.7 -4.3,0 q-1.5,2.6 4.3,6.2 q5.8,-3.6 4.3,-6.2 q-1.6,-2.7 -4.3,0 Z" fill="${c}"/>`;
      case 'rune':
        return `<path d="M114,85 L124,85 M119,85 L119,94 M119,94 L123,97" stroke="${c}" stroke-width="1.7" fill="none" stroke-linecap="round"/>`;
      default:
        return `<circle cx="120" cy="90" r="2.6" fill="${c}"/>`;
    }
  }

  // ═══════════════════════════════════════════════════════════════
  //  조립
  // ═══════════════════════════════════════════════════════════════
  // body: 체형 0(날씬) ~ 1(튜토리얼 인트로의 통통한 공주). 기본 0.
  // 몸통/팔다리와 '옷'을 같은 그룹으로 함께 늘려서 옷이 몸에서 어긋나지 않게 한다.
  // SVG 의 id 는 **문서 전체에서 공유된다.** 아바타를 두 개 이상 한 화면에 그리면
  // 뒤에 온 쪽이 앞 쪽의 그라디언트를 써 버린다 (roomScene 과 같은 이유). 그래서
  // 부를 때마다 꼬리표를 붙인다. build 와 crouchBack 이 같이 쓴다 —
  // **두 함수보다 위에 있어야 한다** (let 은 끌어올려지지 않는다)
  let avatarUid = 0;

  // ─── 웅크려 먹는 뒷모습 — 「혼자 먹은 밤」 컷씬 ─────────────
  //
  // **지금 그 캐릭터의 뒷모습이다.** 머리 모양·머리색·옷 색·체형을 다 따라간다 —
  // 다른 그림을 하나 더 그리면 「내 공주」가 아니라 삽화가 되어 버린다.
  // 뒷머리(hairBack)는 원래 뒤통수를 그리는 함수라 **그대로** 쓴다.
  //
  // 얼굴은 안 그린다. 그게 이 장면의 전부다 — 등을 돌리고 있다.
  function crouchBack(outfit, body, foodEmoji) {
    const w = Math.max(0, Math.min(1, Number(body) || 0));   // 1 = 통통
    const o = outfit || {};
    const col = (o.colors || {});
    const it = (slot) => getItem(slot, o[slot]);
    // 옷 색 — 원피스가 있으면 그것, 없으면 상의. 아무것도 없으면 살색(속옷 아님, 맨몸)
    const dress = it('dress'), top = it('top');
    const cloth = (!isNone(dress) && (col.dress || dress.color))
      || (!isNone(top) && (col.top || top.color)) || SKIN;
    const clothSh = shade(cloth, 16);
    const hairItem = it('hair');
    const hairC = col.hair || hairItem.color || HAIR_DEF;
    const backKind = hairItem.back || (hairItem.kind === 'none' ? 'long' : hairItem.kind);
    // 무릎 색 — **다리를 덮는 옷이면 옷 색이다.** 예전에는 늘 살색이라, 발목까지 오는
    // 공주 드레스를 입고도 무릎만 맨살 덩어리로 옆에 삐져나와 있었다.
    // 서 있을 때 무릎은 y≈278 근처다 (엉덩이 아래 214 ~ 발목 331 의 가운데).
    // 그보다 아래로 내려오는 밑단이면 무릎을 덮는다. `hemY` 가 없는 것(공주 드레스)은
    // 바닥까지 오는 옷이라 덮는 쪽으로 친다.
    // (허리를 올리면서 다리가 올라온 만큼 285 → 278 로 같이 옮겼다)
    const KNEE_Y = 278;
    const legSlot = !isNone(dress) ? 'dress' : 'bottom';
    const legWear = legSlot === 'dress' ? dress : it('bottom');
    const legHem = isNone(legWear) ? null : (Number(legWear.hemY) || 999);
    const legC = isNone(legWear) ? null : (col[legSlot] || legWear.color);
    const kneeCovered = legHem !== null && legHem >= KNEE_Y && !!legC;
    const kneeC = kneeCovered ? legC : SKIN;
    const kneeSh = shade(kneeC, kneeCovered ? 16 : 10);
    // 신발 — **모양까지 따라간다.** 색만 바꾸면 유리구두를 신고도 맨발과 같은 모양이라,
    // 「신발이 안 그려진다」로 읽힌다. 뒤에서 보이는 것은 **뒤꿈치**이므로
    // 목(rise)과 마감(finish) 두 축을 그대로 쓴다 (renderShoes 와 같은 필드)
    const shoes = it('shoes');
    const bare = isNone(shoes);
    const shoeC = (!bare && (col.shoes || shoes.color)) || SKIN;
    const shoeSh = shade(shoeC, 22);
    const rise = bare ? 0 : (Number(shoes.rise) || 0);
    const fin = bare ? 'plain' : (shoes.finish || 'plain');
    // 뒤꿈치 한 짝. 앉아 있으므로 발목이 위로 조금 올라온다
    const heel = (cx) => {
      let g = '';
      if (rise > 0) g += `<rect x="${cx - 11}" y="${210 - rise}" width="22" height="${rise + 6}" rx="6" fill="${shoeC}"/>`;
      g += `<ellipse cx="${cx}" cy="214" rx="15" ry="9" fill="${shoeC}"/>`;
      if (fin === 'sole')       g += `<ellipse cx="${cx}" cy="218" rx="15" ry="3.6" fill="${shoeSh}"/>`;
      else if (fin === 'strap') g += `<path d="M${cx - 11},209 L${cx + 11},209" stroke="${shoeSh}" stroke-width="2.4" stroke-linecap="round"/>`;
      else if (fin === 'ribbon') g += `<path d="M${cx - 8},208 Q${cx},213 ${cx + 8},208" stroke="${shoeSh}" stroke-width="2.2" fill="none" stroke-linecap="round"/>`
        + `<circle cx="${cx}" cy="208" r="2.4" fill="${shoeSh}"/>`;
      else if (fin === 'gloss') g += `<ellipse cx="${cx - 4}" cy="211" rx="6" ry="2.8" fill="#fff" opacity="0.75"/>`;
      if (rise > 0) g += `<path d="M${cx - 11},${210 - rise + 6} L${cx + 11},${210 - rise + 6}" stroke="${shoeSh}" stroke-width="2.2" stroke-linecap="round"/>`;
      // 맨발이면 뒤꿈치에 그늘을 하나 — 안 그러면 살색 덩어리가 두 개 붙은 것으로 보인다
      if (bare) g += `<ellipse cx="${cx}" cy="217" rx="11" ry="4" fill="${SKIN_SH}"/>`;
      return g;
    };

    // 통통할수록 등이 넓어진다. 가로만 늘린다 — 앉은 키는 그대로다
    const k = 1 + 0.22 * w;
    const kS = k.toFixed(3);
    // 웅크린 등의 실루엣. 색을 두 가지로 나눠 칠하려면 같은 모양을 clip 으로도 써야 해서
    // 한 곳에만 적어 둔다 — 두 벌로 두면 한쪽만 고쳐 놓고 못 알아챈다
    const BACK_D = 'M70,116 C60,144 54,176 54,200 C72,214 128,214 146,200'
      + ' C146,176 140,144 130,116 C118,106 82,106 70,116 Z';
    const SKIRT_Y = 166;                       // 허리 — 여기부터 아래가 치마다
    const twoTone = legSlot === 'bottom' && kneeCovered && legC !== cloth;
    // SVG 의 id 는 문서 전체에서 공유된다 — 옷장 미리보기처럼 여럿을 한 화면에 그리면
    // 뒤에 온 것이 앞의 clip 을 덮어쓴다 (roomScene·build 와 같은 이유)
    const uid = 'c' + (++avatarUid);

    return `<svg class="cb-svg" viewBox="0 0 200 250" xmlns="http://www.w3.org/2000/svg"
      role="img" aria-label="">
      ${twoTone ? `<defs><clipPath id="cbb_${uid}"><path d="${BACK_D}"/></clipPath></defs>` : ''}
      <!-- 그림자도 같이 눌린다. 몸만 움직이면 바닥에서 뜬 것처럼 보인다 -->
      <ellipse class="cb-shadow" cx="100" cy="226"
        rx="${(66 * (1 + 0.15 * w)).toFixed(1)}" ry="10" fill="rgba(20,10,25,0.28)"/>

      <g transform="translate(100,0) scale(${kS},1) translate(-100,0)">
        <!-- 씹는 박자에 몸 전체가 아주 살짝 눌렸다 편다 (스쿼시 & 스트레치).
             **바깥 그룹의 체형 배율과 겹치면 안 되므로** 한 겹 안에서 따로 움직인다 —
             CSS transform 은 SVG transform 속성을 덮어쓴다 -->
        <g class="cb-body">
          <!-- 발 — 등 뒤에서는 발끝이 아니라 **뒤꿈치**가 보인다 -->
          ${heel(76)}${heel(124)}

          <!-- 무릎 — 쭈그리면 좌우로 벌어져 등 옆으로 삐져나온다.
               **살짝만 내민다.** 예전에는 엉덩이 높이에서 발보다 넓게 튀어나와,
               다리라기보다 옆에 놓인 살색 덩어리로 보였다.
               색은 입은 옷을 따라간다 — 긴 치마 아래로 맨무릎이 나오면 안 된다 -->
          <ellipse data-part="knee" cx="60" cy="193" rx="15" ry="16" fill="${kneeC}"
            stroke="${kneeSh}" stroke-width="1.6"/>
          <ellipse data-part="knee" cx="140" cy="193" rx="15" ry="16" fill="${kneeC}"
            stroke="${kneeSh}" stroke-width="1.6"/>

          <!-- 등 — 어깨에서 엉덩이로 퍼지는 웅크린 덩어리 -->
          <path d="${BACK_D}" fill="${cloth}"/>
          <!-- 상의와 치마를 따로 입었으면 **아랫도리는 치마 색**이다.
               한 색으로 칠하면 몸통은 상의 색인데 무릎만 치마 색이 되어,
               민트 치마에 분홍 몸통 + 민트 무릎이라는 이상한 그림이 나온다.
               실루엣을 clip 으로 잘라 쓰므로 옷 모양을 다시 그릴 필요가 없다 -->
          ${twoTone ? `<rect clip-path="url(#cbb_${uid})" x="40" y="${SKIRT_Y}" width="120" height="80" fill="${legC}"/>` : ''}
          <!-- 등 한가운데 접힌 자국 하나. 없으면 그냥 색 덩어리로 보인다 -->
          <path d="M100,126 C97,152 97,178 100,198" stroke="${clothSh}" stroke-width="2.4"
            fill="none" stroke-linecap="round" opacity="0.7"/>

          <!-- 왼팔 — 앞으로 안고 있어서 팔꿈치만 등 옆으로 삐져나온다.
               등과 같은 색이라 옆선을 그늘로 잡아 줘야 팔로 읽힌다.
               **회전축은 어깨**다. 팔꿈치를 축으로 돌리면 어깨가 빠져 보인다.
               (오른팔은 음식을 들고 있어서 아래 .cb-bite 가 따로 그린다) -->
          <g class="cb-arm cb-arm-l">
            <ellipse cx="56" cy="154" rx="12" ry="20" fill="${cloth}"
              stroke="${clothSh}" stroke-width="1.6" transform="rotate(-12 56 154)"/>
          </g>

          <!-- 목덜미 (머리에 거의 가린다) -->
          <rect x="88" y="100" width="24" height="20" rx="9" fill="${SKIN_SH}"/>
        </g>
      </g>

      <!-- 오른팔 — 음식을 들고 입으로 가져가는 팔. **머리보다 먼저 그린다.**
           뒤에서 보고 있으니 손은 얼굴 쪽(저쪽 편)에 있고, 뒤통수가 팔을 가려야 맞다.
           머리 위에 그렸더니 팔이 머리를 가로질러 앞으로 넘어와 보였다.
           그러면서도 손과 음식은 **머리 옆으로 비켜나** 있어서 가려지지 않는다 —
           엄밀히는 얼굴 뒤에 숨어야 하지만, 그러면 무엇을 하는 장면인지 안 읽힌다.

           **밑동은 어깨다.** 예전에는 y=168(엉덩이 높이)에서 시작해서, 팔이 허리 뒤에서
           돋아난 것처럼 보였다 — 팔꿈치 덩어리보다도 아래였다.
           어깨(위) → 팔꿈치(아래 바깥) → 손목(위) 의 꺾인 선 하나로 그린다.

           가로는 k 를 따라가되 손과 음식은 그 자리에 놓기만 한다 —
           이모지가 가로로 늘어나면 안 되기 때문이다 -->
      ${(() => {
        const sx = (100 + 33 * k).toFixed(1);   // 어깨 — 등 실루엣의 오른쪽 끝
        const ex = (100 + 47 * k).toFixed(1);   // 팔꿈치 — 등 옆으로 조금 나온다
        const wx = (100 + 43 * k).toFixed(1);   // 손목
        const arm = `M${sx},128 L${ex},157 L${wx},126`;
        const hx = Number(wx), fx = hx + 9;
        return `<g class="cb-bite">
        <!-- 그늘을 **한 번 더 굵게 깔아** 테두리를 만든다. 같은 굵기로 덧칠하면
             전체가 어두워질 뿐이고, 몸통과 한 색으로 붙어 버린다 -->
        <path d="${arm}" stroke="${clothSh}" stroke-width="17.6" fill="none"
          stroke-linecap="round" stroke-linejoin="round"/>
        <path d="${arm}" stroke="${cloth}" stroke-width="15" fill="none"
          stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="${hx}" cy="120" r="9.5" fill="${SKIN}"/>
        ${foodEmoji ? `<text class="cb-food" x="${fx}" y="114" font-size="28" text-anchor="middle">${foodEmoji}</text>` : ''}
      </g>`;
      })()}

      <!-- 머리 — 고개를 숙이고 우적우적. **뒷머리 함수를 그대로 쓴다**.
           우적우적은 CSS 로 흔든다 (.cb-head) — 무한 반복이라 검증기가 건드리지 않는다 -->
      <g transform="translate(0,26)">
        <g class="cb-head">
          <g transform="rotate(-3 100 105)">
            <ellipse cx="100" cy="70" rx="33" ry="35" fill="${SKIN}"/>
            ${hairBack(backKind, hairC)}
          </g>
        </g>
      </g>

      <!-- 「우적」 — 씹을 때마다 머리 옆에서 톡 터지는 효과선. 애니메이션의 박자를 눈으로
           보여 주는 것이라, 이게 없으면 고개만 까딱이는 것으로 보인다.
           오른쪽은 **든 손을 피해 위로** 뺀다 -->
      <g class="cb-spark cb-spark-l" fill="none" stroke="rgba(120,90,70,0.6)" stroke-width="2.4"
        stroke-linecap="round">
        <path d="M56,92 q-7,-4 -12,-2"/><path d="M58,104 q-8,1 -12,5"/>
      </g>
      <g class="cb-spark cb-spark-r" fill="none" stroke="rgba(120,90,70,0.6)" stroke-width="2.4"
        stroke-linecap="round">
        <path d="M150,74 q8,-5 13,-3"/><path d="M156,86 q9,-1 13,3"/>
      </g>

      <!-- 바닥에 남은 것 — 접시가 「몇 번째인지」를 말해 준다 -->
      ${foodEmoji ? `<text x="34" y="216" font-size="30" text-anchor="middle" opacity="0.9">${foodEmoji}</text>` : ''}
      <!-- 부스러기 — 씹을 때마다 톡톡 튄다. 시작 시각을 어긋나게 줘야 같이 안 튄다 -->
      <circle class="cb-crumb cb-crumb1" cx="62" cy="222" r="2.4" fill="rgba(90,60,40,0.55)"/>
      <circle class="cb-crumb cb-crumb2" cx="72" cy="228" r="1.8" fill="rgba(90,60,40,0.45)"/>
      <circle class="cb-crumb cb-crumb3" cx="150" cy="224" r="2" fill="rgba(90,60,40,0.5)"/>
    </svg>`;
  }

  function build(outfit, body, tune) {
    const uid = 'a' + (++avatarUid);
    outfit = outfit || {};
    const w = Math.max(0, Math.min(1, Number(body) || 0));

    // ── 등신 비율 ──────────────────────────────────────────────
    // 통통할 때 3등신, 날씬할 때 4등신. 머리가 큰 쪽이 귀엽다.
    // 머리는 목을 축으로 줄이고, 그만큼 몸을 세로로 늘려 전체 키는 유지한다.
    const head = HEAD_H * lerpN(HEAD_K_SLIM, HEAD_K_FAT, w);   // 실제 머리 높이(px)
    const bodyKy = 1 + (HEAD_H - head) / BODY_SPAN;            // 머리가 줄어든 만큼 몸을 늘림
    const dy = BODY_SPAN * (1 - bodyKy);                       // 어깨가 올라간 만큼 머리도 따라 올림
    const headK = head / HEAD_H;

    // 얼굴 배율은 **몸보다 먼저** 알아야 한다 — 머리가 크면 몸을 줄이기 때문이다
    const kFace = tuneOf(tune, 'face');
    const kBody = bodyShrink(kFace);
    // 몸이 바닥을 축으로 줄어든 만큼 **목이 내려온다** — 머리도 그만큼 따라 내려간다.
    // (NECK_Y − FLOOR_Y)가 음수라 kBody<1 이면 양수, 즉 «아래»로 간다
    //
    // ⚠️ **얼굴을 키우면 목이 길어진다** — 머리는 목 이음점(`NECK_Y` 112)을 축으로
    // 커지는데 턱은 그보다 «위»(머리 안에서 105)라, 키울수록 턱이 이음점 위로
    // 올라가 그만큼 목이 드러난다. 재어 보면 얼굴 100% 12.7px → 150% **17.1px** 이다.
    // 머리는 커지는데 목까지 길어지니 어른 몸에 큰 머리를 얹은 꼴이 됐다.
    // 그래서 얼굴이 커진 만큼 머리를 **더 내려 앉힌다** — 턱이 어깨 쪽으로 내려와
    // 150% 에서 목이 8px 안팎이 된다 (머리가 클수록 목이 짧은 편이 귀엽다).
    // ⚠️ `chinY` 도 이 값을 지나므로 **목 자체의 길이도 같이 줄어든다** —
    // 머리만 내리면 목이 어깨 안으로 파고들어 이음매가 어긋난다.
    //
    // ⚠️ **바닥을 둔다.** 통통한 몸은 등신 비율(`bodyKy`) 때문에 목이 이미 짧다
    // (전부 최대 · 통통에서 11.1px). 거기에 9 를 그대로 빼면 **2.1px** 이 되어
    // 턱이 어깨에 얹힌다 — 그래서 「내리려는 만큼」과 「내릴 수 있는 만큼」 중 작은 쪽만 쓴다.
    const NECK_SINK = 9, NECK_MIN = 6;
    const dropBody = (NECK_Y - FLOOR_Y) * bodyKy * (kBody - 1);

    // 몸: 가로로 통통하게 + 세로로 늘려 다리를 길게 (바닥을 축으로)
    const bodyT = `translate(100,${FLOOR_Y}) scale(${(bodyScaleX(w) * kBody).toFixed(3)},${(bodyKy * kBody).toFixed(3)}) translate(-100,${-FLOOR_Y})`;
    // 머리: 목을 축으로 크기 조절 (통통하면 가로로 살짝 더 둥글게)
    // 날씬할수록 머리를 위로 올려 목을 뺀다 (NECK_LIFT 참고)
    //
    // ⚠️ **몸통 슬라이더로 가늘게 해도 목이 길어져야 한다.** 예전에는 몸무게(w)만
    // 봤는데, 몸통을 줄이면 어깨 곡선(`shoulderC`)이 **가로로 눌려** 승모근이 목 바로
    // 옆에서 솟는다 — 목 길이는 그대로인데 목이 어깨에 파묻힌 것처럼 보였다
    // (몸통 50% 에서 특히). 살이 빠지면 목이 드러나는 게 맞으므로 같은 방향으로 민다.
    // 몸무게 쪽보다 몫을 작게 준다 — 몸통은 굵기만 바꾸지 등신을 안 바꾸기 때문이다.
    const lift = NECK_LIFT * (1 - NECK_FAT * w)
      + NECK_LIFT_TORSO * (1 - Math.min(1, tuneOf(tune, 'torso')));
    // ⚠️ **`lift` 를 알고 나서야 잴 수 있다** — 목 길이 계산에 들어간다.
    // 머리를 1 내리면 보이는 목이 정확히 1 줄어든다 (둘 다 같은 좌표계로 환산된다)
    const kBodyY = bodyKy * kBody;
    const neckLenAt = c => (BODY.torsoTopY + 1 - FLOOR_Y) * kBodyY + FLOOR_Y - c;
    const chin0 = NECK_Y + (105 - NECK_Y) * headK * kFace + (dy - lift + dropBody);
    const headDrop = dropBody + Math.min(NECK_SINK * overOf(tune, 'face'),
      Math.max(0, neckLenAt(chin0) - NECK_MIN));
    const headT = `translate(0,${(dy - lift + headDrop).toFixed(2)}) translate(100,${NECK_Y}) `
      + `scale(${(headK * (1 + 0.06 * w)).toFixed(3)},${headK.toFixed(3)}) translate(-100,${-NECK_Y})`;
    // 체형이 0(날씬)이어도 등신 비율 때문에 변환이 필요하므로 항상 적용한다
    const B = s => (s ? `<g transform="${bodyT}">${s}</g>` : s);   // 몸통 계열
    // 머리 계열 — '얼굴' 배율은 여기서 **머리 전체**에 건다.
    // 예전에는 얼굴 타원(data-part="head")에만 걸려 있어서, 얼굴을 줄이면
    // 머리카락만 원래 크기로 남아 가발을 쓴 것처럼 됐다.
    // 머리카락·귀걸이·서클렛이 전부 H() 를 지나므로 여기 한 곳이면 다 따라온다.
    const H = s => (s ? `<g transform="${headT}">${wrapU(s, kFace, 100, NECK_Y)}</g>` : s);

    // ── 목 — **머리와 몸통은 변환이 서로 다르다.** 목은 몸통 그룹에 그려지므로
    // 머리 쪽 값을 몸통 좌표계로 환산해서 넘긴다. 안 그러면 체형·배율을 움직일 때마다
    // 턱과 목이 어긋난다 (NECK_LIFT 를 넣고 실제로 벌어졌다).
    //
    //   턱   머리 안에서 y=105. 머리 변환(kFace → headK, 그리고 dy-lift)을 지난 값
    //   폭   얼굴 반폭 33 이 머리 가로 배율을 지난 값 (몸통 가로 배율로 나눠 되돌린다)
    // ⚠️ **몸을 줄였으면(`kBody`) 그것까지 되돌려야 한다.** 몸통 좌표계로 옮기는
    // 나눗셈이 `bodyKy` 만 보고 있으면, 머리가 커져 몸이 줄어드는 구간에서
    // 목이 턱보다 짧아져 **턱과 어깨 사이에 배경이 비친다**
    const kx = (1 + 0.36 * w) * kBody, hx = headK * (1 + 0.06 * w) * kFace;
    const chinY = NECK_Y + (105 - NECK_Y) * headK * kFace + (dy - lift + headDrop);
    const neck = {
      // 몸통 좌표계로 되돌리고 2px 겹친다 — 딱 맞추면 경계에 배경이 1px 비친다
      top: FLOOR_Y + (chinY - FLOOR_Y) / (bodyKy * kBody) - 2,
      half: neckHalfOf(tune, hx / kx),
    };
    // 고른 색이 있으면 아이템의 원래 색을 덮어쓴다.
    // outfit.colors = { top: '#ffffff', ... } — 없는 칸은 아이템 색 그대로.
    // **원본을 고치지 않고 사본을 만든다** — D.WARDROBE 는 모두가 공유하는 카탈로그라
    // 여기서 물들이면 다른 화면(옷장 목록·미리보기)까지 같이 물든다.
    const pick = (slot, id) => {
      const it = getItem(slot, id);
      const c = outfit.colors && outfit.colors[slot];
      return (c && !isNone(it)) ? Object.assign({}, it, { color: c }) : it;
    };
    const dress = pick('dress', outfit.dress);
    const hasDress = !isNone(dress);
    const top = hasDress ? null : pick('top', outfit.top);
    const bottom = hasDress ? null : pick('bottom', outfit.bottom);

    const hairItem = getItem('hair', outfit.hair);
    // 머리색 — 다른 칸과 같은 규칙이다. 염색한 색이 있으면 그것, 없으면 헤어의 원래 색.
    // 마지막은 옛 세이브를 위한 길이다: '헤어컬러' 칸이 따로 있던 시절의 선택은
    // 마이그레이션이 염색으로 옮기지만, 그 전에 그려질 수도 있다
    const hairColor = (outfit.colors && outfit.colors.hair)
      || hairItem.color
      || getItem('hairColor', outfit.hairColor).color || HAIR_DEF;
    // 옛 세이브는 kind 하나로만 머리를 정했다 — back 이 없으면 kind 를 그대로 쓴다
    const hairBackKind = hairItem.back || (hairItem.kind === 'none' ? 'long' : hairItem.kind);
    const hairBangKind = hairItem.bang || hairItem.kind;
    const expItem = getItem('expression', outfit.expression);

    const layers = [
      H(hairBack(hairBackKind, hairColor)),
      B(legs(tune)),
      B(torsoArms(tune, uid, neck)),
      // 상의 → 하의 순. **상의가 뒤, 하의가 앞이다** — 옷을 넣어 입은 모양이 된다.
      // (반대로 두면 상의 밑단이 치마 허리춤 위에 얹혀 빼 입은 것처럼 보인다)
      //
      // 둘 다 몸통보다는 **앞**이어야 한다. 하의를 몸통 뒤로 보냈더니 몸통이 허리춤을
      // 덮어 버려, 상의 밑단과 치마 사이로 살이 띠처럼 드러났었다.
      // 상의 밑단(hipY-2)이 하의 허리(waistY)보다 아래라 그 사이에 틈이 생기지 않는다.
      B(hasDress ? '' : renderTop(top, tune)),
      B(hasDress ? '' : renderBottom(bottom, tune)),
      // 신발은 **드레스보다 아래** 다 — 위에 그리면 부츠 목이 드레스를 뚫고 나온다.
      // 하의(바지)보다는 위라서 부츠가 바짓단을 덮는다.
      B(renderShoes(pick('shoes', outfit.shoes), tune)),
      B(hasDress ? renderDress(dress, tune) : ''),
      // 허리 아래의 팔은 **치마보다 앞**이다 — 안 그러면 퍼진 치마가 팔뚝과 손을
      // 통째로 덮어, 소매 끝 언저리에 살색 조각만 남는다 (armsOverSkirt 참고)
      B(armsOverSkirt(tune, hasDress ? dress : top)),
      H(faceAndExpression(expItem)),
      H(hairFront(hairBangKind, hairColor)),
      H(faceFx(expItem)),
      B(renderGlove(pick('glove', outfit.glove), tune)),
      B(renderTattoo(getItem('tattoo', outfit.tattoo))),
      H(renderEarring(pick('earring', outfit.earring))),
      B(renderNecklace(pick('necklace', outfit.necklace))),
      H(renderCirclet(pick('circlet', outfit.circlet))),
    ];

    return `<svg class="avatar-svg" viewBox="${VB.x} ${VB.y} ${VB.w} ${VB.h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="내 아바타">
      <defs>${neckDefs(uid)}</defs>
      <ellipse cx="100" cy="342" rx="${(52 * (1 + 0.18 * w)).toFixed(1)}" ry="8" fill="rgba(120,90,110,0.14)"/>
      ${layers.join('')}
    </svg>`;
  }

  // ═══════════════════════════════════════════════════════════════
  //  마이 룸 배경 — 5단계로 커지는 방
  //
  //  구조는 **껍데기(shell) + 소품(prop)** 두 겹이다.
  //  · 껍데기 = 벽 · 창문 · 바닥. 단계에 따라 색만 바뀌고 형태는 그대로다
  //  · 소품   = 이름이 붙은 조각들(`ROOM_PROPS`). 단계마다 어떤 소품을 놓을지
  //             `ROOM_LEVELS` 가 id 목록으로 정한다
  //
  //  **추후 '마이 룸 꾸미기' 를 붙일 자리가 여기다.** 소품이 id 로 구분돼 있으므로
  //  플레이어가 고른 소품 id 목록을 `roomScene(level, extra)` 의 `extra` 로 넘기면
  //  그대로 얹힌다 — 단계별 기본 소품은 건드리지 않는다.
  //  그리는 순서는 `ROOM_Z`(뒤→앞)가 정한다. 목록에 넣은 순서와 무관하게
  //  항상 같은 앞뒤 관계로 겹치게 하려는 것이다.
  //
  //  (viewBox를 넓게 잡고 CSS에서 전체 폭으로 슬라이스 → 네모 프레임 없이 열린 방)
  //  가운데(x 150~250)는 아바타가 서는 자리라 소품을 놓지 않는다.
  // ═══════════════════════════════════════════════════════════════
  // 창문 한 곳에서만 좌표를 정한다 — 튜토리얼 인트로(intro.js)의 둥근 사각 창과 같은 모양.
  // f* = 바깥 나무틀, i* = 유리(하늘이 보이는 안쪽), m* = 창살
  let roomUid = 0;   // 방을 여러 개 그릴 때 SVG id 가 겹치지 않게 붙이는 일련번호
  const WIN = {
    fx: 262, fy: 100, fw: 80, fh: 104, fr: 7,
    ix: 269, iy: 107, iw: 66, ih: 90,  ir: 5,
    mx: 302, my: 152, mw: 5,
  };

  // 시간대별 창밖 하늘 (한국시간 UTC+9 기준) — 아이폰 날씨 앱처럼 시간에 따라 변화
  function skyPhase(now) {
    const d = now || new Date();
    const utc = d.getTime() + d.getTimezoneOffset() * 60000;
    const h = new Date(utc + 9 * 3600000).getHours();
    if (h >= 5 && h < 8)   return 'dawn';    // 새벽/일출
    if (h >= 8 && h < 16)  return 'day';     // 낮
    if (h >= 16 && h < 19) return 'dusk';    // 노을
    if (h >= 19 && h < 21) return 'evening'; // 초저녁
    return 'night';                          // 밤
  }

  // 창 안쪽(하늘 + 천체) 그리기. skyId = 하늘 그라디언트의 id (호출마다 다르다)
  function skyView(phase, skyId) {
    const SKY = {
      dawn:    ['#5a5a92', '#f0a97a'],
      day:     ['#7fb8e8', '#cfe6f5'],
      dusk:    ['#7a4a86', '#f2915e'],
      evening: ['#3a3468', '#6a5a92'],
      night:   ['#20203c', '#3b3358'],
    }[phase] || ['#20203c', '#3b3358'];

    // 천체 좌표는 창 안쪽(WIN.ix~ / WIN.iy~)에 맞춰 둔 값이다.
    // 창 위치를 옮기면 여기도 같이 옮겨야 한다.
    let body = `<rect x="${WIN.ix}" y="${WIN.iy}" width="${WIN.iw}" height="${WIN.ih}" fill="url(#${skyId})"/>`;

    if (phase === 'day') {
      body += `<circle cx="316" cy="128" r="13" fill="#fff3b0"/><circle cx="316" cy="128" r="19" fill="#fff3b0" opacity="0.35"/>
        <ellipse cx="288" cy="150" rx="17" ry="7" fill="#fff" opacity="0.75"/>
        <ellipse cx="298" cy="146" rx="11" ry="6" fill="#fff" opacity="0.75"/>
        <ellipse cx="318" cy="176" rx="14" ry="6" fill="#fff" opacity="0.5"/>`;
    } else if (phase === 'dawn' || phase === 'dusk') {
      body += `<circle cx="302" cy="152" r="14" fill="#ffd08a"/><circle cx="302" cy="152" r="21" fill="#ffd08a" opacity="0.3"/>
        <ellipse cx="302" cy="170" rx="34" ry="7" fill="#ffb27a" opacity="0.35"/>
        <ellipse cx="286" cy="132" rx="15" ry="6" fill="#ffd9c0" opacity="0.55"/>`;
    } else {
      body += `<circle cx="318" cy="126" r="11" fill="#fff7e0"/><circle cx="312" cy="122" r="8.5" fill="url(#${skyId})" opacity="0.6"/>
        <circle cx="282" cy="124" r="1.5" fill="#fff"/><circle cx="292" cy="140" r="1.2" fill="#fff"/>
        <circle cx="278" cy="166" r="1.4" fill="#fff"/><circle cx="328" cy="166" r="1.1" fill="#fff"/>
        <circle cx="302" cy="114" r="1" fill="#fff"/><circle cx="316" cy="184" r="1.2" fill="#fff"/>`;
    }
    return { body, SKY };
  }

  // ─── 단계별 색 (벽 위/아래, 바닥 위/아래, 벽 이음새, 창틀) ───
  const ROOM_MAX = 5;
  // 시작 단계. 1단계는 거미줄·균열까지 있는 '텅 빈 골방' 이라 첫인상으로는 너무 휑하다 —
  // 기본은 선반과 러그가 놓인 2단계로 두고, 1단계는 아래로 내려갈 자리로 남겨 둔다.
  const ROOM_DEFAULT = 2;
  const ROOM_SKIN = {
    1: { wall: ['#a8977c', '#7a6a54'], floor: ['#6b4e30', '#452f1b'], seam: 'rgba(40,32,26,0.26)', frame: '#4a3a2c' },
    2: { wall: ['#cbb99c', '#9d8a70'], floor: ['#7d5c39', '#5a4026'], seam: 'rgba(40,32,26,0.22)', frame: '#4a3a2c' },
    3: { wall: ['#dcc9a8', '#ab967a'], floor: ['#8a663f', '#63472a'], seam: 'rgba(40,32,26,0.16)', frame: '#5c4632' },
    4: { wall: ['#e0d0bd', '#a89078'], floor: ['#7d5b46', '#523a2c'], seam: 'rgba(40,32,26,0.12)', frame: '#6b4f37' },
    5: { wall: ['#efe6f6', '#c0aed2'], floor: ['#6e4c56', '#46303a'], seam: 'rgba(90,70,110,0.14)', frame: '#8a6f4a' },
  };

  // ─── 소품 ───
  // 값은 「id → SVG 조각을 만드는 함수」. 인자 `k` 는 단계별 색(ROOM_SKIN 의 한 줄).
  // 새 소품을 늘리면 여기에 넣고 ROOM_Z 의 순서에도 끼워 넣는다.
  const ROOM_PROPS = {
    // 갈라진 금 — 허름한 단계에만
    crack: () => `
      <path d="M46,66 L56,96 L44,124 L56,158" stroke="rgba(40,32,26,0.28)" stroke-width="2.2" fill="none"/>
      <path d="M372,130 L362,160 L374,190" stroke="rgba(40,32,26,0.22)" stroke-width="1.8" fill="none"/>`,
    // 거미줄 (좌상단)
    cobweb: () => `
      <g stroke="rgba(255,255,255,0.16)" stroke-width="1.4" fill="none">
        <path d="M0,0 L52,52 M0,26 L52,52 M26,0 L52,52"/>
        <path d="M10,10 Q24,16 28,28 M20,20 Q34,26 38,38"/>
      </g>`,
    // 벽 아래쪽 나무 판자(굽도리)
    wainscot: k => `
      <rect x="0" y="168" width="400" height="72" fill="${k.frame}" opacity="0.55"/>
      <rect x="0" y="164" width="400" height="7" rx="2" fill="${k.frame}"/>
      <g stroke="rgba(0,0,0,0.18)" stroke-width="1.5">
        <line x1="50" y1="174" x2="50" y2="240"/><line x1="110" y1="174" x2="110" y2="240"/>
        <line x1="170" y1="174" x2="170" y2="240"/><line x1="230" y1="174" x2="230" y2="240"/>
        <line x1="350" y1="174" x2="350" y2="240"/>
      </g>`,
    // 천장 몰딩
    moulding: k => `
      <rect x="0" y="0" width="400" height="16" fill="${k.frame}"/>
      <rect x="0" y="16" width="400" height="5" fill="rgba(255,240,200,0.35)"/>`,
    // 벽 아치 부조 — 5단계 대저택.
    // 기둥 대신 부조로 둔 이유: 우측은 창문·커튼·화분이 이미 차 있어 기둥을 세울 자리가 없다
    arches: () => {
      let s = '';
      for (let x = 20; x < 400; x += 80) {
        s += `<path d="M${x},108 L${x},52 A26,26 0 0 1 ${x + 52},52 L${x + 52},108 Z"
          fill="rgba(255,255,255,0.16)" stroke="rgba(120,96,150,0.18)" stroke-width="2"/>`;
      }
      return s;
    },
    // 액자 (좌측 벽)
    frame: k => `
      <rect x="86" y="70" width="46" height="56" rx="3" fill="${k.frame}"/>
      <rect x="92" y="76" width="34" height="44" rx="2" fill="#cfd9e8"/>
      <path d="M92,120 L104,98 L114,110 L122,92 L126,120 Z" fill="#8aa87e"/>
      <circle cx="116" cy="88" r="5" fill="#f5e08a"/>`,
    // 벽 촛대
    candle: () => `
      <g>
        <rect x="46" y="96" width="6" height="16" rx="2" fill="#8a6f4a"/>
        <rect x="40" y="76" width="18" height="22" rx="3" fill="#f3ead6"/>
        <ellipse cx="49" cy="70" rx="5" ry="8" fill="#ffcf6a"/>
        <ellipse cx="49" cy="70" rx="11" ry="15" fill="#ffcf6a" opacity="0.22"/>
        <rect x="366" y="96" width="6" height="16" rx="2" fill="#8a6f4a"/>
        <rect x="360" y="76" width="18" height="22" rx="3" fill="#f3ead6"/>
        <ellipse cx="369" cy="70" rx="5" ry="8" fill="#ffcf6a"/>
        <ellipse cx="369" cy="70" rx="11" ry="15" fill="#ffcf6a" opacity="0.22"/>
      </g>`,
    // 낡은 선반 + 약병 (좌측)
    shelf: k => `
      <rect x="24" y="176" width="92" height="7" rx="2" fill="${k.frame}"/>
      <rect x="38" y="152" width="13" height="24" rx="4" fill="#5f7a6a"/>
      <rect x="60" y="158" width="12" height="18" rx="5" fill="#7a5f6a"/>
      <rect x="82" y="148" width="12" height="28" rx="4" fill="#6a6a4a"/>`,
    // 책장 (좌측 바닥까지)
    bookshelf: k => `
      <rect x="12" y="118" width="86" height="122" rx="4" fill="${k.frame}"/>
      <rect x="18" y="124" width="74" height="110" fill="rgba(0,0,0,0.28)"/>
      <g>
        <rect x="22" y="128" width="9" height="32" fill="#a8556a"/><rect x="33" y="132" width="8" height="28" fill="#5f7a9a"/>
        <rect x="43" y="126" width="10" height="34" fill="#6a8a5f"/><rect x="55" y="134" width="8" height="26" fill="#c08a4a"/>
        <rect x="65" y="130" width="9" height="30" fill="#8a6a9a"/>
        <rect x="22" y="172" width="8" height="30" fill="#7a9a8a"/><rect x="32" y="176" width="10" height="26" fill="#b06a6a"/>
        <rect x="44" y="170" width="9" height="32" fill="#5f6a9a"/><rect x="55" y="178" width="8" height="24" fill="#9a8a4a"/>
      </g>
      <rect x="18" y="162" width="74" height="6" fill="${k.frame}"/>
      <rect x="18" y="204" width="74" height="6" fill="${k.frame}"/>`,
    // 화분 (우측 창 아래)
    plant: () => `
      <path d="M356,240 L352,214 L382,214 L378,240 Z" fill="#a86a4a"/>
      <rect x="350" y="208" width="34" height="9" rx="3" fill="#bd7a56"/>
      <g fill="#6f9a63">
        <ellipse cx="358" cy="196" rx="8" ry="14" transform="rotate(-24 358 196)"/>
        <ellipse cx="374" cy="196" rx="8" ry="14" transform="rotate(24 374 196)"/>
        <ellipse cx="366" cy="188" rx="7" ry="16"/>
      </g>`,
    // 창문 커튼
    curtain: () => `
      <rect x="${WIN.fx - 14}" y="${WIN.fy - 12}" width="${WIN.fw + 28}" height="7" rx="3" fill="#8a6f4a"/>
      <path d="M${WIN.fx - 12},${WIN.fy - 8} L${WIN.fx + 12},${WIN.fy - 8} L${WIN.fx + 6},${WIN.fy + WIN.fh + 8}
        Q${WIN.fx - 2},${WIN.fy + WIN.fh + 2} ${WIN.fx - 12},${WIN.fy + WIN.fh + 8} Z" fill="#9a5f72"/>
      <path d="M${WIN.fx + WIN.fw - 12},${WIN.fy - 8} L${WIN.fx + WIN.fw + 12},${WIN.fy - 8}
        L${WIN.fx + WIN.fw + 12},${WIN.fy + WIN.fh + 8}
        Q${WIN.fx + WIN.fw + 2},${WIN.fy + WIN.fh + 2} ${WIN.fx + WIN.fw - 6},${WIN.fy + WIN.fh + 8} Z" fill="#9a5f72"/>
      <g stroke="rgba(0,0,0,0.16)" stroke-width="2" fill="none">
        <path d="M${WIN.fx - 4},${WIN.fy - 6} L${WIN.fx + 1},${WIN.fy + WIN.fh}"/>
        <path d="M${WIN.fx + WIN.fw + 4},${WIN.fy - 6} L${WIN.fx + WIN.fw - 1},${WIN.fy + WIN.fh}"/>
      </g>`,
    // 창틀 황금 장식
    goldTrim: () => `
      <rect x="${WIN.fx - 4}" y="${WIN.fy - 4}" width="${WIN.fw + 8}" height="${WIN.fh + 8}" rx="10"
        fill="none" stroke="#d9b45f" stroke-width="3"/>
      <circle cx="${WIN.fx + WIN.fw / 2}" cy="${WIN.fy - 10}" r="7" fill="#d9b45f"/>
      <circle cx="${WIN.fx + WIN.fw / 2}" cy="${WIN.fy - 10}" r="3" fill="#fff2c4"/>`,
    // 작은 러그
    rugSmall: () => `
      <ellipse cx="200" cy="290" rx="96" ry="26" fill="#8a5f6a" opacity="0.75"/>
      <ellipse cx="200" cy="290" rx="76" ry="19" fill="none" stroke="rgba(255,235,205,0.4)" stroke-width="2"/>`,
    // 큰 카펫
    rugBig: () => `
      <ellipse cx="200" cy="288" rx="150" ry="38" fill="#8e3f4e"/>
      <ellipse cx="200" cy="288" rx="150" ry="38" fill="none" stroke="#d9b45f" stroke-width="3"/>
      <ellipse cx="200" cy="288" rx="120" ry="28" fill="none" stroke="#d9b45f" stroke-width="2" opacity="0.7"/>
      <ellipse cx="200" cy="288" rx="60" ry="14" fill="#a04d5c"/>`,
    // 바닥 마법진
    circle: () => `
      <g fill="none" stroke="#cba8f0" stroke-width="2" opacity="0.75">
        <ellipse cx="200" cy="288" rx="104" ry="26"/>
        <ellipse cx="200" cy="288" rx="72" ry="18"/>
        <path d="M96,288 L200,270 L304,288 L200,306 Z"/>
      </g>
      <g fill="#e6d0ff" opacity="0.85">
        <circle cx="96" cy="288" r="3"/><circle cx="304" cy="288" r="3"/>
        <circle cx="200" cy="270" r="3"/><circle cx="200" cy="306" r="3"/>
      </g>`,
    // 샹들리에 (천장 · 아바타 머리 위를 피해 위쪽에만)
    chandelier: () => `
      <line x1="200" y1="0" x2="200" y2="22" stroke="#8a6f4a" stroke-width="3"/>
      <ellipse cx="200" cy="28" rx="46" ry="9" fill="none" stroke="#d9b45f" stroke-width="4"/>
      <g fill="#ffcf6a">
        <rect x="162" y="16" width="6" height="13" rx="2" fill="#f3ead6"/><ellipse cx="165" cy="12" rx="4" ry="6"/>
        <rect x="197" y="14" width="6" height="15" rx="2" fill="#f3ead6"/><ellipse cx="200" cy="9" rx="4" ry="6"/>
        <rect x="232" y="16" width="6" height="13" rx="2" fill="#f3ead6"/><ellipse cx="235" cy="12" rx="4" ry="6"/>
      </g>
      <ellipse cx="200" cy="24" rx="62" ry="24" fill="#ffcf6a" opacity="0.16"/>
      <g fill="#ffe9a8" opacity="0.8">
        <circle cx="176" cy="38" r="2.5"/><circle cx="200" cy="42" r="2.5"/><circle cx="224" cy="38" r="2.5"/>
      </g>`,
  };

  // 그리는 순서(뒤 → 앞). 벽 → 창문 → 바닥 → 천장 순서로 겹친다.
  const ROOM_Z = [
    'wainscot', 'moulding', 'arches', 'crack', 'cobweb', 'frame', 'candle', 'bookshelf', 'shelf',
    '@window',
    'curtain', 'goldTrim', 'plant',
    '@floor',
    'rugSmall', 'rugBig', 'circle',
    '@beam',
    'chandelier',
  ];

  // 단계별 기본 소품. 위 단계라고 아래 것을 다 물려받지는 않는다 —
  // 거미줄·균열은 방이 좋아지면 사라지고, 작은 러그는 큰 카펫으로 바뀐다.
  const ROOM_LEVELS = {
    1: ['crack', 'cobweb'],
    2: ['crack', 'shelf', 'rugSmall'],
    3: ['wainscot', 'shelf', 'frame', 'curtain', 'plant', 'rugSmall'],
    4: ['wainscot', 'moulding', 'bookshelf', 'shelf', 'frame', 'candle', 'curtain', 'plant', 'rugBig'],
    5: ['wainscot', 'moulding', 'arches', 'bookshelf', 'frame', 'candle', 'curtain', 'goldTrim',
        'plant', 'rugBig', 'circle', 'chandelier'],
  };

  // 마이 룸 배경 — 텔레포트해 온 연금술 공방이 단계에 따라 번듯해진다 (창문은 우측)
  // level : 1~5 (기본 1)
  // extra : 추가로 얹을 소품 id 목록 — 추후 '마이 룸 꾸미기' 가 쓸 자리
  // padBottom — **방을 아래로 더 그린다.** 스탯을 접었을 때 그 자리를 방 배경이
  // 이어받게 하려는 것이다.
  //
  // CSS 로 상자만 늘이면 안 된다: 이 그림은 `preserveAspectRatio="…slice"` 라
  // 늘어난 만큼 **좌우가 잘린다** (선반과 창문이 화면 밖으로 나간다).
  // 그래서 viewBox 자체를 늘리고 **바닥을 진짜로 더 그린다** — 원근선도 기울기를
  // 그대로 이어서 연장하므로 이음매가 생기지 않는다.
  function roomScene(level, extra, padBottom) {
    const pad = Math.max(0, Math.round(Number(padBottom) || 0));
    const H = 320 + pad;
    const lv = Math.min(ROOM_MAX, Math.max(1, Math.round(Number(level) || ROOM_DEFAULT)));
    // SVG 의 id 는 **문서 전체에서 공유된다.** 방을 두 개 이상 한 화면에 그리면
    // 뒤에 온 쪽이 앞 쪽의 그라디언트를 그대로 써 버려 단계별 색이 전부 같아진다
    // (5단계 미리보기를 나란히 놓다가 실제로 겪었다). 그래서 부를 때마다 꼬리표를 붙인다.
    const u = 'r' + (++roomUid);
    const ID = n => `${n}_${u}`;
    const k = ROOM_SKIN[lv];
    const want = new Set(ROOM_LEVELS[lv].concat(Array.isArray(extra) ? extra : []));

    const phase = skyPhase();
    const sky = skyView(phase, ID('skyDyn'));
    // 낮일수록, 방이 좋을수록 실내도 조금 밝게
    const warm = ((phase === 'day') ? 0.30 : (phase === 'dawn' || phase === 'dusk') ? 0.24 : 0.14)
      + (lv - 1) * 0.03;

    // 벽 이음새 — 돌벽은 아래 단계에서만 진하게 보인다
    const stone = `<g stroke="${k.seam}" stroke-width="2">
        <line x1="0" y1="60" x2="400" y2="60"/><line x1="0" y1="120" x2="400" y2="120"/><line x1="0" y1="180" x2="400" y2="180"/>
        <line x1="60" y1="0" x2="60" y2="60"/><line x1="210" y1="0" x2="210" y2="60"/><line x1="330" y1="0" x2="330" y2="60"/>
        <line x1="20" y1="60" x2="20" y2="120"/><line x1="140" y1="60" x2="140" y2="120"/><line x1="250" y1="60" x2="250" y2="120"/>
        <line x1="90" y1="120" x2="90" y2="180"/><line x1="360" y1="120" x2="360" y2="180"/>
      </g>`;

    // 창문 — 튜토리얼 인트로와 같은 둥근 사각 창
    const win = `
      <rect x="${WIN.fx}" y="${WIN.fy}" width="${WIN.fw}" height="${WIN.fh}" rx="${WIN.fr}" fill="${k.frame}"/>
      <rect x="${WIN.ix}" y="${WIN.iy}" width="${WIN.iw}" height="${WIN.ih}" rx="${WIN.ir}" fill="#2a2438"/>
      <clipPath id="${ID('winClip')}"><rect x="${WIN.ix}" y="${WIN.iy}" width="${WIN.iw}" height="${WIN.ih}" rx="${WIN.ir}"/></clipPath>
      <g clip-path="url(#${ID('winClip')})">${sky.body}</g>
      <line x1="${WIN.mx}" y1="${WIN.iy}" x2="${WIN.mx}" y2="${WIN.iy + WIN.ih}" stroke="${k.frame}" stroke-width="${WIN.mw}"/>
      <line x1="${WIN.ix}" y1="${WIN.my}" x2="${WIN.ix + WIN.iw}" y2="${WIN.my}" stroke="${k.frame}" stroke-width="${WIN.mw}"/>`;

    // 원근선은 **기울기를 그대로 이어서** 늘인다 (y=241 → 320 의 기울기를 H 까지)
    const ext = (x0, x1) => (x1 + (x1 - x0) * pad / 79).toFixed(1);
    const floor = `
      <rect x="0" y="235" width="400" height="${85 + pad}" fill="url(#${ID('floorG')})"/>
      <rect x="0" y="235" width="400" height="6" fill="${k.floor[1]}"/>
      <g stroke="${k.floor[1]}" stroke-width="2" opacity="0.55">
        <line x1="120" y1="241" x2="${ext(120, 70)}" y2="${H}"/><line x1="200" y1="241" x2="200" y2="${H}"/><line x1="280" y1="241" x2="${ext(280, 330)}" y2="${H}"/>
        <line x1="40" y1="241" x2="${ext(40, -40)}" y2="${H}"/><line x1="360" y1="241" x2="${ext(360, 440)}" y2="${H}"/>
      </g>
      <line x1="0" y1="280" x2="400" y2="280" stroke="${k.floor[1]}" stroke-width="1.5" opacity="0.5"/>`;

    // 창빛도 같은 기울기로 바닥 끝까지 (중간에서 끊기면 그 선이 그대로 보인다)
    const bY = WIN.iy + WIN.ih;
    const bW = 40 * (H - bY) / (320 - bY);
    const beam = `<path d="M${WIN.ix},${bY} L${WIN.ix + WIN.iw},${bY}
      L${(WIN.ix + WIN.iw + bW).toFixed(1)},${H} L${(WIN.ix - bW).toFixed(1)},${H} Z" fill="url(#${ID('beamG')})"/>`;

    const FIXED = { '@window': win, '@floor': floor, '@beam': beam };
    const body = ROOM_Z.map(id => FIXED[id] || (want.has(id) && ROOM_PROPS[id] ? ROOM_PROPS[id](k) : '')).join('');

    return `<svg class="room-svg" viewBox="0 0 400 ${H}" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMax slice" aria-hidden="true">
      <defs>
        <linearGradient id="${ID('wallG')}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="${k.wall[0]}"/><stop offset="1" stop-color="${k.wall[1]}"/>
        </linearGradient>
        <linearGradient id="${ID('floorG')}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="${k.floor[0]}"/><stop offset="1" stop-color="${k.floor[1]}"/>
        </linearGradient>
        <linearGradient id="${ID('skyDyn')}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="${sky.SKY[0]}"/><stop offset="1" stop-color="${sky.SKY[1]}"/>
        </linearGradient>
        <linearGradient id="${ID('beamG')}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="rgba(255,240,190,${warm})"/><stop offset="1" stop-color="rgba(255,240,190,0)"/>
        </linearGradient>
        <radialGradient id="${ID('vigG')}" cx="0.5" cy="${(0.42 * 320 / H).toFixed(3)}" r="0.78">
          <stop offset="0.4" stop-color="rgba(0,0,0,0)"/><stop offset="1" stop-color="rgba(12,8,20,${(0.46 - lv * 0.05).toFixed(2)})"/>
        </radialGradient>
      </defs>

      <rect x="0" y="0" width="400" height="240" fill="url(#${ID('wallG')})"/>
      ${lv <= 3 ? stone : ''}
      ${body}
      <rect x="0" y="0" width="400" height="${H}" fill="url(#${ID('vigG')})"/>
    </svg>`;
  }

  // NECK_CUT 은 커버리지 검사기(tools/checkavatar.js)도 읽는다 —
  // 파는 자리를 두 곳에 적어 두면 어긋나고, 어긋나는 순간 검사가 헛돈다
  // ⚠️ **몸무게가 만드는 변환을 밖에서도 물어볼 수 있어야 한다.**
  // `checkavatar` 가 「이 체형에서 허리는 화면의 몇 번째 줄인가」를 알아야 창을 잡는데,
  // 그동안 `HEAD_K_FAT` 같은 상수를 **검사기가 따로 베껴 두고** 있었다. 그래서
  // 여기 값을 고치자마자 창이 어긋나 **멀쩡한 옷 80벌이 「허리 살이 나왔다」로 잡혔다.**
  // 같은 수를 두 군데 적지 않는다 — 물어보게 한다.
  //   kx·ky 는 `bodyT` 의 가로·세로 배율, dy 는 머리가 따라 올라가는 몫이다
  function bodyMetrics(body) {
    const w = Math.max(0, Math.min(1, Number(body) || 0));
    const head = HEAD_H * lerpN(HEAD_K_SLIM, HEAD_K_FAT, w);
    const ky = 1 + (HEAD_H - head) / BODY_SPAN;
    return { w: w, kx: bodyScaleX(w), ky: ky, head: head, floorY: FLOOR_Y,
             dy: BODY_SPAN * (1 - ky), vb: { x: VB.x, y: VB.y, w: VB.w, h: VB.h } };
  }
  window.Avatar = { build, crouchBack, getItem, roomScene, hairIcon, TUNE_KEYS, neckCutBox, CLOTH_TOP_Y,
    partRatio, bodyScaleX, bodyMetrics, TUNE_MAX,
    ROOM_MAX, ROOM_DEFAULT, ROOM_PROPS, ROOM_LEVELS };
})();
